/*!40000 ALTER TABLE `learning_concept_blocks` DISABLE KEYS */;
INSERT INTO `learning_concept_blocks` VALUES (1,1,'INTRO',1,'주식을 산다는 것은 무엇을 사는 걸까요?','주식은 단순히 가격이 오르내리는 숫자가 아니라 회사에 대한 소유지분을 나타내는 증권입니다. 주식을 보유한 사람을 주주라고 하며, 주주는 회사의 성과와 가치 변화에 따라 이익을 얻을 수도 있고 손실을 볼 수도 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(2,1,'PARAGRAPH',2,'주식과 주주의 기본 관계','회사는 자금을 조달하기 위해 주식을 발행할 수 있습니다. 발행된 주식을 보유하면 그 회사의 주주가 됩니다. 주주의 권리는 주식 종류와 법령·정관에 따라 달라질 수 있지만, 보통주에는 일반적으로 의결권과 배당을 받을 수 있는 권리 등이 연결됩니다. 이 권리는 예금의 이자 지급 약속처럼 확정 수익을 보장하는 권리는 아닙니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(3,1,'TABLE',3,'주주와 채권자 비교',NULL,'{\"rows\": [[\"법적·경제적 관계\", \"회사의 소유지분 보유\", \"회사나 정부 등에 자금을 빌려준 관계\"], [\"주요 수익\", \"주가 상승에 따른 매매차익, 배당 등\", \"약정된 이자 또는 할인수익, 원금 상환 등\"], [\"기업 성과의 영향\", \"기업가치 변화에 직접 영향\", \"상환능력과 신용도 변화의 영향\"], [\"원금\", \"보장되지 않음\", \"발행자의 신용위험과 시장가격 변동 위험 존재\"]], \"headers\": [\"구분\", \"주주\", \"채권자\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(4,1,'EXAMPLE',4,'회사의 일부를 보유한다는 뜻','예를 들어 한 회사의 전체 주식이 100만 주이고 내가 1만 주를 보유한다면 단순 지분율은 1%입니다. 다만 실제 의결권 비율은 의결권 제한 주식, 자기주식 등 여러 요소에 따라 달라질 수 있으므로 ‘보유주식 수만 보면 모든 권리가 정확히 1%’라고 단정해서는 안 됩니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(5,1,'KEY_POINT',5,'주식에서 얻는 수익과 손실','주식 투자 수익은 주가가 오른 뒤 매도해 생기는 매매차익, 기업이 배당을 결정한 경우 받는 배당 등에서 발생할 수 있습니다. 반대로 주가가 하락하면 평가손실이나 실현손실이 생길 수 있고, 회사의 상황이 매우 나빠지면 투자금의 상당 부분 또는 전부를 잃을 가능성도 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(6,1,'WARNING',6,'주식은 원금 보장 상품이 아닙니다','기업이 좋은 회사라는 사실과 내가 산 가격에서 수익이 난다는 사실은 다릅니다. 기업가치와 시장가격은 계속 변하므로 주식을 보유했다는 이유만으로 원금이나 일정 수익이 보장되지 않습니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(7,1,'TIP',7,'추가로 알아보기','보통주와 우선주는 배당·의결권 등 권리 구조가 다를 수 있습니다. StockMate 초급에서는 ‘주식은 기업의 지분이며 권리와 위험을 함께 가진다’는 핵심을 먼저 이해하고 세부 종류는 이후 확장 학습으로 다룹니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(8,1,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"주식은 회사에 대한 소유지분을 나타내는 증권입니다.\", \"주식을 보유한 사람을 주주라고 합니다.\", \"주주와 채권자는 회사와 맺는 관계와 수익 구조가 다릅니다.\", \"주식의 원금과 수익은 보장되지 않습니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(9,2,'INTRO',1,'주가는 누가 정할까요?','주가는 회사가 매일 임의로 붙이는 가격표가 아닙니다. 시장 참가자가 사고 싶은 가격과 팔고 싶은 가격을 제시하고 실제 거래가 체결되면서 시장가격이 형성됩니다. 따라서 주가는 기업의 현재 상태뿐 아니라 앞으로의 실적과 위험에 대한 시장의 기대도 반영할 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(10,2,'PARAGRAPH',2,'매수·매도, 호가와 체결','매수 주문은 주식을 사려는 의사표시이고 매도 주문은 팔려는 의사표시입니다. 거래소에서 제시되는 사고 싶은 가격과 팔고 싶은 가격을 호가라고 부릅니다. 서로 거래 가능한 조건이 맞으면 체결이 이루어지고, 그 체결가격이 시장에서 관찰되는 가격이 됩니다. 실제 체결 규칙에는 가격우선·시간우선 등 거래소 규정이 적용됩니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(11,2,'TABLE',3,'시장가 주문과 지정가 주문',NULL,'{\"rows\": [[\"가격 지정\", \"가격을 직접 지정하지 않음\", \"원하는 가격을 지정\"], [\"핵심 목적\", \"가능한 상대 주문과 체결을 우선\", \"가격 조건을 우선\"], [\"주의점\", \"급격한 변동·호가 공백에서는 예상보다 불리한 가격에 체결될 수 있음\", \"지정 가격에 도달하지 않으면 체결되지 않을 수 있음\"]], \"headers\": [\"구분\", \"시장가 주문\", \"지정가 주문\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(12,2,'INFOGRAPHIC',4,'정보가 주가로 이어지는 흐름',NULL,'{\"steps\": [\"실적·공시·뉴스·금리 등 정보 발생\", \"투자자의 기대와 위험평가 변화\", \"매수·매도 주문 변화\", \"수요·공급과 호가 변화\", \"체결가격 변화\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(13,2,'EXAMPLE',5,'좋은 실적 뒤에 주가가 하락할 수도 있습니다','기업이 전년보다 좋은 실적을 발표했어도 시장이 그보다 훨씬 좋은 실적을 이미 기대했다면 발표 직후 매도 주문이 늘 수 있습니다. ‘실적이 좋아졌다’는 사실과 ‘시장의 예상보다 좋았다’는 판단은 서로 다릅니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(14,2,'KEY_POINT',6,'주가는 한 가지 이유로만 움직이지 않습니다','개별 기업 실적, 업종 전망, 금리와 환율, 수급, 시장 전체 분위기 등 여러 요인이 동시에 작용할 수 있습니다. 특정 하루의 주가 변화를 한 기사나 한 사건만으로 완전히 설명하는 것은 위험합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(15,2,'WARNING',7,'시장가 주문도 체결가격을 보장하지 않습니다','시장가 주문은 가격을 지정하지 않는 주문이므로 ‘현재 화면에 보이는 가격 그대로 반드시 체결된다’는 뜻이 아닙니다. 주문량과 호가 상황에 따라 여러 가격에서 체결될 수 있습니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(16,2,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"주가는 거래소에서 실제 거래가 체결되며 형성됩니다.\", \"호가는 사고 싶거나 팔고 싶은 가격이고, 조건이 맞으면 체결됩니다.\", \"시장가 주문은 가격을 지정하지 않고, 지정가 주문은 가격 조건을 지정합니다.\", \"새로운 정보는 투자자의 기대와 주문을 바꾸는 과정을 통해 주가에 반영될 수 있습니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(17,3,'INTRO',1,'주가가 더 비싸면 더 큰 회사일까요?','A기업 주가가 10만 원이고 B기업 주가가 2만 원이라고 해서 A기업의 시장가치가 반드시 더 큰 것은 아닙니다. 한 주의 가격뿐 아니라 시장에 상장된 주식 수가 얼마나 되는지도 함께 봐야 합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(18,3,'FORMULA',2,'시가총액의 기본 계산',NULL,'{\"formula\": \"시가총액 = 주가 × 상장주식 수\", \"description\": \"StockMate 문제에서는 이해를 위해 주가와 발행·상장주식 수를 곱하는 형태로 계산합니다. 실제 데이터 이용 시 제공기관의 주식 수 기준을 확인합니다.\"}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(19,3,'EXAMPLE',3,'두 기업 비교',NULL,'{\"cases\": [{\"name\": \"A기업\", \"price\": \"100,000원\", \"result\": \"약 1조 원\", \"shares\": \"1,000만 주\"}, {\"name\": \"B기업\", \"price\": \"20,000원\", \"result\": \"약 2조 원\", \"shares\": \"1억 주\"}], \"conclusion\": \"A기업의 한 주 가격은 더 높지만 B기업의 시가총액이 더 큽니다.\"}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(20,3,'TABLE',4,'주가와 시가총액',NULL,'{\"rows\": [[\"무엇을 나타내나\", \"한 주의 시장가격\", \"상장된 지분 전체의 시장가치 규모\"], [\"주요 활용\", \"현재 한 주의 가격 확인\", \"기업 규모·시장 내 비중 비교\"], [\"주의\", \"주식 수를 반영하지 않음\", \"부채·현금 등까지 포함한 기업가치(EV)와는 다름\"]], \"headers\": [\"구분\", \"주가\", \"시가총액\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(21,3,'KEY_POINT',5,'시가총액은 ‘기업 전체 경제가치’와 완전히 같지 않습니다','시가총액은 주주지분의 시장가치를 나타내는 지표입니다. 기업가치(EV)는 분석 목적에 따라 시가총액에 순부채 등을 조정해 계산하므로 시가총액과 같은 말로 사용하면 안 됩니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(22,3,'WARNING',6,'주가만 보고 기업 크기를 비교하지 마세요','주식분할처럼 한 주의 가격과 주식 수가 함께 조정되는 사건에서는 주가가 크게 바뀌어도 그 사건 자체만으로 회사의 전체 지분가치가 같은 비율로 변했다고 볼 수 없습니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(23,3,'TIP',7,'데이터 제공 기준을 확인하세요','한국거래소는 일반 시가총액 자료와 별도로 자기주식 제외 시가총액 자료도 제공합니다. 따라서 분석이나 API 구현에서는 어떤 주식 수 기준의 시가총액인지 명시하는 것이 좋습니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(24,3,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"시가총액은 한 주 가격이 아니라 전체 주식 수까지 반영합니다.\", \"기본 계산은 주가 × 상장주식 수입니다.\", \"주가가 높은 기업이 반드시 시가총액도 큰 것은 아닙니다.\", \"시가총액은 주주지분의 시장가치이며 기업가치(EV)와 구분합니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(25,4,'INTRO',1,'주식 수익은 주가 상승뿐일까요?','주주는 주가 상승에 따른 매매차익 외에도 회사가 배당을 결정한 경우 배당을 받을 수 있습니다. 다만 배당은 예금이자처럼 자동으로 확정되는 지급이 아니며 회사의 배당정책, 재무상태와 법적 요건 등에 따라 달라질 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(26,4,'PARAGRAPH',2,'배당은 주주에게 가치를 분배하는 방식입니다','회사는 벌어들인 이익과 과거에 쌓인 이익잉여금, 앞으로 필요한 투자자금과 재무상태 등을 고려해 배당을 결정할 수 있습니다. 따라서 ‘이번 해 순이익의 일정 비율이 무조건 배당된다’고 생각하면 안 됩니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(27,4,'FORMULA',3,'배당수익률의 기본 이해',NULL,'{\"formula\": \"배당수익률 = 주당배당금 ÷ 기준 주가 × 100\", \"description\": \"어떤 기간의 배당금과 어떤 주가를 기준으로 계산했는지에 따라 값이 달라질 수 있으므로 데이터 제공 기준을 확인합니다.\"}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(28,4,'TABLE',4,'매매차익과 배당',NULL,'{\"rows\": [[\"발생 원인\", \"매수가와 매도가의 차이\", \"회사의 배당 결정\"], [\"확정 시점\", \"매도해 손익이 실현될 때\", \"배당 절차와 지급 조건에 따라\"], [\"지속성\", \"주가 변동에 따라 달라짐\", \"기업 이익·현금흐름·배당정책에 따라 달라짐\"]], \"headers\": [\"구분\", \"매매차익\", \"배당\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(29,4,'EXAMPLE',5,'배당수익률 예시','주가 20,000원을 기준으로 연간 주당배당금이 600원이라면 단순 배당수익률은 3%입니다. 이후 주가가 15,000원으로 내려가면 같은 600원 기준 수익률은 4%가 되므로 ‘수익률이 높아졌다 = 기업이 더 좋아졌다’고 단정할 수 없습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(30,4,'WARNING',6,'높은 배당수익률만 보고 좋은 투자라고 판단하지 마세요','배당금이 그대로인데 주가가 급락해서 배당수익률이 높아질 수 있고, 이익과 현금흐름이 악화되면 다음 배당은 줄거나 없어질 수 있습니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(31,4,'TIP',7,'배당기준일과 실제 권리는 공시를 확인하세요','배당을 받을 권리가 정해지는 기준일과 지급일은 회사 공시와 관련 제도를 확인해야 합니다. StockMate 초급에서는 날짜 계산보다 배당의 경제적 의미를 중심으로 학습합니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(32,4,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"배당은 회사가 주주에게 가치를 분배하는 방식 중 하나입니다.\", \"배당은 자동으로 보장되거나 매년 같은 금액이 지급되는 것이 아닙니다.\", \"배당수익률은 주당배당금과 기준 주가의 관계입니다.\", \"배당수익률이 높다는 사실만으로 투자 매력을 확정할 수 없습니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(33,5,'INTRO',1,'거래가 얼마나 활발했는지는 무엇으로 볼까요?','주가는 한 주의 가격 수준과 방향을 보여주지만 그 움직임에 얼마나 많은 거래가 동반됐는지는 알려주지 않습니다. 일정 기간 실제 거래된 수량을 나타내는 거래량은 시장 참여 정도를 살펴보는 가장 기본적인 정보 중 하나입니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(34,5,'PARAGRAPH',2,'거래량과 거래대금','거래량은 일정 기간 체결된 주식 수량의 합입니다. 거래대금은 각 체결에서 거래가격과 수량을 곱한 금액을 합산한 값입니다. 따라서 ‘현재 주가 × 하루 거래량’은 개념을 설명하는 단순 근사 예시일 뿐 실제 거래대금과 정확히 같다고 보면 안 됩니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(35,5,'FORMULA',3,'거래대금의 구조',NULL,'{\"formula\": \"거래대금 = 각 체결가격 × 각 체결수량의 합\", \"description\": \"여러 가격에서 체결되므로 하루 거래대금은 모든 체결금액을 합산해 계산합니다.\"}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(36,5,'TABLE',4,'가격과 거래량을 함께 볼 때',NULL,'{\"rows\": [[\"상승\", \"증가\", \"상승 구간에 참여가 커졌는지 확인\"], [\"상승\", \"감소\", \"가격은 오르지만 참여 강도가 약해지는지 확인\"], [\"하락\", \"증가\", \"하락 과정에서 거래 참여가 커졌는지 확인\"], [\"하락\", \"감소\", \"조정 과정에서 거래가 줄어드는지 확인\"]], \"headers\": [\"가격 움직임\", \"거래량 변화\", \"초급에서 볼 수 있는 점\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(37,5,'EXAMPLE',5,'절대 수치보다 평소와 비교하기','평소 하루 10만 주가 거래되던 종목이 특정 날 100만 주 거래됐다면 ‘100만 주’라는 숫자 자체보다 평소보다 약 10배 늘었다는 변화가 더 유용할 수 있습니다. 종목마다 평소 거래규모가 크게 다르기 때문입니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(38,5,'KEY_POINT',6,'거래량은 방향이 아니라 활동량을 보여줍니다','거래량이 크다는 것은 매수와 매도가 활발하게 맞붙어 거래가 많이 성사됐다는 뜻입니다. 거래량만으로 어느 쪽이 ‘무조건 우세하다’고 결론내리기보다 가격 위치, 추세, 캔들 등과 함께 봅니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(39,5,'WARNING',7,'거래량 증가 = 주가 상승이라는 공식은 없습니다','급락하는 날에도 많은 거래가 발생하면 거래량은 크게 늘 수 있습니다. 가격·거래량 조합은 기술적 분석의 참고 근거이지 미래 가격을 보장하는 규칙이 아닙니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(40,5,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"거래량은 거래된 주식 수량, 거래대금은 체결금액의 합입니다.\", \"현재 거래량은 종목의 평소 거래량과 비교하는 것이 유용합니다.\", \"거래량은 시장 참여 정도를 보여주며 가격 방향을 단독으로 확정하지 않습니다.\", \"가격과 거래량의 관계는 보조적인 해석 도구로 사용합니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(41,6,'INTRO',1,'차트 막대 하나에는 네 가지 가격이 들어 있습니다','캔들차트는 일정 기간 동안의 가격 움직임을 압축해 보여줍니다. 일봉이면 하루, 주봉이면 한 주처럼 선택한 기간마다 한 개의 캔들이 만들어지며 시가·고가·저가·종가를 함께 확인할 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(42,6,'TABLE',2,'OHLC 네 가지 가격',NULL,'{\"rows\": [[\"시가(Open)\", \"해당 기간의 첫 체결가격\"], [\"고가(High)\", \"해당 기간 가장 높았던 체결가격\"], [\"저가(Low)\", \"해당 기간 가장 낮았던 체결가격\"], [\"종가(Close)\", \"해당 기간 마지막 체결가격\"]], \"headers\": [\"항목\", \"의미\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(43,6,'PARAGRAPH',3,'양봉과 음봉','종가가 시가보다 높으면 상승한 캔들, 종가가 시가보다 낮으면 하락한 캔들로 봅니다. 흔히 양봉·음봉이라는 표현을 사용합니다. 다만 상승과 하락을 표시하는 색상은 국가·차트 서비스·사용자 설정에 따라 다를 수 있으므로 색만 외우기보다 시가와 종가의 관계를 확인해야 합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(44,6,'TABLE',4,'세 가지 기본 추세',NULL,'{\"rows\": [[\"상승 추세\", \"고점과 저점이 전반적으로 높아지는 흐름\"], [\"하락 추세\", \"고점과 저점이 전반적으로 낮아지는 흐름\"], [\"횡보\", \"일정 범위 안에서 방향성이 뚜렷하지 않은 흐름\"]], \"headers\": [\"추세\", \"대표적인 가격 구조\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(45,6,'EXAMPLE',5,'상승 추세에서도 음봉은 나올 수 있습니다','여러 주 동안 고점과 저점이 높아지고 있는 종목이 하루 하락해 음봉을 만들었다고 해서 즉시 전체 상승 추세가 끝났다고 할 수는 없습니다. 한 캔들은 해당 기간의 정보이고 추세는 여러 기간의 구조입니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(46,6,'KEY_POINT',6,'시간 단위에 따라 추세가 다를 수 있습니다','일봉에서는 상승 추세처럼 보여도 주봉에서는 장기 하락 중의 반등일 수 있습니다. 분석할 때 어떤 시간 단위를 기준으로 말하는지 함께 표시하면 해석이 더 명확해집니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(47,6,'WARNING',7,'캔들 하나나 색상 하나로 매매를 결정하지 마세요','캔들 패턴과 추세는 과거 가격을 요약한 정보입니다. 미래 가격을 확정적으로 예측하는 도구가 아니므로 거래량, 가격대, 기본정보 등 다른 근거와 함께 사용해야 합니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(48,6,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"캔들은 시가·고가·저가·종가를 한 번에 보여줍니다.\", \"양봉·음봉은 색상이 아니라 시가와 종가의 관계로 이해합니다.\", \"상승·하락·횡보 추세는 여러 기간의 고점과 저점 흐름으로 판단합니다.\", \"분석 시간 단위와 여러 근거를 함께 확인합니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(49,7,'INTRO',1,'재무제표는 기업을 숫자로 설명하는 보고서입니다','주가만 보면 시장이 기업을 얼마에 평가하는지는 알 수 있지만 기업이 실제로 얼마를 팔고, 얼마나 이익을 냈고, 어떤 자산과 부채를 가지고 있으며, 현금이 어떻게 움직였는지는 알기 어렵습니다. 이 정보를 체계적으로 제공하는 핵심 자료가 재무제표입니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(50,7,'TABLE',2,'초급에서 먼저 보는 세 축',NULL,'{\"rows\": [[\"손익계산서·포괄손익 관련 명세\", \"일정 기간 얼마를 벌고 어떤 비용이 발생했는가?\"], [\"재무상태표\", \"특정 시점에 어떤 자산·부채·자본을 보유하는가?\"], [\"현금흐름표\", \"일정 기간 실제 현금이 영업·투자·재무활동에서 어떻게 움직였는가?\"]], \"headers\": [\"보고서\", \"핵심 질문\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(51,7,'PARAGRAPH',3,'매출액·영업이익·당기순이익','매출액은 재화나 서비스를 제공하며 발생한 수익 규모를 보여주는 대표 항목입니다. 영업이익은 회사의 주된 영업활동에서 매출과 관련 비용 등을 반영한 이익이고, 당기순이익은 금융손익·법인세 등 영업 외 요소까지 반영한 최종 손익입니다. 실제 표시 항목과 명칭은 기업·기준에 따라 달라질 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(52,7,'FORMULA',4,'재무상태표의 기본 관계',NULL,'{\"formula\": \"자산 = 부채 + 자본\", \"description\": \"자산은 회사가 통제하는 경제적 자원, 부채는 갚아야 할 의무, 자본은 자산에서 부채를 차감한 잔여지분으로 이해합니다.\"}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(53,7,'EXAMPLE',5,'매출은 늘었는데 이익은 줄 수 있습니다','매출이 100억 원에서 120억 원으로 늘어도 원재료비·인건비·마케팅비 등 비용이 더 크게 늘면 영업이익은 감소할 수 있습니다. 따라서 ‘매출 증가 = 이익 증가’로 자동 연결하면 안 됩니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(54,7,'KEY_POINT',6,'완전한 재무제표에는 더 많은 정보가 있습니다','초급에서는 이해하기 쉬운 세 축을 먼저 보지만 완전한 재무제표에는 자본변동표와 주석 등도 포함됩니다. 주석에는 회계정책, 세부 계정, 우발사항 등 숫자만으로 알기 어려운 중요한 정보가 담길 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(55,7,'WARNING',7,'서로 다른 기준의 숫자를 바로 비교하지 마세요','연결재무제표와 별도재무제표, 연간과 분기, 회계정책이 다른 숫자는 범위가 달라질 수 있습니다. 비교 전 기준과 기간을 확인해야 합니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(56,7,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"손익 관련 재무제표는 기간 성과, 재무상태표는 특정 시점의 자산·부채·자본, 현금흐름표는 현금의 흐름을 보여줍니다.\", \"매출액·영업이익·당기순이익은 서로 다른 단계의 성과입니다.\", \"자산 = 부채 + 자본의 기본 관계를 이해합니다.\", \"완전한 분석에서는 자본변동표와 주석, 비교 기준도 함께 확인합니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(57,8,'INTRO',1,'기업 전체 이익을 한 주 기준으로 보면?','기업 규모가 다르면 전체 순이익만으로 주당 성과를 비교하기 어렵습니다. EPS(Earnings Per Share, 주당순이익)는 기업의 이익을 보통주 한 주 기준으로 환산해 보여주는 대표적인 지표입니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(58,8,'FORMULA',2,'초급 문제에서 사용하는 단순식',NULL,'{\"formula\": \"EPS ≈ 당기순이익 ÷ 주식 수\", \"description\": \"StockMate 기초 계산 문제에서는 개념 이해를 위해 단순화한 식을 사용합니다. 문제에서 주어진 이익과 주식 수의 기준을 따릅니다.\"}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(59,8,'KEY_POINT',3,'실제 기본 EPS 산식은 더 엄밀합니다','회계기준상 기본 EPS는 일반적으로 보통주주에게 귀속되는 이익을 기간 중 가중평균 유통보통주식수로 나누는 방식으로 계산합니다. 연중에 신주발행이나 자사주 변동이 있으면 연말 주식 수 하나만 사용하는 것보다 기간별 주식 수를 반영하는 것이 적절하기 때문입니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(60,8,'EXAMPLE',4,'학습용 EPS 계산','문제에서 당기순이익 100억 원과 주식 수 1,000만 주가 주어지고 다른 조정이 없다고 가정하면 단순 EPS는 1,000원입니다. 실제 공시 수치와 직접 비교할 때는 보통주주 귀속이익·가중평균 주식 수 등 산식 기준을 확인해야 합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(61,8,'TABLE',5,'EPS를 움직이는 요인',NULL,'{\"rows\": [[\"이익 증가\", \"EPS 상승 방향\"], [\"주식 수 증가\", \"EPS 하락 방향\"], [\"주식 수 감소\", \"EPS 상승 방향\"], [\"적자 발생\", \"EPS가 음수가 될 수 있음\"]], \"headers\": [\"변화\", \"다른 조건이 같을 때 EPS에 미칠 수 있는 영향\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(62,8,'TIP',6,'희석 EPS','전환사채·주식매수선택권 등 잠재적 보통주가 실제 주식으로 전환될 경우 주당이익이 낮아질 가능성을 반영한 희석 EPS가 별도로 표시될 수 있습니다. 초급에서는 기본 EPS와 구분되는 지표라는 점만 알아두면 충분합니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(63,8,'WARNING',7,'EPS가 높다는 이유만으로 좋은 주식이라고 단정하지 마세요','EPS는 기업의 이익을 주당 기준으로 보여주지만 이익의 지속성, 부채, 성장성, 현재 주가 수준을 설명하지는 않습니다. 또한 일회성 이익이 EPS를 크게 높일 수 있습니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(64,8,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"EPS는 기업의 이익을 보통주 한 주 기준으로 보여주는 지표입니다.\", \"초급 문제에서는 당기순이익 ÷ 주식 수로 단순 계산할 수 있습니다.\", \"실제 기본 EPS는 보통주주 귀속이익과 가중평균 유통보통주식수를 사용합니다.\", \"주식 수와 이익의 변화 모두 EPS에 영향을 줄 수 있습니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(65,9,'INTRO',1,'현재 주가는 이익의 몇 배일까요?','PER(Price Earnings Ratio, 주가수익비율)은 주가를 EPS로 나눈 값입니다. 현재 시장가격이 한 주당 이익에 비해 어느 수준에서 거래되는지 보는 대표적인 밸류에이션 지표입니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(66,9,'FORMULA',2,'PER 계산',NULL,'{\"formula\": \"PER = 주가 ÷ EPS\", \"description\": \"주가 20,000원, EPS 2,000원이면 PER은 10배입니다. EPS와 주가의 기준 시점이 맞는지 확인해야 합니다.\"}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(67,9,'TABLE',3,'높고 낮은 PER의 가능한 해석',NULL,'{\"rows\": [[\"상대적으로 높은 PER\", \"높은 성장 기대, 낮은 현재 이익, 과도한 가격 기대 등\"], [\"상대적으로 낮은 PER\", \"낮은 가격, 높은 현재 이익, 성장 둔화·위험 우려 등\"]], \"headers\": [\"상태\", \"가능한 이유\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(68,9,'EXAMPLE',4,'낮은 PER이 ‘싸다’는 결론은 아닙니다','A기업의 PER이 5배, B기업이 15배라고 해도 A기업의 이익이 일회성 자산매각으로 크게 늘었거나 다음 해 급감할 것으로 예상된다면 5배라는 숫자가 지속 가능한 이익 수준을 반영하지 않을 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(69,9,'KEY_POINT',5,'비교 기준을 맞추세요','PER은 같은 업종이나 비슷한 사업모델·성장단계의 기업끼리 비교할 때 상대적으로 해석하기 쉽습니다. 경기민감 업종과 고성장 기술기업의 일반적인 이익 변동과 기대 수준이 다를 수 있기 때문입니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(70,9,'WARNING',6,'EPS가 0 이하이면 일반적인 PER 해석이 어렵습니다','적자로 EPS가 음수인 경우 PER을 단순 계산해 ‘마이너스 몇 배’로 가치평가하는 것은 일반적인 PER 해석과 맞지 않습니다. 데이터 서비스에서 N/A 등으로 표시하기도 합니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(71,9,'TIP',7,'후행 PER과 예상 PER을 구분하세요','과거 실적을 사용하는 PER과 향후 예상 이익을 사용하는 선행 PER은 기준이 다릅니다. 서로 다른 종류의 PER을 직접 비교하지 않도록 데이터 정의를 확인합니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(72,9,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"PER은 주가를 EPS로 나눈 이익 대비 가격 지표입니다.\", \"낮은 PER은 저평가 가능성뿐 아니라 성장 둔화나 위험을 반영할 수도 있습니다.\", \"적자나 일회성 이익이 큰 경우 PER 해석에 주의합니다.\", \"같은 기준·업종·기간의 PER을 비교합니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(73,10,'INTRO',1,'기업의 장부상 순자산을 한 주 기준으로 보면?','BPS(Book-value Per Share)는 장부상 자기자본을 한 주 기준으로 환산한 값으로 이해할 수 있습니다. PBR(Price Book-value Ratio)은 주가가 이 한 주당 장부가치의 몇 배 수준에서 거래되는지 보여줍니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(74,10,'FORMULA',2,'초급에서 사용하는 BPS와 PBR',NULL,'{\"formula\": [\"BPS ≈ 자기자본 ÷ 주식 수\", \"PBR = 주가 ÷ BPS\"], \"description\": \"실제 데이터 제공기관은 지배주주지분, 자기주식 처리, 기준 주식 수 등 세부 산식이 다를 수 있으므로 공시·API 기준을 확인합니다.\"}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(75,10,'EXAMPLE',3,'PBR 1배 예시','BPS가 20,000원이고 주가가 20,000원이면 PBR은 1배입니다. 이는 시장가격이 장부상 한 주당 순자산과 같은 숫자 수준이라는 뜻이지 ‘회사를 지금 청산하면 반드시 20,000원을 돌려받는다’는 뜻은 아닙니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(76,10,'KEY_POINT',4,'장부가치와 실제 경제가치는 다를 수 있습니다','재무제표의 자산은 회계기준에 따라 측정됩니다. 실제 매각가격과 다를 수 있고, 브랜드·인적자원·기술력처럼 장부에 충분히 나타나지 않는 요소가 있는 반면 가치가 떨어진 자산이 뒤늦게 손상 처리될 수도 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(77,10,'TABLE',5,'PBR 해석 시 함께 볼 것',NULL,'{\"rows\": [[\"ROE·수익성\", \"자기자본을 얼마나 효율적으로 사용하는지\"], [\"자산의 질\", \"장부상 자산이 실제로 수익을 만들 수 있는지\"], [\"업종 특성\", \"자산집약 산업과 무형자산 중심 산업의 구조 차이\"], [\"자본 변화\", \"증자·손상·이익 누적 등으로 BPS가 변할 수 있음\"]], \"headers\": [\"확인 항목\", \"이유\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(78,10,'WARNING',6,'PBR 1배 미만 = 무조건 저평가가 아닙니다','지속적인 적자, 낮은 ROE, 자산가치 훼손 우려가 있으면 시장이 장부가치보다 낮은 가격을 부여할 수 있습니다. 숫자의 원인을 확인해야 합니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(79,10,'TIP',7,'데이터 산식의 기준을 통일하세요','기업 비교에서 서로 다른 사이트의 BPS·PBR을 섞으면 지배주주지분·최근 분기 반영 여부 등 차이로 결과가 어긋날 수 있습니다. 한 분석에서는 같은 출처와 기준을 사용하는 것이 좋습니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(80,10,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"BPS는 장부상 자기자본을 한 주 기준으로 본 값입니다.\", \"PBR은 주가를 BPS로 나눈 장부가치 대비 가격 지표입니다.\", \"PBR 1배는 청산가치 보장을 뜻하지 않습니다.\", \"수익성·자산의 질·업종과 함께 PBR을 해석합니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(81,11,'INTRO',1,'주주의 자본을 얼마나 효율적으로 사용했을까요?','ROE(Return on Equity, 자기자본이익률)는 기업이 자기자본을 바탕으로 어느 정도의 이익을 냈는지 보는 대표적인 수익성 지표입니다. 같은 업종·조건이라면 높은 ROE는 자본 효율성이 높다는 신호일 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(82,11,'FORMULA',2,'초급 문제의 기본 계산',NULL,'{\"formula\": \"ROE ≈ 당기순이익 ÷ 자기자본 × 100\", \"description\": \"StockMate 기초 문제에서는 주어진 당기순이익과 자기자본으로 단순 계산합니다.\"}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(83,11,'KEY_POINT',3,'실제 분석에서는 평균 자기자본을 자주 사용합니다','이익은 일정 기간 동안 발생한 흐름이고 자기자본은 시점의 잔액이므로, 분석에서는 연초와 연말 자기자본의 평균 등 기간 평균 자본을 분모로 사용하는 경우가 일반적입니다. 데이터 제공기관마다 계산 방식이 다를 수 있어 산식을 확인해야 합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(84,11,'EXAMPLE',4,'ROE 계산 예시','당기순이익 100억 원, 문제에서 제시한 자기자본 1,000억 원을 단순 기준으로 사용하면 ROE는 10%입니다. 실제 비교에서는 평균 자기자본 여부와 연결·별도 기준을 맞춥니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(85,11,'TABLE',5,'높은 ROE가 나타나는 이유',NULL,'{\"rows\": [[\"영업 경쟁력 개선\", \"이익이 반복 가능한지\"], [\"자기자본 규모가 작음\", \"과도한 부채 사용 여부\"], [\"일회성 이익\", \"다음 기간에도 지속 가능한지\"], [\"자사주·자본 변화\", \"분모 변화가 ROE를 높였는지\"]], \"headers\": [\"가능한 원인\", \"확인할 점\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(86,11,'WARNING',6,'높은 ROE 자체가 투자 수익을 보장하지 않습니다','ROE가 높아도 주가가 이미 비싸거나 부채가 과도할 수 있습니다. 자기자본이 음수인 기업은 ROE 숫자 자체가 일반적인 의미를 잃을 수 있어 해석에 특히 주의합니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(87,11,'TIP',7,'PER과 함께 보면 역할이 다릅니다','ROE는 자본 효율성, PER은 이익 대비 시장가격을 봅니다. 중급에서는 두 지표를 함께 보면서 수익성과 가격 수준을 구분합니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(88,11,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"ROE는 자기자본 대비 이익 수준을 보는 수익성 지표입니다.\", \"초급에서는 당기순이익 ÷ 자기자본으로 단순 계산합니다.\", \"실제 분석에서는 평균 자기자본 등 산식 기준을 확인합니다.\", \"높은 ROE는 부채·일회성 이익·분모 변화의 영향도 점검합니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(89,12,'INTRO',1,'목돈을 맡길까요, 나누어 모을까요?','예금과 적금은 금융회사에 자금을 맡기고 약정된 조건에 따라 이자를 받는 대표적인 저축상품입니다. 둘 다 ‘금리가 몇 %인가’만 보기보다 돈을 넣는 방식과 실제 예치 기간을 함께 이해해야 합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(90,12,'TABLE',2,'예금과 적금의 기본 차이',NULL,'{\"rows\": [[\"납입 방식\", \"목돈을 일정 기간 예치\", \"일정 금액을 정기적으로 납입\"], [\"대표 목적\", \"이미 가진 목돈 운용\", \"기간 동안 목돈을 만들어 가기\"], [\"이자 계산의 핵심\", \"예치한 목돈과 기간\", \"각 납입금마다 실제 예치기간이 다름\"], [\"중도해지\", \"약정 만기 전 해지 조건 적용\", \"약정 만기 전 해지 조건 적용\"]], \"headers\": [\"구분\", \"정기예금\", \"정기적금\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(91,12,'EXAMPLE',3,'같은 연 3%라도 적금 이자가 단순히 원금 전체의 3%는 아닙니다','1년 적금에 매달 돈을 넣으면 첫 납입금은 비교적 오래 예치되지만 마지막 납입금은 짧은 기간만 예치됩니다. 따라서 전체 납입원금에 표시금리를 단순 곱해 예금과 같은 방식으로 비교하면 실제 이자와 달라질 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(92,12,'KEY_POINT',4,'만기와 중도해지','약정 기간을 채우면 만기가 되고 만기 전에 해지하면 상품 약관에 따른 중도해지이율이 적용될 수 있습니다. 우대금리도 조건을 충족하지 못하면 적용되지 않을 수 있으므로 가입 전 약관을 확인합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(93,12,'WARNING',5,'‘예금’이라는 이름만으로 예금자보호를 확정하지 마세요','예금자보호 여부와 보호 한도는 상품 종류, 금융회사, 제도 변경에 따라 달라질 수 있습니다. 실제 가입할 때는 해당 금융회사와 예금보험 관련 공식 안내의 최신 기준을 확인해야 합니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(94,12,'TIP',6,'세후 이자도 확인하세요','표시금리는 세전 기준인 경우가 많습니다. 실제 수령액은 세금, 우대조건, 가입기간과 납입방식에 따라 달라질 수 있습니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(95,12,'KEY_POINT',7,'투자상품과의 차이','일반적인 예·적금은 약정 이자 구조가 중심인 반면 주식·펀드·ETF 등 투자상품은 시장가격 변동에 따라 원금 손실이 발생할 수 있습니다. 단, 예·적금도 중도해지나 금융회사·제도 조건을 무시해서는 안 됩니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(96,12,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"정기예금은 목돈 예치, 정기적금은 정기적인 분할 납입이 기본입니다.\", \"적금은 납입 시점마다 실제 예치기간이 달라 표시금리만으로 예금과 단순 비교하기 어렵습니다.\", \"중도해지와 우대금리 조건을 확인합니다.\", \"예금자보호 여부·한도는 최신 공식 기준을 확인합니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(97,13,'INTRO',1,'채권은 발행자에게 자금을 빌려주는 증권입니다','정부·공공기관·기업 등은 자금을 조달하기 위해 채권을 발행할 수 있습니다. 투자자는 채권을 매수하면서 발행자에게 자금을 제공하고, 채권 조건에 따라 이자 또는 할인수익과 만기 원금 상환을 기대합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(98,13,'TABLE',2,'채권의 기본 요소',NULL,'{\"rows\": [[\"발행자\", \"돈을 빌리고 상환의무를 부담하는 주체\"], [\"액면가\", \"만기 상환의 기준이 되는 금액\"], [\"만기\", \"원금 상환이 예정된 시점\"], [\"쿠폰금리\", \"이표채에서 액면가를 기준으로 약정한 이자율\"], [\"시장가격\", \"만기 전 거래될 때 시장에서 형성되는 가격\"]], \"headers\": [\"요소\", \"의미\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(99,13,'KEY_POINT',3,'쿠폰금리와 시장수익률은 같은 말이 아닙니다','쿠폰금리는 채권 조건에 정해진 이자율이고, 시장수익률은 투자자가 현재 시장가격으로 채권을 매수했을 때 기대하는 수익률과 관련된 개념입니다. 채권 가격이 변하면 쿠폰금리가 그대로여도 시장수익률은 달라질 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(100,13,'PARAGRAPH',4,'고정금리 채권 가격과 시장금리','일반적인 고정금리 채권에서 시장금리가 상승하면 더 높은 금리를 제공하는 새 채권의 매력이 커집니다. 기존 낮은 쿠폰의 채권을 경쟁력 있게 팔려면 가격이 내려가는 방향의 압력을 받을 수 있습니다. 반대로 시장금리가 하락하면 기존 고정금리 채권 가격은 올라갈 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(101,13,'EXAMPLE',5,'무이표채도 있습니다','모든 채권이 정기적으로 이자를 지급하는 것은 아닙니다. 무이표채(제로쿠폰채)는 정기 쿠폰을 지급하지 않고 보통 액면가보다 낮은 가격에 발행·거래되어 만기에 액면가를 상환받는 차이에서 수익이 발생할 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(102,13,'TABLE',6,'대표적인 채권 위험',NULL,'{\"rows\": [[\"신용위험\", \"발행자가 이자나 원금을 약속대로 지급하지 못할 위험\"], [\"금리위험\", \"시장금리 변화로 기존 채권 가격이 움직이는 위험\"], [\"유동성위험\", \"원할 때 적정 가격에 매도하기 어려울 위험\"], [\"물가위험\", \"고정된 현금흐름의 실질 구매력이 물가상승으로 줄어들 위험\"]], \"headers\": [\"위험\", \"의미\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(103,13,'WARNING',7,'‘채권 = 원금 보장’으로 외우지 마세요','만기까지 보유하더라도 발행자가 부도나면 원금·이자를 받지 못할 수 있고, 만기 전에 시장에서 매도하면 매수가보다 낮은 가격에 팔 수 있습니다. 채권 종류와 조건마다 위험이 다릅니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(104,13,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"채권은 발행자에게 자금을 제공하고 약정된 현금흐름을 기대하는 증권입니다.\", \"고정금리 채권의 시장가격은 시장금리와 일반적으로 반대 방향으로 움직입니다.\", \"무이표채처럼 정기 쿠폰이 없는 채권도 있습니다.\", \"신용·금리·유동성·물가 위험을 함께 확인합니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(105,14,'INTRO',1,'여러 자산을 하나의 상품으로 투자하는 방법','펀드는 여러 투자자의 자금을 모아 정해진 투자목적에 따라 주식·채권 등 다양한 자산에 투자하는 집합투자 구조입니다. ETF(Exchange-Traded Fund)는 거래소에 상장되어 장중에 주식처럼 시장가격으로 거래되는 펀드입니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(106,14,'TABLE',2,'일반 펀드와 ETF의 대표적인 차이',NULL,'{\"rows\": [[\"거래 방식\", \"펀드 또는 판매사를 통한 가입·환매\", \"거래소에서 투자자끼리 장중 매매\"], [\"가격 기준\", \"보통 산정된 기준가격(NAV) 중심\", \"시장가격으로 체결\"], [\"장중 가격 변화\", \"주식처럼 실시간 체결하는 구조가 아님\", \"시장 수요·공급에 따라 실시간 변동\"], [\"원금 보장\", \"아님\", \"아님\"]], \"headers\": [\"구분\", \"일반 공모펀드\", \"ETF\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(107,14,'KEY_POINT',3,'NAV와 ETF 시장가격','NAV(순자산가치)는 펀드가 가진 자산가치에서 부채 등을 차감한 순자산을 기준으로 계산합니다. ETF는 거래소에서 시장가격으로 사고팔기 때문에 시장가격이 NAV보다 높으면 프리미엄, 낮으면 디스카운트 상태가 될 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(108,14,'EXAMPLE',4,'지수와 ETF 수익률이 완전히 같지 않을 수 있습니다','어떤 ETF가 특정 지수를 추종해도 보수·거래비용·세금·운용 방식 등의 영향으로 실제 ETF 수익률이 지수 수익률과 차이날 수 있습니다. 이를 추적오차라고 부릅니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(109,14,'KEY_POINT',5,'모든 ETF가 같은 위험을 갖는 것은 아닙니다','시장 전체를 추종하는 ETF, 특정 산업에 집중하는 ETF, 채권 ETF, 원자재 ETF 등 기초자산이 다릅니다. 레버리지·인버스 등 구조가 복잡한 상품은 일일 수익률 목표와 복리효과 때문에 장기 성과가 단순 배수와 달라질 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(110,14,'WARNING',6,'‘ETF = 자동 분산 = 안전’은 틀린 생각입니다','한 산업이나 소수 종목에 집중된 ETF는 분산효과가 제한적일 수 있고 기초자산 가격 하락, 시장가격과 NAV 괴리, 유동성 등 여러 위험이 있습니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(111,14,'TIP',7,'비용을 확인하세요','운용보수뿐 아니라 매매 수수료, 스프레드, 세금 등 실제 투자성과에 영향을 주는 비용이 있을 수 있습니다. 비교할 때는 동일한 기준의 총비용을 확인합니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(112,14,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"펀드는 여러 투자자의 자금을 모아 운용하는 구조입니다.\", \"ETF는 거래소에서 시장가격으로 장중 거래되는 펀드입니다.\", \"ETF 시장가격은 NAV보다 높거나 낮을 수 있습니다.\", \"지수형 ETF에는 추적오차가 있을 수 있고 상품별 위험구조가 다릅니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(113,15,'INTRO',1,'주가가 10% 올랐으면 내 투자수익률도 항상 10%일까요?','투자성과를 볼 때는 가격 변화뿐 아니라 배당처럼 투자 중 받은 현금, 수수료와 세금, 투자기간을 함께 봐야 합니다. 또한 여러 해의 수익률은 단순히 숫자를 더하는 방식으로 누적되지 않고 원금이 변한 상태에서 다음 수익률이 적용되는 복리 구조를 가집니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(114,15,'FORMULA',2,'기본 총수익률',NULL,'{\"formula\": \"총수익률 = (기말가치 - 기초투자금 + 기간 중 받은 현금수익) ÷ 기초투자금 × 100\", \"description\": \"중간 추가납입·인출이 없는 단순 상황의 기본식입니다. 배당 등 현금수익을 포함하면 단순 주가등락률과 달라질 수 있습니다.\"}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(115,15,'EXAMPLE',3,'주가수익과 배당을 함께 보기','10,000원에 산 주식이 1년 뒤 10,800원이 되었고 기간 중 200원의 현금배당을 받았다고 가정하면 단순 총수익은 1,000원입니다. 기초 10,000원 대비 약 10%의 총수익률이 됩니다. 거래비용과 세금은 별도로 반영해야 합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(116,15,'KEY_POINT',4,'복리는 수익 위에 다시 수익이 붙는 구조입니다','첫해 10% 수익 후 둘째 해 10% 수익이면 누적수익률은 20%가 아니라 21%입니다. 100이 110이 된 뒤 다시 10%가 적용되어 121이 되기 때문입니다. 반대로 +10% 뒤 -10%는 원금으로 돌아오지 않고 99가 됩니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(117,15,'FORMULA',5,'고정 수익률의 복리 누적',NULL,'{\"formula\": \"n기간 후 가치 = 시작가치 × (1 + 기간수익률)^n\", \"description\": \"매 기간 같은 수익률이고 중간 현금흐름이 없다는 단순 가정입니다. 실제 투자수익률은 기간마다 달라질 수 있습니다.\"}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(118,15,'KEY_POINT',6,'명목수익률과 실질수익률','계좌 금액이 늘어도 같은 기간 물가가 상승하면 구매력 기준 성과는 더 작을 수 있습니다. 물가를 반영한 실질수익률의 기본 관계는 (1+명목수익률) ÷ (1+물가상승률) - 1입니다. 수익률이 작을 때는 명목수익률에서 물가상승률을 뺀 값으로 근사하기도 합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(119,15,'WARNING',7,'수익률 비교에서는 기간과 현금흐름 기준을 맞추세요','한 달 수익률과 1년 수익률을 그대로 비교하거나 중간에 추가입금이 있었는데 단순 기초·기말 금액만 비교하면 성과가 왜곡될 수 있습니다. 실제 투자자는 수수료·세금도 최종 순수익에 영향을 받습니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(120,15,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"총수익률은 가격변화뿐 아니라 배당 등 현금수익을 포함해 볼 수 있습니다.\", \"여러 기간의 수익률은 복리로 누적됩니다.\", \"명목수익률과 물가를 반영한 실질수익률은 다릅니다.\", \"수수료·세금·중간 현금흐름과 비교기간을 함께 확인합니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(121,16,'INTRO',1,'가격이 크게 흔들리는 것과 손실이 확정된 것은 같은 말이 아닙니다','투자위험을 이해하려면 ‘현재 평가금액이 원금보다 낮다’, ‘매도해 손실이 확정됐다’, ‘가격이 크게 오르내린다’는 세 상황을 구분해야 합니다. 이들은 서로 관련되지만 같은 개념은 아닙니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(122,16,'TABLE',2,'평가손익과 실현손익',NULL,'{\"rows\": [[\"평가손익\", \"현재 시장가격으로 계산한 보유자산의 손익으로 아직 매도하지 않은 상태\"], [\"실현손익\", \"자산을 매도해 거래가 끝나면서 확정된 손익\"]], \"headers\": [\"구분\", \"의미\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(123,16,'KEY_POINT',3,'원금 손실','투자한 자금의 가치가 줄어 투자원금보다 낮아진 상태를 원금 손실로 이해할 수 있습니다. 보유 중 평가손실은 향후 가격에 따라 변할 수 있지만, 그렇다고 위험이 없어진 것은 아닙니다. 필요한 시점에 현금화해야 한다면 평가손실도 중요한 현실적인 위험입니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(124,16,'EXAMPLE',4,'50% 손실 후에는 100% 상승이 필요합니다','100만 원이 50% 하락하면 50만 원입니다. 여기서 50% 상승하면 75만 원에 불과합니다. 50만 원이 다시 100만 원이 되려면 50만 원이 늘어야 하므로 기준금액 대비 100% 상승이 필요합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(125,16,'PARAGRAPH',5,'변동성은 가격이 움직이는 정도를 나타냅니다','변동성은 가격이나 수익률이 시간에 따라 얼마나 크게 흔들리는지를 나타내는 개념입니다. 높은 변동성은 큰 상승 가능성과 큰 하락 가능성이 함께 나타날 수 있다는 뜻이지 ‘반드시 손실이 난다’는 뜻은 아닙니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(126,16,'KEY_POINT',6,'위험은 변동성만으로 설명되지 않습니다','투자기간, 필요한 현금화 시점, 신용위험, 유동성, 집중투자 여부 등도 투자위험에 영향을 줍니다. 같은 변동성이라도 당장 사용할 돈과 10년 뒤 사용할 돈이 체감하는 위험은 다를 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(127,16,'WARNING',7,'손실을 만회하려고 더 큰 위험을 자동으로 선택하지 마세요','손실이 커질수록 회복에 필요한 수익률이 커지지만 이를 이유로 레버리지나 과도한 집중투자를 선택하면 추가 손실 가능성도 커질 수 있습니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(128,16,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"평가손익은 보유 중, 실현손익은 매도 후 확정된 손익입니다.\", \"큰 손실일수록 원금 회복에 필요한 수익률은 더 커집니다.\", \"변동성은 가격의 흔들림 정도이며 손실과 같은 개념이 아닙니다.\", \"실제 위험은 투자기간·유동성·집중도 등 여러 요소와 함께 봅니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(129,17,'INTRO',1,'여러 종목을 사면 무조건 분산투자일까요?','분산투자는 투자자금을 여러 투자대상에 나누어 특정 기업이나 특정 위험요인에 대한 집중을 줄이는 방법입니다. 하지만 이름이 다른 종목을 여러 개 샀다는 사실만으로 충분한 분산이 이루어졌다고 볼 수는 없습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(130,17,'TABLE',2,'분산의 여러 층위',NULL,'{\"rows\": [[\"종목 분산\", \"여러 회사 주식\", \"개별기업 위험\"], [\"업종 분산\", \"반도체·금융·소비재 등\", \"특정 산업 위험\"], [\"자산 분산\", \"주식·채권·현금성 자산 등\", \"한 자산군의 위험\"]], \"headers\": [\"유형\", \"예시\", \"줄이고자 하는 집중\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(131,17,'EXAMPLE',3,'이름은 세 개지만 위험은 비슷할 수 있습니다','반도체 회사 두 곳과 반도체 산업 ETF를 보유하면 종목명은 세 개지만 반도체 업황이라는 공통 위험요인에 크게 노출될 수 있습니다. 따라서 ‘몇 종목인가’보다 ‘무슨 위험을 공유하는가’를 함께 봐야 합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(132,17,'KEY_POINT',4,'자산배분은 목적과 기간에서 시작합니다','곧 사용할 비상자금, 몇 년 뒤 사용할 자금, 장기 투자자금은 감당할 수 있는 가격변동이 다릅니다. 자산배분은 기대수익만 보고 결정하기보다 사용 시점, 손실 감당 능력, 유동성 필요를 함께 고려하는 과정입니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(133,17,'PARAGRAPH',5,'분산투자가 줄이기 쉬운 위험과 어려운 위험','한 회사의 문제처럼 개별기업에 국한된 위험은 여러 기업으로 나누어 투자하면 영향을 줄일 수 있습니다. 반면 금융위기·급격한 경기침체처럼 시장 전체를 흔드는 위험은 많은 종목이 함께 영향을 받아 분산만으로 완전히 제거하기 어렵습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(134,17,'WARNING',6,'분산투자는 원금손실 방지 보장이 아닙니다','적절한 분산은 손실 폭과 변동을 줄이는 데 도움을 줄 수 있지만 모든 시장 상황에서 손실을 막거나 수익을 보장하지는 않습니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(135,17,'TIP',7,'중급에서는 상관관계를 배웁니다','서로 다른 자산이 실제로 얼마나 비슷하거나 반대로 움직이는지는 상관관계와 연결됩니다. 초급에서는 ‘공통 위험요인이 적을수록 분산효과가 커질 가능성이 있다’는 직관을 먼저 익힙니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(136,17,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"분산투자는 특정 종목·업종·자산에 위험이 집중되는 것을 줄이려는 방법입니다.\", \"종목 수가 많아도 공통 위험요인이 크면 분산효과가 제한될 수 있습니다.\", \"자산배분은 투자목적·기간·유동성 필요와 연결합니다.\", \"분산투자는 손실을 완전히 제거하거나 수익을 보장하지 않습니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(137,18,'INTRO',1,'내 종목이 오른 것과 시장 전체가 오른 것은 다릅니다','특정 종목의 주가 변화에는 기업 자체의 실적과 뉴스뿐 아니라 금리·경기·정책 같은 시장 공통 요인, 반도체·자동차처럼 특정 업종에 영향을 주는 요인이 함께 작용할 수 있습니다. 비교 기준을 만들면 원인을 더 체계적으로 생각할 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(138,18,'PARAGRAPH',2,'시장지수는 여러 종목의 움직임을 요약합니다','시장지수는 정해진 방법에 따라 여러 종목의 가격 또는 시가총액 움직임을 하나의 지표로 요약합니다. KOSPI·KOSDAQ 관련 지수처럼 시장의 대표적인 흐름을 보는 지표가 있으며 지수마다 포함 종목과 산출 방식이 다릅니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(139,18,'KEY_POINT',3,'업종은 비슷한 사업을 하는 기업의 묶음입니다','반도체, 은행, 자동차처럼 비슷한 제품·서비스와 사업환경을 가진 기업을 업종 단위로 묶어 볼 수 있습니다. 같은 업종 기업은 원가구조·경기민감도·규제환경 등이 어느 정도 비슷해 재무지표의 상대 비교가 더 의미 있을 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(140,18,'TABLE',4,'비교 범위별 질문',NULL,'{\"rows\": [[\"개별 종목\", \"이 기업만의 실적·공시·경영 변화가 있었나?\"], [\"업종\", \"같은 산업 기업들이 공통으로 영향을 받는 사건이 있었나?\"], [\"시장 전체\", \"금리·경기·정책·위험선호 같은 전체 요인이 변했나?\"]], \"headers\": [\"범위\", \"질문\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(141,18,'EXAMPLE',5,'시장 상승 중 특정 종목만 하락','시장지수와 해당 업종이 모두 강한데 한 종목만 크게 하락한다면 기업 고유의 실적·공시·수급 문제를 추가로 확인할 이유가 생깁니다. 반대로 업종 전체가 함께 하락한다면 개별 기업만의 문제로 단정하기 어렵습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(142,18,'WARNING',6,'지수가 오른다고 모든 구성종목이 오르는 것은 아닙니다','지수는 여러 종목을 정해진 가중방식으로 합산한 값입니다. 일부 대형주의 영향이 클 수 있고 개별 종목은 지수와 다른 방향으로 움직일 수 있습니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(143,18,'TIP',7,'벤치마크를 명확히 하세요','‘시장보다 잘했다’고 말하려면 어떤 시장지수, 어떤 기간을 기준으로 비교했는지 명시해야 합니다. 업종 비교에서도 같은 기간과 같은 시장 범위를 사용하는 것이 좋습니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(144,18,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"시장지수는 여러 종목의 움직임을 정해진 방식으로 요약한 지표입니다.\", \"업종은 비슷한 사업환경의 기업을 묶어 비교하는 기준입니다.\", \"종목·업종·시장 전체를 나누어 보면 주가 변화의 원인을 더 체계적으로 살필 수 있습니다.\", \"지수와 모든 개별 종목이 항상 같은 방향으로 움직이는 것은 아닙니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(145,19,'INTRO',1,'이익이 나면 재무상태도 무조건 좋을까요?','기업이 이번 분기에 이익을 냈어도 과거에 쌓인 부채가 크거나 가까운 시기에 갚아야 할 채무가 많으면 재무부담이 클 수 있습니다. 반대로 부채가 있어도 안정적인 현금흐름과 충분한 상환능력이 있다면 같은 숫자의 부채가 다른 의미를 가질 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(146,19,'PARAGRAPH',2,'손익과 재무상태를 연결해서 보기','손익계산서는 일정 기간의 성과를 보여주고 재무상태표는 특정 시점의 자산·부채·자본을 보여줍니다. 당기 이익은 시간이 지나면서 이익잉여금 등 자본 변화에 영향을 줄 수 있지만 배당, 증자, 자사주 거래, 기타포괄손익 등 다른 요인도 자본을 바꿀 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(147,19,'FORMULA',3,'부채비율의 기본식',NULL,'{\"formula\": \"부채비율 = 부채 ÷ 자기자본 × 100\", \"description\": \"자기자본에 비해 부채 규모가 어느 정도인지 보는 기본 지표입니다. 자기자본이 매우 작거나 음수이면 비율 해석이 왜곡될 수 있습니다.\"}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(148,19,'TABLE',4,'재무안정성을 볼 때 함께 확인할 것',NULL,'{\"rows\": [[\"부채 규모와 구성\", \"단기·장기 채무와 금융부채의 부담을 구분\"], [\"이자 부담\", \"영업이익·현금흐름으로 이자를 감당할 수 있는지\"], [\"현금·유동자산\", \"가까운 시기의 지급능력 확인\"], [\"영업현금흐름\", \"본업에서 실제 현금을 만들고 있는지\"], [\"업종 특성\", \"설비·금융업 등 업종별 자금구조가 다름\"]], \"headers\": [\"항목\", \"확인 이유\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(149,19,'EXAMPLE',5,'부채비율 200%가 모든 업종에서 같은 의미는 아닙니다','대규모 설비투자가 필요한 산업과 자산이 가벼운 소프트웨어 기업은 일반적인 자금조달 구조가 다를 수 있습니다. 동일 숫자를 기계적으로 비교하기보다 같은 업종의 경쟁사와 과거 추세를 함께 보는 것이 적절합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(150,19,'KEY_POINT',6,'‘부채가 많다’보다 ‘감당 가능한가’를 묻습니다','부채는 성장투자에 활용될 수도 있지만 이익과 현금흐름이 약한 상태에서 이자·상환 부담이 커지면 위험이 커집니다. 만기구조와 금리조건까지 보면 재무안정성을 더 정확히 이해할 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(151,19,'WARNING',7,'부채비율 하나로 안전·위험을 확정하지 마세요','자기자본이 음수이거나 매우 작은 기업에서는 부채비율이 일반적인 비교지표로 기능하기 어렵습니다. 연결/별도 기준과 업종 차이도 확인해야 합니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(152,19,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"손익은 기간 성과, 재무상태는 특정 시점의 자금구조를 보여줍니다.\", \"부채비율은 자기자본 대비 부채 수준을 보는 지표입니다.\", \"재무안정성은 부채 숫자 하나보다 현금·이자부담·만기·업종을 함께 봅니다.\", \"자기자본이 음수이거나 기준이 다른 기업은 단순 비율 비교에 주의합니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(153,20,'INTRO',1,'흑자인데 왜 통장에 현금이 부족할까요?','회계는 거래가 경제적으로 발생한 시점에 수익과 비용을 인식하기 때문에 손익계산서의 이익과 실제 현금의 유입·유출 시점이 다를 수 있습니다. 이 차이를 이해하면 ‘순이익은 좋은데 왜 현금흐름이 나쁜가’ 같은 상황을 해석할 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(154,20,'PARAGRAPH',2,'순이익과 영업현금흐름','순이익은 회계기준에 따라 수익과 비용을 인식해 계산한 최종 손익이고, 영업현금흐름은 본업 관련 활동에서 실제 현금이 어떻게 움직였는지를 보여줍니다. 두 숫자가 장기간 크게 엇갈리면 원인을 확인할 필요가 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(155,20,'TABLE',3,'현금흐름을 볼 때 자주 확인하는 항목',NULL,'{\"rows\": [[\"매출채권\", \"매출은 인식했지만 고객에게 받을 현금이 늘었는지\"], [\"재고자산\", \"판매되지 않은 상품·원재료가 쌓이고 있는지\"], [\"매입채무\", \"지급 시점을 늦추며 현금을 일시적으로 보존했는지\"], [\"선수금·계약부채\", \"현금을 먼저 받았지만 아직 매출 인식 전인지\"]], \"headers\": [\"항목\", \"증가할 때 생각할 점\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(156,20,'EXAMPLE',4,'매출과 이익은 증가했는데 현금이 줄어든 경우','외상판매가 빠르게 늘면 매출과 이익은 증가할 수 있지만 고객에게 실제 현금을 받기 전까지 매출채권이 늘어 영업현금흐름이 약해질 수 있습니다. 이것이 곧 부실을 의미하는 것은 아니지만 회수기간과 연체 여부를 살펴야 합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(157,20,'KEY_POINT',5,'일회성 손익을 구분합니다','부동산·자회사 매각, 대규모 손상차손 환입처럼 반복되기 어려운 사건이 당기순이익을 크게 바꿀 수 있습니다. 본업에서 반복적으로 발생하는 이익과 일회성 요인을 나누어 보는 것이 이익의 질을 판단하는 핵심입니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(158,20,'KEY_POINT',6,'한 기간의 음수 현금흐름도 원인을 봐야 합니다','성장기업이 운전자본을 늘리거나 일시적인 재고 확보를 하면서 영업현금흐름이 악화될 수 있습니다. 반대로 장기간 순이익은 흑자인데 현금흐름이 계속 약하면 회수·재고·회계인식 문제를 더 깊게 확인할 필요가 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(159,20,'WARNING',7,'‘현금흐름이 음수 = 무조건 나쁜 기업’도 단순화입니다','현금흐름은 시점과 사업주기에 크게 영향을 받습니다. 여러 기간의 추세와 투자·재무현금흐름, 업종 특성을 함께 봐야 합니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(160,20,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"순이익과 현금흐름은 인식 시점 차이 때문에 다를 수 있습니다.\", \"매출채권·재고자산 등 운전자본 변화가 영업현금흐름에 영향을 줍니다.\", \"일회성 손익과 반복 가능한 본업 이익을 구분합니다.\", \"한 기간 숫자보다 여러 기간의 원인과 추세를 확인합니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(161,21,'INTRO',1,'싸 보이는 기업과 잘 버는 기업은 같은 질문이 아닙니다','PER은 이익 대비 현재 가격이 어느 정도인지, ROE는 자기자본으로 이익을 얼마나 효율적으로 냈는지를 봅니다. 두 지표는 서로 다른 질문에 답하기 때문에 함께 보면 ‘가격’과 ‘수익성’을 구분해 생각할 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(162,21,'TABLE',2,'PER과 ROE의 역할',NULL,'{\"rows\": [[\"PER\", \"현재 주가가 이익의 몇 배인가?\", \"적자·일회성 이익·성장성 차이에 민감\"], [\"ROE\", \"자기자본으로 얼마나 이익을 냈는가?\", \"부채·자본규모·일회성 이익에 영향\"]], \"headers\": [\"지표\", \"핵심 질문\", \"대표적인 한계\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(163,21,'EXAMPLE',3,'낮은 PER + 높은 ROE','같은 업종에서 A기업이 경쟁사보다 PER은 낮고 ROE는 높다면 가격 부담이 상대적으로 낮고 자본 효율성이 좋을 가능성을 검토할 수 있습니다. 하지만 시장이 실적 하락이나 법적 위험을 예상해 PER을 낮게 부여한 것일 수도 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(164,21,'KEY_POINT',4,'좋은 조합보다 ‘왜’ 그런지를 확인합니다','ROE가 높은 이유가 영업 경쟁력인지 높은 부채인지, PER이 낮은 이유가 저평가인지 이익 피크아웃 우려인지 확인해야 합니다. 숫자 조합은 질문을 만드는 도구이지 정답표가 아닙니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(165,21,'PARAGRAPH',5,'기간과 분모 기준을 맞춥니다','PER은 후행 실적 또는 예상 실적을 사용할 수 있고 ROE는 평균 자기자본 사용 여부가 다를 수 있습니다. 서로 다른 데이터 제공기관의 숫자를 섞기보다 동일 출처·기준의 데이터를 사용하는 것이 비교에 유리합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(166,21,'WARNING',6,'‘저PER·고ROE = 무조건 매수’ 공식은 없습니다','시장가격에는 성장성·재무위험·업종 전망·지배구조 등 다양한 정보가 반영됩니다. 투자 판단에는 현금흐름과 재무안정성, 뉴스·공시를 추가로 확인해야 합니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(167,21,'TIP',7,'여러 기간의 지속성을 보세요','한 해만 높은 ROE보다 여러 해 안정적으로 높은 ROE가 더 의미 있을 수 있고, PER도 이익이 크게 변하면 빠르게 달라집니다. 최근 한 시점의 숫자를 장기 특성으로 오해하지 않습니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(168,21,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"PER은 이익 대비 가격, ROE는 자기자본 수익성을 봅니다.\", \"두 지표를 함께 보더라도 원인을 확인해야 합니다.\", \"적자·일회성 이익·과도한 부채는 해석을 왜곡할 수 있습니다.\", \"같은 업종·기간·산식 기준으로 비교합니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(169,22,'INTRO',1,'많이 파는 것과 많이 남기는 것은 다릅니다','매출이 빠르게 늘면 외형이 성장한다고 볼 수 있지만 비용이 더 빠르게 늘면 본업의 수익성은 오히려 악화될 수 있습니다. 성장성과 수익성을 나누어 본 뒤 함께 연결하는 것이 중요합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(170,22,'FORMULA',2,'매출 성장률',NULL,'{\"formula\": \"매출 성장률 = (현재 매출 - 비교 매출) ÷ 비교 매출 × 100\", \"description\": \"전년 동기, 전분기 등 어떤 기간을 비교하는지 반드시 함께 표시합니다.\"}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(171,22,'FORMULA',3,'영업이익률',NULL,'{\"formula\": \"영업이익률 = 영업이익 ÷ 매출액 × 100\", \"description\": \"매출에서 본업의 영업이익이 어느 정도 남는지 보는 대표적인 수익성 비율입니다.\"}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(172,22,'TABLE',4,'성장성과 수익성 조합',NULL,'{\"rows\": [[\"증가\", \"증가\", \"규모와 본업 수익성이 함께 개선되는지\"], [\"증가\", \"감소\", \"원가·인건비·마케팅비 등 비용 부담 증가 여부\"], [\"감소\", \"증가\", \"저수익 사업 축소·가격 인상·비용 효율화 여부\"], [\"감소\", \"감소\", \"수요 둔화와 비용 부담이 동시에 나타나는지\"]], \"headers\": [\"매출 성장\", \"영업이익률\", \"확인할 점\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(173,22,'EXAMPLE',5,'기저효과','지난해 일회성 악재로 매출이 매우 낮았던 기업이 올해 정상 수준으로 회복하면 성장률이 매우 높게 보일 수 있습니다. 숫자는 크지만 장기 성장속도가 갑자기 높아졌다는 뜻은 아닐 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(174,22,'KEY_POINT',6,'계절성과 비교기간','성수기와 비수기가 뚜렷한 기업은 전분기 대비보다 전년 같은 분기와 비교하는 것이 더 유용할 수 있습니다. 분기와 연간 성장률을 함께 보면 일시적 변동을 구분하기 쉽습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(175,22,'WARNING',7,'한 번의 고성장을 지속 성장으로 확정하지 마세요','가격 인상, 환율, 인수합병, 일회성 대형계약처럼 매출을 일시적으로 키운 요인이 있을 수 있습니다. 매출 증가의 원인과 영업이익률의 동반 여부를 확인합니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(176,22,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"매출 성장률은 외형 성장, 영업이익률은 본업 수익성을 보여줍니다.\", \"매출과 이익률은 서로 다른 방향으로 움직일 수 있습니다.\", \"성장률은 비교기간·기저효과·계절성을 확인합니다.\", \"숫자 변화의 원인을 함께 봐야 지속성을 판단할 수 있습니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(177,23,'INTRO',1,'하루 크게 올랐다고 하락 추세가 끝난 걸까요?','추세는 한 번의 강한 캔들보다 여러 기간에 걸친 고점과 저점의 구조를 보는 개념입니다. 하락 중 하루 반등과 실제 구조적 전환을 구분하려면 이전 고점·저점과 주요 가격대를 함께 확인해야 합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(178,23,'PARAGRAPH',2,'추세 지속의 대표적인 구조','상승 추세에서는 고점과 저점이 전반적으로 높아지는 흐름, 하락 추세에서는 고점과 저점이 전반적으로 낮아지는 흐름을 대표적인 기준으로 봅니다. 실제 시장은 완벽한 계단 모양이 아니므로 ‘전반적인 구조’를 봅니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(179,23,'EXAMPLE',3,'단기 반등과 추세 전환','하락 추세 중 주가가 반등했지만 이전 주요 고점을 넘지 못하고 다시 새로운 저점을 만든다면 기존 하락 구조가 유지될 가능성이 큽니다. 반대로 저점이 높아지고 이전 고점 영역을 회복하면 전환 가능성을 추가로 검토할 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(180,23,'KEY_POINT',4,'전환은 복수의 근거로 확인합니다','고점·저점 구조 변화, 지지·저항 돌파, 거래량 변화, 이동평균선 방향 등 여러 근거가 함께 나타나는지 봅니다. 어느 하나도 미래를 보장하지 않지만 신호 하나보다 해석의 근거를 늘릴 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(181,23,'TABLE',5,'시간 단위에 따른 차이',NULL,'{\"rows\": [[\"일봉\", \"단기 상승 추세\"], [\"주봉\", \"장기 하락 추세 안의 반등\"], [\"월봉\", \"더 긴 기간에서는 횡보\"]], \"headers\": [\"시간 단위\", \"가능한 상황\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(182,23,'WARNING',6,'기술적 추세는 확률적 해석입니다','과거 가격구조가 비슷해도 미래 결과는 달라질 수 있습니다. 추세 전환을 ‘확정’이라는 표현으로 단정하기보다 근거가 강화되거나 약화된다고 표현하는 것이 적절합니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(183,23,'TIP',7,'분석 기준을 기록하세요','어느 기간의 고점·저점과 어떤 시간봉을 기준으로 추세를 판단했는지 기록하면 뒤에 결과를 복기하기 쉽습니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(184,23,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"추세는 여러 기간의 고점과 저점 구조로 봅니다.\", \"단기 반등과 구조적 추세 전환은 다릅니다.\", \"복수의 가격·거래량 근거를 함께 확인합니다.\", \"기술적 추세 분석은 미래 가격을 보장하지 않습니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(185,24,'INTRO',1,'주가가 반복해서 반응하는 가격대가 있습니다','기술적 분석에서는 과거에 하락이 멈추거나 매수 반응이 반복된 구간을 지지, 상승이 막히거나 매도 반응이 반복된 구간을 저항으로 표현합니다. 실제 시장에서는 정확한 한 가격보다 일정 범위의 ‘구간’으로 보는 편이 적절합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(186,24,'TABLE',2,'지지와 저항',NULL,'{\"rows\": [[\"지지 구간\", \"과거 매수 반응이나 하락 둔화가 나타난 가격대\", \"아래로 이탈한 뒤 회복하는지\"], [\"저항 구간\", \"과거 매도 반응이나 상승 둔화가 나타난 가격대\", \"위로 돌파한 뒤 유지하는지\"]], \"headers\": [\"구분\", \"대표적 의미\", \"깨졌을 때 확인\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(187,24,'PARAGRAPH',3,'돌파와 이탈','주가가 저항 구간을 넘어 거래되고 그 위에서 유지되는 흐름을 돌파, 지지 구간 아래로 내려가 유지되는 흐름을 이탈로 볼 수 있습니다. 장중 한 번 넘었다는 사실보다 종가와 이후 가격흐름을 함께 보는 경우가 많습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(188,24,'EXAMPLE',4,'실패한 돌파','장중 저항을 크게 넘었지만 종가가 다시 저항 아래로 내려오고 다음 거래일에도 약세가 이어지면 돌파가 유지되지 못했다고 해석할 수 있습니다. 반대로 돌파 후 되돌림에서 이전 저항 구간이 지지 역할을 하는지도 확인합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(189,24,'KEY_POINT',5,'거래량은 보조 근거입니다','저항 돌파 때 평소보다 거래량이 크게 늘면 많은 거래가 동반됐다는 근거가 되지만 성공을 보장하지는 않습니다. 돌파 뒤 재진입, 종가, 시장 상황을 함께 봐야 합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(190,24,'WARNING',6,'지지·저항은 물리적인 벽이 아닙니다','과거에 반응한 가격대가 미래에도 반드시 같은 역할을 한다는 보장은 없습니다. 너무 많은 선을 임의로 그으면 사후적으로 어떤 움직임도 설명할 수 있게 되는 편향이 생길 수 있습니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(191,24,'TIP',7,'역할 전환','과거 저항을 돌파한 뒤 그 구간이 조정에서 지지처럼 작용하거나, 깨진 지지 구간이 이후 반등에서 저항처럼 작용하는 현상을 참고하기도 합니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(192,24,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"지지와 저항은 과거 가격 반응이 반복된 구간입니다.\", \"돌파·이탈은 장중 한 순간보다 종가와 이후 유지 여부를 함께 봅니다.\", \"거래량은 보조 근거이며 성공을 보장하지 않습니다.\", \"지지·저항은 확정적 가격선이 아니라 기술적 분석의 참고 영역입니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(193,25,'INTRO',1,'같은 가격 상승이라도 거래량이 다르면 무엇을 더 볼 수 있을까요?','거래량은 가격 움직임에 실제 체결이 얼마나 많이 동반됐는지 보여줍니다. 중급에서는 단순 증가·감소를 넘어서 평소 거래량, 가격 위치, 돌파·조정 맥락을 함께 봅니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(194,25,'PARAGRAPH',2,'평균과 비교합니다','종목마다 평소 거래량 규모가 다르므로 ‘100만 주’처럼 절대 수치만 비교하기보다 최근 평균이나 중앙값 등 기준과 비교하는 것이 유용합니다. 어떤 기간을 평균으로 썼는지도 결과에 영향을 줍니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(195,25,'TABLE',3,'상황별 거래량 관찰',NULL,'{\"rows\": [[\"저항 돌파\", \"크게 증가\", \"돌파 과정에 많은 거래가 참여했는가?\"], [\"상승 후 조정\", \"감소\", \"매도 거래가 줄며 조정되는가?\"], [\"급락\", \"급증\", \"공포·손절·강제청산 등 거래가 집중됐는가?\"], [\"가격 상승\", \"지속 감소\", \"가격 상승과 참여 강도가 엇갈리는가?\"]], \"headers\": [\"상황\", \"거래량 변화\", \"확인할 질문\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(196,25,'EXAMPLE',4,'평소 대비 거래량','최근 20거래일 평균이 20만 주인데 저항 돌파일 150만 주가 거래됐다면 평소 대비 크게 늘어난 거래입니다. 하지만 이후 가격이 다시 저항 아래로 내려오면 ‘거래량이 많았으니 무조건 성공’이라는 결론은 틀릴 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(197,25,'KEY_POINT',5,'거래량은 매수량과 매도량을 따로 세는 숫자가 아닙니다','하나의 체결에는 매수자와 매도자가 동시에 존재합니다. 거래량 급증은 거래가 많이 성사됐다는 뜻이지 ‘매수량만 많았다’고 단순 표현하면 정확하지 않습니다. 가격이 어느 방향으로 형성됐는지를 함께 봅니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(198,25,'WARNING',6,'거래량 패턴은 시장·종목에 따라 다릅니다','뉴스 발표, 지수 편입, 옵션만기, 블록딜 등 특별한 사건이 거래량을 크게 바꿀 수 있습니다. 기술적 패턴만으로 원인을 확정하지 않습니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(199,25,'TIP',7,'거래대금도 보조적으로 볼 수 있습니다','주가 수준이 크게 다른 종목의 거래활동을 비교할 때는 거래량과 함께 거래대금을 보면 실제 거래된 금액 규모를 이해하는 데 도움이 됩니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(200,25,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"거래량은 종목의 평소 수준과 비교합니다.\", \"가격 위치와 맥락에 따라 같은 거래량 증가의 의미가 달라질 수 있습니다.\", \"거래량은 매수자와 매도자가 함께 만든 체결량입니다.\", \"거래량은 단독 매매신호가 아니라 보조 근거입니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(201,26,'INTRO',1,'가격의 작은 흔들림을 줄여 큰 흐름을 보는 방법','이동평균선은 일정 기간의 가격을 평균해 매 시점 다시 계산하고 그 값을 연결한 선입니다. 하루하루의 급격한 변동을 완화해 전반적인 방향을 보기 쉽게 하지만 이미 발생한 가격을 사용하므로 미래를 미리 알려주는 선은 아닙니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(202,26,'FORMULA',2,'단순이동평균(SMA)',NULL,'{\"formula\": \"n기간 SMA = 최근 n기간 가격의 합 ÷ n\", \"description\": \"보통 종가를 사용하지만 차트 설정에 따라 다른 가격을 사용할 수도 있습니다.\"}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(203,26,'KEY_POINT',3,'SMA와 EMA','SMA는 선택한 기간의 각 가격에 같은 가중치를 줍니다. EMA(지수이동평균)는 최근 가격에 더 큰 가중치를 주어 같은 기간의 SMA보다 최근 변화에 빠르게 반응하는 경향이 있습니다. 어떤 종류와 기간을 쓰는지는 분석 목적과 설정에 따라 달라집니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(204,26,'TABLE',4,'기간에 따른 일반적 특징',NULL,'{\"rows\": [[\"단기 이동평균\", \"최근 가격 변화에 빠르게 반응하지만 노이즈가 많을 수 있음\"], [\"중기 이동평균\", \"단기와 장기의 중간 성격\"], [\"장기 이동평균\", \"큰 추세를 완만하게 보여주지만 반응이 느림\"]], \"headers\": [\"구분\", \"특징\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(205,26,'EXAMPLE',5,'가격과 이동평균선의 관계','주가가 상승하는 이동평균선 위에서 유지되면 상승 흐름을 보조하는 근거로 볼 수 있습니다. 하지만 주가가 이동평균선을 한 번 아래로 내려갔다는 이유만으로 추세 전환을 확정하기보다 선의 기울기와 가격 구조를 함께 봅니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(206,26,'TIP',6,'정배열·역배열과 교차','단기·중기·장기선의 위치관계를 정배열·역배열이라고 표현하거나 단기선이 장기선을 상향·하향 교차하는 현상을 참고하기도 합니다. 기간 설정에 따라 신호 시점이 달라질 수 있습니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(207,26,'WARNING',7,'이동평균선은 후행합니다','이동평균선은 과거 가격으로 계산되므로 실제 가격 전환 뒤에 방향이 바뀌는 경우가 많습니다. 횡보장에서는 가격과 선이 반복적으로 교차해 거짓 신호가 늘 수 있습니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(208,26,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"이동평균선은 일정 기간 가격 평균을 연결한 선입니다.\", \"SMA는 동일 가중, EMA는 최근 가격에 더 큰 가중을 주는 방식입니다.\", \"가격 위치와 선의 기울기를 추세 보조근거로 봅니다.\", \"과거 가격 기반의 후행지표이므로 단독 신호로 확정하지 않습니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(209,27,'INTRO',1,'많이 올랐다는 것과 바로 떨어진다는 것은 다릅니다','RSI(Relative Strength Index)는 일정 기간의 상승폭과 하락폭을 비교해 가격 움직임의 상대적인 강도를 0에서 100 사이의 값으로 표현하는 모멘텀 지표입니다. 값이 높거나 낮다고 해서 다음 가격 방향이 자동으로 정해지는 것은 아닙니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(210,27,'FORMULA',2,'RSI의 기본 구조',NULL,'{\"formula\": [\"RS = 평균 상승폭 ÷ 평균 하락폭\", \"RSI = 100 - 100 ÷ (1 + RS)\"], \"description\": \"원래 Wilder 방식은 평균 상승·하락폭을 특정 방식으로 평활화합니다. 많은 차트에서 14기간이 대표 기본값으로 사용되지만 설정은 변경할 수 있습니다.\"}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(211,27,'TABLE',3,'흔히 쓰이는 참고 구간',NULL,'{\"rows\": [[\"70 초과\", \"과매수 구간으로 참고\", \"즉시 하락 확정 아님\"], [\"30~70\", \"중간 범위\", \"추세와 시장에 따라 의미 달라짐\"], [\"30 미만\", \"과매도 구간으로 참고\", \"즉시 상승 확정 아님\"]], \"headers\": [\"RSI\", \"일반적 표현\", \"주의\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(212,27,'EXAMPLE',4,'강한 상승 추세에서 높은 RSI','강한 상승 추세에서는 RSI가 70을 넘은 뒤에도 상당 기간 높은 수준을 유지하며 주가가 추가 상승할 수 있습니다. 따라서 ‘RSI 70 이상 = 무조건 매도’ 같은 규칙은 지나치게 단순합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(213,27,'KEY_POINT',5,'다이버전스','가격이 새로운 고점을 만들었지만 RSI가 이전 고점을 넘지 못하는 등 가격과 지표의 움직임이 어긋나는 현상을 다이버전스라고 부릅니다. 모멘텀 약화를 의심하는 보조근거가 될 수 있지만 반드시 반전을 뜻하지는 않습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(214,27,'WARNING',6,'RSI 기준은 종목과 추세에 따라 달라질 수 있습니다','일부 분석에서는 강한 상승장에서 40~80, 하락장에서 20~60처럼 범위를 다르게 관찰하기도 합니다. 70·30은 대표적 기준일 뿐 모든 시장에 동일하게 적용되는 법칙이 아닙니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(215,27,'TIP',7,'기간 설정을 비교할 때 고정하세요','14기간 RSI와 7기간 RSI는 민감도가 다릅니다. 기업이나 기간을 비교할 때는 RSI 설정값을 동일하게 유지해야 결과를 같은 기준으로 볼 수 있습니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(216,27,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"RSI는 상승과 하락의 상대적 강도를 0~100으로 나타냅니다.\", \"14기간과 70/30은 널리 쓰이는 기본 설정이지만 변경 가능합니다.\", \"과매수·과매도는 즉시 반전 신호가 아닙니다.\", \"다이버전스와 RSI는 다른 가격·거래량 근거와 함께 사용합니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(217,28,'INTRO',1,'두 이동평균의 간격으로 모멘텀 변화를 봅니다','MACD(Moving Average Convergence/Divergence)는 빠르게 반응하는 이동평균과 느리게 반응하는 이동평균의 차이를 이용해 추세와 모멘텀 변화를 관찰하는 지표입니다. 일반적인 구현에서는 지수이동평균(EMA)을 사용합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(218,28,'FORMULA',2,'대표적인 MACD 구조',NULL,'{\"formula\": [\"MACD선 = 12기간 EMA - 26기간 EMA\", \"시그널선 = MACD선의 9기간 EMA\", \"히스토그램 = MACD선 - 시그널선\"], \"description\": \"12·26·9는 매우 널리 쓰이는 기본값이지만 차트 설정에서 변경할 수 있으며 기간 단위는 사용한 차트 주기에 따라 달라집니다.\"}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(219,28,'TABLE',3,'기본적인 관찰',NULL,'{\"rows\": [[\"MACD선이 시그널선 위로 교차\", \"상승 모멘텀이 강화되는지 관찰\"], [\"MACD선이 시그널선 아래로 교차\", \"하락 모멘텀이 강화되는지 관찰\"], [\"MACD선이 0선 위\", \"빠른 EMA가 느린 EMA보다 높은 상태\"], [\"MACD선이 0선 아래\", \"빠른 EMA가 느린 EMA보다 낮은 상태\"]], \"headers\": [\"상황\", \"일반적으로 보는 점\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(220,28,'EXAMPLE',4,'횡보장에서 교차가 반복될 수 있습니다','가격이 좁은 범위에서 오르내리면 빠른 EMA와 느린 EMA가 자주 가까워지고 MACD선과 시그널선 교차도 반복될 수 있습니다. 이때 교차마다 추세 전환으로 보면 잦은 거짓 신호에 노출될 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(221,28,'KEY_POINT',5,'히스토그램은 두 선의 거리입니다','히스토그램이 커진다는 것은 MACD선과 시그널선의 간격이 벌어지고 있다는 뜻입니다. 히스토그램이 양수에서 줄어든다고 해서 즉시 가격이 하락한다는 뜻은 아니며 모멘텀 변화 가능성을 관찰하는 데 사용합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(222,28,'WARNING',6,'MACD도 과거 가격 기반의 후행지표입니다','가격이 이미 움직인 뒤 이동평균과 MACD가 반응할 수 있습니다. 교차 시점만으로 매수·매도를 확정하지 않고 추세, 가격대, 거래량과 함께 봅니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(223,28,'TIP',7,'설정값을 혼합 비교하지 마세요','12·26·9 MACD와 다른 설정의 MACD는 민감도가 다릅니다. 동일한 종목을 비교하더라도 설정이 다르면 신호 시점이 달라질 수 있습니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(224,28,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"MACD는 빠른 EMA와 느린 EMA의 차이를 이용합니다.\", \"시그널선은 MACD선을 평활화한 선이고 히스토그램은 두 선의 차이입니다.\", \"12·26·9는 대표 설정이지만 절대 규칙이 아닙니다.\", \"MACD는 후행성이 있어 다른 근거와 함께 사용합니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(225,29,'INTRO',1,'평균 주변에서 가격이 얼마나 넓게 움직이는지 봅니다','볼린저밴드는 이동평균선을 중심으로 가격 변동성에 따라 상단과 하단 밴드가 넓어지거나 좁아지는 기술적 지표입니다. 가격의 절대 고평가·저평가를 결정하는 지표라기보다 평균과 변동성에 대한 상대적 위치를 보여줍니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(226,29,'FORMULA',2,'대표적인 기본 설정',NULL,'{\"formula\": [\"중심선 = 20기간 단순이동평균(SMA)\", \"상단 = 중심선 + 2 × 표준편차\", \"하단 = 중심선 - 2 × 표준편차\"], \"description\": \"20기간과 2표준편차는 널리 쓰이는 대표 기본값이며 사용자가 변경할 수 있습니다.\"}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(227,29,'TABLE',3,'밴드 폭 해석',NULL,'{\"rows\": [[\"밴드 확대\", \"최근 가격 변동성이 커졌는지\"], [\"밴드 축소\", \"최근 가격 변동성이 낮아졌는지\"], [\"스퀴즈\", \"밴드가 상대적으로 좁아진 상태로 이후 변동성 확대 여부 관찰\"]], \"headers\": [\"상태\", \"일반적으로 보는 점\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(228,29,'EXAMPLE',4,'상단 밴드를 따라 오르는 경우','강한 상승 추세에서는 가격이 상단 밴드에 반복해서 닿거나 상단을 따라 움직일 수 있습니다. 따라서 상단 접촉을 ‘과매수이므로 즉시 하락’이라고 단순 해석하면 강한 추세를 잘못 판단할 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(229,29,'KEY_POINT',5,'밴드 밖 가격도 가능합니다','상단·하단은 물리적인 제한선이 아니므로 가격이 밴드 밖에서 거래될 수 있습니다. 표준편차를 사용한다고 해서 ‘가격의 95%가 반드시 밴드 안에 있다’고 확정해서도 안 됩니다. 금융수익률이 항상 정규분포를 따르는 것은 아니기 때문입니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(230,29,'WARNING',6,'밴드 접촉은 자동 매매신호가 아닙니다','가격 추세, 거래량, 지지·저항, 뉴스 등 다른 정보를 확인해야 합니다. 밴드 폭이 좁아졌다고 어느 방향으로 돌파할지까지 알려주는 것도 아닙니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(231,29,'TIP',7,'설정값을 확인하세요','20·2 외 다른 기간·표준편차 설정을 사용할 수 있습니다. 서로 다른 차트의 밴드를 비교할 때는 설정값이 같은지 먼저 확인합니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(232,29,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"볼린저밴드는 이동평균과 표준편차를 이용해 가격 위치와 변동성을 시각화합니다.\", \"20기간 SMA와 ±2표준편차가 대표 기본 설정입니다.\", \"밴드가 넓어지면 최근 변동성이 커졌을 가능성이 있습니다.\", \"밴드 접촉·스퀴즈는 방향을 보장하는 매매신호가 아닙니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(233,30,'INTRO',1,'좋은 제목이 좋은 투자기회라는 뜻은 아닙니다','뉴스는 기업에 대한 새로운 정보를 제공할 수 있지만 제목만으로 호재·악재를 확정하면 중요한 맥락을 놓칠 수 있습니다. 먼저 사실인지 전망인지, 기업 전체에서 얼마나 큰 영향을 주는지, 시장이 이미 알고 있던 정보인지 확인해야 합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(234,30,'INFOGRAPHIC',2,'뉴스를 읽는 순서',NULL,'{\"steps\": [\"원출처와 사실 여부 확인\", \"사건이 실제로 발생한 날짜 확인\", \"기업 매출·비용·현금흐름에 미칠 영향 추정\", \"회사 전체 규모와 비교\", \"시장 기대와 선반영 여부 확인\", \"발표 후 주가·거래량·업종 반응 확인\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(235,30,'TABLE',3,'정보 유형과 주의점',NULL,'{\"rows\": [[\"공식 공시·회사 발표\", \"원문 수치와 조건, 정정 여부\"], [\"언론 보도\", \"어떤 원출처를 인용했는지\"], [\"증권사·전문가 전망\", \"가정과 예상치가 무엇인지\"], [\"커뮤니티·루머\", \"검증된 사실과 명확히 구분\"]], \"headers\": [\"정보 유형\", \"확인할 점\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(236,30,'EXAMPLE',4,'대형 수주 뉴스인데 주가가 약한 경우','계약금액이 500억 원이라는 제목만 보면 커 보이지만 연매출 10조 원 회사라면 영향이 제한적일 수 있습니다. 이미 시장이 1,000억 원 규모를 기대했다면 500억 원 확정이 오히려 기대 이하로 받아들여질 수도 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(237,30,'KEY_POINT',5,'호재·악재는 기업마다 다르게 작용합니다','원화 약세는 해외 매출 비중이 높은 기업에는 매출 환산에 긍정적일 수 있지만 수입 원재료 의존도가 높은 기업에는 비용 부담이 될 수 있습니다. 같은 뉴스도 사업구조에 따라 효과가 달라집니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(238,30,'KEY_POINT',6,'뉴스와 가격의 인과관계를 과도하게 단정하지 않습니다','발표 직후 주가가 움직였다고 해서 그 뉴스 하나가 가격변화의 유일한 원인이라고 확정하기 어렵습니다. 같은 시간에 시장·업종·수급·다른 공시가 함께 영향을 줬을 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(239,30,'WARNING',7,'기사 작성일과 사건 발생일을 혼동하지 마세요','이미 며칠 전 공시된 사실이 뒤늦게 기사로 다시 보도될 수 있습니다. 새로운 정보인지 확인하지 않으면 ‘오늘 나온 호재’로 잘못 판단할 수 있습니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(240,30,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"뉴스는 원출처·사실성·사건 발생일을 먼저 확인합니다.\", \"영향의 크기는 회사 전체 매출·이익·현금흐름 규모와 비교합니다.\", \"호재·악재의 영향은 사업구조에 따라 달라질 수 있습니다.\", \"기존 기대와 선반영, 시장·업종 반응을 함께 봅니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(241,31,'INTRO',1,'공시는 기업이 공식적으로 제출하는 투자정보입니다','상장기업은 법령과 거래소 규정 등에 따라 중요한 경영·재무 정보를 공시합니다. 뉴스는 공시를 요약하거나 해석할 수 있지만 숫자와 조건을 정확히 확인하려면 DART·거래소 공시 등 원문을 직접 보는 습관이 중요합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(242,31,'TABLE',2,'공시와 뉴스의 차이',NULL,'{\"rows\": [[\"작성 주체\", \"회사 등 공시의무자\", \"언론사·기자 등\"], [\"역할\", \"법정·수시 정보와 공식 수치 제공\", \"사실 전달·맥락·해석 제공\"], [\"주의\", \"추정치·정정·오류 가능성 확인\", \"원출처와 해석을 구분\"]], \"headers\": [\"구분\", \"공시\", \"뉴스·기사\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(243,31,'KEY_POINT',3,'실적에서 먼저 확인할 숫자','매출액, 영업이익, 당기순이익과 대상 기간을 확인합니다. 연결재무제표인지 별도재무제표인지도 중요합니다. 전년 동기와 전분기 대비 변화가 모두 의미 있지만 계절성이 큰 업종은 전년 동기 비교가 더 유용할 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(244,31,'EXAMPLE',4,'매출은 늘고 영업이익은 줄었습니다','매출이 전년 동기 대비 15% 증가했지만 영업이익이 20% 감소했다면 외형은 성장했지만 원가·인건비·판촉비 등 비용 증가가 더 컸는지 확인합니다. 순이익만으로 본업 상황을 단정하지 않습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(245,31,'KEY_POINT',5,'시장 예상치와 일회성 요인','실적이 전년보다 좋아도 시장 예상보다 낮으면 실망으로 받아들여질 수 있습니다. 자산매각이익·충당금·손상차손처럼 일회성 항목이 손익을 크게 바꿨는지도 확인합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(246,31,'PARAGRAPH',6,'정정공시와 주석','공시는 이후 정정될 수 있습니다. 사업보고서·분기보고서의 주석에는 회계정책, 부문정보, 우발채무 등 중요한 설명이 담깁니다. 보고서 종류와 시점에 따라 외부감사 또는 검토의 범위가 다를 수 있으므로 관련 보고서도 함께 확인합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(247,31,'WARNING',7,'‘공시 = 미래가 확정된 사실’은 아닙니다','공시에는 회사가 현재 시점에서 추정한 전망, 계약조건, 계획이 포함될 수 있고 이후 상황에 따라 변경될 수 있습니다. 원문에 있는 가정·조건·변경 가능성을 함께 읽어야 합니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(248,31,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"공시는 기업의 공식 정보이므로 원문 수치와 조건을 확인합니다.\", \"실적은 매출·영업이익·순이익과 대상 기간, 연결/별도 기준을 봅니다.\", \"시장 예상치와 일회성 손익을 구분합니다.\", \"정정공시·주석과 감사·검토 범위도 함께 확인합니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(249,32,'INTRO',1,'500억 원 계약이면 500억 원 이익일까요?','계약 공시는 미래 매출 기회를 보여주는 중요한 정보일 수 있지만 계약금액 전체가 체결 즉시 매출이나 이익으로 인식되는 것은 아닙니다. 회사 규모와 계약기간, 원가, 실제 이행 여부를 함께 봐야 합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(250,32,'TABLE',2,'계약 공시 핵심 항목',NULL,'{\"rows\": [[\"계약금액\", \"절대 규모 파악\"], [\"최근 매출 대비 비율\", \"회사 규모에 비해 얼마나 중요한 계약인지\"], [\"계약기간\", \"언제 이행될 예정인지\"], [\"계약상대방\", \"고객 신뢰도·의존도 확인\"], [\"조건·해지 가능성\", \"계약이 변경·취소될 위험 확인\"]], \"headers\": [\"항목\", \"확인 이유\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(251,32,'EXAMPLE',3,'같은 500억 원도 의미가 다릅니다','연매출 1,000억 원 회사의 500억 원 계약은 매우 큰 비중일 수 있지만 연매출 10조 원 회사에서는 상대적 영향이 작을 수 있습니다. 계약금액은 반드시 기업 규모와 비교해야 합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(252,32,'KEY_POINT',4,'계약일과 매출 인식일은 다를 수 있습니다','회계상 매출은 계약을 발표한 날이 아니라 재화·서비스를 고객에게 이전하는 과정과 회계기준에 따라 기간에 걸쳐 또는 특정 시점에 인식될 수 있습니다. 따라서 계약 체결만으로 해당 분기 매출을 동일 금액만큼 더하면 안 됩니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(253,32,'KEY_POINT',5,'계약금액과 이익은 다릅니다','계약을 이행하려면 원재료비·인건비·외주비 등 비용이 발생합니다. 계약금액이 500억 원이어도 순이익은 그보다 훨씬 작을 수 있고 손실 계약이 될 가능성도 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(254,32,'WARNING',6,'변경·해지와 상대방 의존도를 확인하세요','계약금액·기간이 정정되거나 해지될 수 있고 한 고객에 매출이 지나치게 집중되면 향후 계약 종료 시 위험이 커질 수 있습니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(255,32,'TIP',7,'부가세·환율 등 공시 조건을 읽으세요','공시의 계약금액이 부가가치세 포함/제외인지, 외화 계약이라면 어떤 환율을 적용했는지 등 세부조건이 있을 수 있습니다. 원문 주석과 계산기준을 확인합니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(256,32,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"계약금액은 회사의 최근 매출 규모와 비교합니다.\", \"계약 체결 시점과 회계상 매출 인식 시점은 다를 수 있습니다.\", \"계약금액 전체가 순이익이 아닙니다.\", \"계약기간·상대방·변경·해지 조건을 함께 확인합니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(257,33,'INTRO',1,'기업이 새 주식을 발행해 자금을 조달하는 방법','유상증자는 회사가 새로운 주식을 발행하고 그 대가로 자금을 받는 방식입니다. 신주가 늘어난다는 사실만 보면 기존 주주에게 불리해 보일 수 있지만 실제 영향은 배정 방식, 발행가격, 기존 주주의 참여 여부, 조달자금의 사용처에 따라 달라집니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(258,33,'INFOGRAPHIC',2,'유상증자의 기본 흐름',NULL,'{\"steps\": [\"신주 발행 결정\", \"발행가격·수량·배정방식 결정\", \"투자자의 청약·납입\", \"회사에 자금 유입\", \"발행주식 수 증가\", \"조달자금 사용과 향후 성과 확인\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(259,33,'TABLE',3,'대표적인 배정 방식',NULL,'{\"rows\": [[\"주주배정\", \"기존 주주에게 보유 주식 수에 비례해 신주 인수 기회를 부여\", \"배정분에 비례해 참여하면 지분율을 유지할 수 있는 경우가 있음\"], [\"제3자배정\", \"정관·법적 요건 등에 따라 특정 제3자에게 신주 배정\", \"기존 주주가 참여하지 못하면 지분율 희석 가능성이 큼\"], [\"일반공모 등\", \"불특정 다수 투자자에게 신주를 모집\", \"기존 주주의 참여·배정 조건을 공시에서 확인\"]], \"headers\": [\"방식\", \"기본 의미\", \"기존 주주 관점\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(260,33,'KEY_POINT',4,'지분율 희석과 주당지표 희석은 구분합니다','지분율 희석은 기존 주주가 회사 전체에서 차지하는 비율이 낮아지는 현상입니다. 주주배정에서 기존 주주가 자신의 비율만큼 신주를 인수하면 지분율을 유지할 수 있습니다. 반면 발행주식 수가 증가하면 이익이 즉시 같은 비율로 늘지 않는 한 EPS 같은 주당지표는 낮아질 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(261,33,'EXAMPLE',5,'주주배정에 비례 참여한 경우','기존 주주가 회사 지분 1%를 갖고 있고 주주배정 유상증자에서 배정받은 신주를 모두 인수해 다른 주주들과 동일 비율로 참여한다면 지분율 1%를 유지할 수 있습니다. 반대로 참여하지 않으면 새 주식 수가 늘면서 지분율이 낮아질 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(262,33,'KEY_POINT',6,'조달자금의 사용 목적이 중요합니다','시설투자·연구개발처럼 미래 현금흐름을 늘리기 위한 자금인지, 적자를 메우는 운영자금인지, 부채 상환을 통한 재무구조 개선인지 확인합니다. 같은 유상증자라도 경제적 의미가 다를 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(263,33,'WARNING',7,'유상증자 = 항상 악재, 또는 항상 호재라고 단정하지 마세요','신주 발행은 희석 부담을 만들 수 있지만 조달자금이 기업가치를 충분히 높인다면 장기 효과가 달라질 수 있습니다. 반대로 성장투자라는 명목만으로 성공이 보장되는 것도 아닙니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(264,33,'TIP',8,'발행가격·할인율·보호예수·정정공시를 확인하세요','시가보다 크게 할인된 신주 발행은 가격 부담이 될 수 있고 제3자배정에서는 배정 대상과 보호예수 조건 등이 중요할 수 있습니다. 최종 발행가액과 정정 내용을 원문 공시에서 확인합니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(265,33,'SUMMARY',9,'핵심 정리',NULL,'{\"items\": [\"유상증자는 신주 발행을 통해 자금을 조달하는 방식입니다.\", \"주주배정에서는 기존 주주가 비례 참여하면 지분율을 유지할 수 있는 경우가 있습니다.\", \"지분율 희석과 EPS 등 주당지표 희석은 다른 개념입니다.\", \"발행조건과 조달자금 사용 목적, 향후 성과를 함께 봅니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(266,34,'INTRO',1,'배당금이 늘었다면 항상 좋은 신호일까요?','배당 확대는 주주환원 측면에서 긍정적으로 볼 수 있지만 현재 이익과 현금창출력에 비해 무리한 배당인지, 일회성 특별배당인지, 미래 투자 여력을 크게 줄이는지는 별도로 확인해야 합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(267,34,'TABLE',2,'배당 공시에서 먼저 볼 항목',NULL,'{\"rows\": [[\"주당배당금(DPS)\", \"주식 한 주당 지급하는 배당금\"], [\"배당총액\", \"회사 전체가 지급할 예정인 배당금 규모\"], [\"배당기준일\", \"배당 권리를 판단하는 기준이 되는 날짜\"], [\"지급 예정일\", \"실제 현금 지급 일정\"], [\"배당 종류\", \"현금배당·주식배당 등 형태\"]], \"headers\": [\"항목\", \"의미\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(268,34,'FORMULA',3,'배당수익률과 배당성향',NULL,'{\"formula\": [\"배당수익률 = 주당배당금 ÷ 기준 주가 × 100\", \"배당성향 ≈ 배당총액 ÷ 당기순이익 × 100\"], \"description\": \"배당성향의 정확한 분모와 연결·별도 기준은 데이터 제공기관마다 다를 수 있습니다. 적자나 일회성 이익이 큰 경우 단순 비율 해석에 주의합니다.\"}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(269,34,'EXAMPLE',4,'배당수익률이 높아진 이유','주당배당금이 1,000원으로 그대로인데 주가가 50,000원에서 25,000원으로 급락하면 단순 배당수익률은 2%에서 4%로 높아집니다. 기업의 배당능력이 좋아진 것이 아니라 주가 하락의 결과일 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(270,34,'KEY_POINT',5,'배당의 지속 가능성','순이익뿐 아니라 영업현금흐름, 부채와 이자 부담, 예정된 설비투자·연구개발, 과거 배당정책을 함께 봅니다. 배당은 현금 유출이므로 회계상 이익이 커도 현금이 부족하면 지속 가능성이 낮을 수 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(271,34,'WARNING',6,'특별배당을 정기배당처럼 가정하지 마세요','자산 매각이나 일회성 현금 유입으로 특별배당이 지급될 수 있습니다. 일회성 배당을 기준으로 미래 배당수익률을 그대로 예상하면 과대평가할 수 있습니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(272,34,'TIP',7,'권리 취득 날짜는 최신 공시·결제제도를 확인하세요','배당기준일만 보고 실제 매수 가능 마지막 날짜를 임의 계산하지 말고 회사 공시와 당시 결제제도를 확인해야 합니다. 제도와 회사별 일정은 바뀔 수 있습니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(273,34,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"배당 공시에서 DPS·배당총액·기준일·지급일을 확인합니다.\", \"배당수익률은 기준 주가에 따라 달라집니다.\", \"배당성향은 이익 중 배당 비중을 보는 참고지표이며 산식 기준을 확인합니다.\", \"지속 가능성은 이익·현금흐름·부채·투자계획을 함께 봅니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:41'),(274,35,'INTRO',1,'PER이 더 낮은 기업이 항상 더 좋은 기업일까요?','기업 비교의 목적은 하나의 숫자로 순위를 매기는 것이 아니라 각 기업의 성장성, 수익성, 가격 수준, 재무위험과 사업경쟁력을 같은 기준으로 놓고 장점과 약점을 설명하는 것입니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(275,35,'INFOGRAPHIC',2,'종합 비교 순서',NULL,'{\"steps\": [\"같은 업종·사업모델인지 확인\", \"동일한 보고기간·연결기준 맞추기\", \"매출 성장률 비교\", \"영업이익률·ROE 비교\", \"PER·PBR 비교\", \"부채·현금흐름·이익의 질 확인\", \"시장점유율·R&D·사업구조·외부위험 확인\", \"강점과 위험을 함께 정리\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(276,35,'TABLE',3,'재무지표별 질문',NULL,'{\"rows\": [[\"성장성\", \"매출 성장률\", \"사업 규모가 얼마나 빠르게 커지는가?\"], [\"수익성\", \"영업이익률·ROE\", \"매출과 자본으로 얼마나 이익을 내는가?\"], [\"밸류에이션\", \"PER·PBR\", \"현재 시장가격이 실적·장부가치 대비 어느 수준인가?\"], [\"안정성\", \"부채·현금흐름\", \"재무부담을 감당할 수 있는가?\"]], \"headers\": [\"영역\", \"대표 지표·정보\", \"질문\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(277,35,'TABLE',4,'비재무 비교 요소',NULL,'{\"rows\": [[\"시장점유율\", \"경쟁 지위와 변화\"], [\"연구개발비·신제품\", \"미래 기술·제품 투자와 성과 가능성\"], [\"해외매출 비중\", \"성장 기회와 환율·지역 위험\"], [\"고객 집중도\", \"특정 고객 의존 위험\"], [\"재고·공급망\", \"수요 둔화·원재료 위험\"], [\"사업 포트폴리오\", \"특정 사업 의존도와 분산\"]], \"headers\": [\"항목\", \"확인 의미\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(278,35,'EXAMPLE',5,'낮은 PER과 높은 성장률이 서로 다른 기업에 있을 때','A기업은 PER 6배지만 매출과 영업이익이 감소하고 있고, B기업은 PER 15배지만 높은 ROE와 점유율 성장이 이어진다고 가정해봅시다. A가 싸 보인다는 이유만으로 우위라고 단정할 수 없고 B도 높은 기대가 이미 주가에 반영됐는지 확인해야 합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(279,35,'KEY_POINT',6,'회계기준과 분모를 통일합니다','연결과 별도, 최근 12개월과 직전 연간, 예상이익과 실제이익이 섞이면 비교가 왜곡됩니다. 연구개발비도 비용처리·자산화 정책 차이가 있을 수 있으므로 숫자의 정의를 확인합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(280,35,'WARNING',7,'‘종합점수 1등 = 무조건 좋은 투자’는 아닙니다','투자자는 미래 불확실성을 평가합니다. 지표 가중치를 어떻게 두느냐에 따라 결과가 달라지고 예상치 자체가 틀릴 수 있으므로 비교 결과를 확정적 매수추천으로 사용하지 않습니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(281,35,'TIP',8,'비교표에는 출처와 기준일을 기록하세요','데이터 출처, 연결/별도 여부, 기준일, 환율 적용 기준 등을 기록하면 이후 숫자가 바뀌었을 때 왜 차이가 나는지 설명하기 쉽습니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(282,35,'SUMMARY',9,'핵심 정리',NULL,'{\"items\": [\"기업 비교는 성장성·수익성·밸류에이션·안정성을 함께 봅니다.\", \"비재무 경쟁력과 외부위험도 중요한 비교 요소입니다.\", \"같은 기간·회계범위·산식 기준으로 데이터를 맞춥니다.\", \"한 지표나 임의 점수로 기업 우열을 확정하지 않습니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(283,36,'INTRO',1,'세 종목을 샀는데 사실상 하나의 위험에 베팅할 수도 있습니다','분산효과는 종목 수뿐 아니라 자산들이 어떤 위험요인을 공유하고 수익률이 얼마나 같이 움직이는지에 영향을 받습니다. 이 동행 정도를 정량적으로 표현하는 대표 개념이 상관관계입니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(284,36,'TABLE',2,'상관관계의 기본',NULL,'{\"rows\": [[\"+1에 가까움\", \"두 자산 수익률이 같은 방향으로 강하게 움직이는 경향\"], [\"0에 가까움\", \"선형적인 동행관계가 약함\"], [\"-1에 가까움\", \"두 자산 수익률이 반대 방향으로 강하게 움직이는 경향\"]], \"headers\": [\"상관계수\", \"직관적 의미\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(285,36,'KEY_POINT',3,'0은 ‘아무 관계도 없다’는 뜻이 아닙니다','상관계수 0은 주로 선형적인 함께 움직임이 약하다는 뜻입니다. 비선형 관계나 특정 위기 시 동행 가능성이 없다는 뜻은 아닙니다. 상관계수는 -1에서 +1 사이의 통계적 요약값입니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(286,36,'EXAMPLE',4,'반도체에 집중된 세 상품','반도체 기업 A, 반도체 기업 B, 반도체 ETF를 보유하면 세 종목이지만 업황·메모리 가격·수출 규제 같은 공통 요인에 동시에 노출될 수 있습니다. 평소 수익률도 높은 양의 상관을 보일 가능성이 있습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(287,36,'PARAGRAPH',5,'상관관계가 낮으면 왜 분산에 도움이 될까요?','한 자산이 하락할 때 다른 자산이 덜 하락하거나 다른 방향으로 움직이면 포트폴리오 전체 변동이 완화될 수 있습니다. 다만 기대수익, 변동성, 비중을 함께 고려해야 하며 단순히 상관관계가 낮다는 이유만으로 좋은 자산은 아닙니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(288,36,'KEY_POINT',6,'상관관계는 시간이 지나며 변합니다','평상시에는 상관이 낮던 자산도 금융위기처럼 시장 전체 위험회피가 커질 때 함께 하락할 수 있습니다. 과거 상관계수를 미래의 고정된 성질로 보지 않습니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(289,36,'WARNING',7,'상관관계는 인과관계가 아닙니다','두 자산이 함께 움직였다고 해서 하나가 다른 하나의 가격을 직접 움직였다는 뜻은 아닙니다. 금리·경기 같은 공통 요인이 둘 모두에 영향을 줬을 수 있습니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(290,36,'SUMMARY',8,'핵심 정리',NULL,'{\"items\": [\"상관계수는 -1에서 +1 사이에서 수익률의 선형 동행 정도를 나타냅니다.\", \"양의 상관은 같은 방향, 음의 상관은 반대 방향의 움직임 경향을 뜻합니다.\", \"0에 가까워도 모든 관계가 없다는 뜻은 아닙니다.\", \"상관관계는 변할 수 있으며 분산은 시장 전체 위험을 완전히 제거하지 못합니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(291,37,'INTRO',1,'‘공격형’이면 모든 돈을 고위험 자산에 넣어도 될까요?','아닙니다. 투자 성향은 위험을 얼마나 감수하고 싶은지 설명하는 한 요소일 뿐이고 실제로 감당할 수 있는 손실은 투자기간, 소득, 부채, 비상자금, 가까운 지출계획에 따라 달라집니다. 성향과 재무상황을 분리해 생각해야 합니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(292,37,'KEY_POINT',2,'StockMate의 3단계는 학습용 간소화 분류입니다','안정형·성장형·공격형은 StockMate에서 교육과 문제풀이를 위해 단순화한 분류입니다. 금융회사에서 사용하는 법정 투자자정보 확인 절차나 적합성·적정성 판단의 공식 분류와 동일하다고 보면 안 됩니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(293,37,'TABLE',3,'학습용 세 성향',NULL,'{\"rows\": [[\"안정형\", \"원금 변동을 줄이고 안정성을 상대적으로 더 중시\"], [\"성장형\", \"일정 수준의 변동을 감수하며 성장과 안정의 균형을 추구\"], [\"공격형\", \"큰 가격변동을 감수하면서 높은 기대수익 가능성을 추구\"]], \"headers\": [\"분류\", \"일반적 학습 특징\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(294,37,'KEY_POINT',4,'위험 선호와 위험 감당 능력','심리적으로 30% 손실을 견딜 자신이 있어도 6개월 뒤 반드시 사용할 등록금이라면 실제 손실 감당 능력은 낮습니다. ‘나는 공격적인 성격’이라는 자기평가보다 자금의 사용 시점과 생활에 미칠 영향을 먼저 봅니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(295,37,'TABLE',5,'상품을 역할로 생각하기',NULL,'{\"rows\": [[\"예·적금\", \"단기자금·유동성·원금 안정성 중시\", \"중도해지·물가·보호조건 확인\"], [\"채권\", \"이자수익과 만기 구조 활용\", \"신용·금리·유동성위험\"], [\"ETF\", \"시장·산업·자산군에 분산 접근\", \"기초자산·괴리·구조 확인\"], [\"개별주식\", \"기업 선택에 따른 성장·수익 가능성\", \"높은 기업고유 위험과 가격변동\"]], \"headers\": [\"자산·상품\", \"대표적으로 고려할 역할\", \"주요 주의\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(296,37,'EXAMPLE',6,'같은 성장형이라도 자산구성이 달라질 수 있습니다','비상자금이 충분하고 10년 이상 투자할 직장인과 1년 뒤 큰 지출이 예정된 학생이 모두 ‘성장형’으로 분류돼도 실제 위험자산 비중은 같을 필요가 없습니다. 투자목적과 현금 필요시점이 다르기 때문입니다.',NULL,NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(297,37,'WARNING',7,'성향 분류는 투자추천이나 수익 보장이 아닙니다','공격형이라는 이유로 레버리지·집중투자가 자동으로 적합해지는 것도 아니고 안정형이라고 손실이 전혀 없는 것도 아닙니다. 실제 금융상품 선택에는 상품설명서와 개인 재무상황을 별도로 확인해야 합니다.','\"warning\"','warning',1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(298,37,'TIP',8,'성향은 시간이 지나면 바뀔 수 있습니다','취업, 결혼, 대출, 소득 변화, 투자 경험처럼 상황이 달라지면 감당 가능한 위험도 달라질 수 있습니다. 정기적으로 자신의 목적과 자금계획을 다시 확인하는 것이 좋습니다.','\"tip\"','tip',1,'2026-08-14 00:44:21','2026-08-14 05:27:42'),(299,37,'SUMMARY',9,'핵심 정리',NULL,'{\"items\": [\"StockMate의 3단계 투자성향은 학습을 위한 간소화 분류입니다.\", \"위험 선호와 실제 손실 감당 능력은 다를 수 있습니다.\", \"투자목적·기간·비상자금·유동성 필요를 함께 고려합니다.\", \"성향 분류만으로 특정 상품의 적합성이나 수익을 보장하지 않습니다.\"]}',NULL,1,'2026-08-14 00:44:21','2026-08-14 05:27:42');
