INSERT INTO `quiz_choices` VALUES (155,40,1,'채권',0),(156,40,2,'정기예금',0),(157,40,3,'배당',0),(158,40,4,'기업의 소유권 일부를 나타내는 증권',1),(159,41,1,'주식은 기업에 대한 소유 지분이고, 채권은 정해진 이자와 원금 상환을 약속하는 채무 증권이다',1),(160,41,2,'주식과 채권 모두 만기에 원금 상환이 보장된다',0),(161,41,3,'채권은 주식보다 항상 더 높은 수익률을 낸다',0),(162,41,4,'주식은 이자를, 채권은 배당을 지급하는 상품이다',0),(163,42,1,'주주는 보유 지분만큼 배당을 받을 권리가 있다',0),(164,42,2,'주주는 주주총회에서 의결권을 행사할 수 있다',0),(165,42,3,'기업이 파산하면 주주는 채권자보다 먼저 잔여재산을 배분받는다',1),(166,42,4,'회사 실적이 악화되면 주가 하락에 따른 손실을 감수해야 한다',0),(167,43,1,'O',1),(168,43,2,'X',0),(169,43,3,'개념 \'주식\'는 일정 기간 실제로 거래된 주식 수량이고, 개념 \'거래량\'는 기업의 소유권 일부를 나타내는 증권이다.',0),(170,43,4,'개념 \'주식\'와 개념 \'거래량\'는 같은 의미이므로 구분할 필요가 없다.',0),(171,44,1,'O',0),(172,44,2,'X',1),(173,45,1,'배당이 없어도 이익을 재투자해 기업가치가 높아지면 주가 상승으로 이어질 수 있다',1),(174,45,2,'배당이 없는 회사는 투자 가치가 전혀 없다',0),(175,46,1,'재무제표, 산업 동향, 경쟁사 비교 등 기업 펀더멘털 정보',1),(176,46,2,'특정 종목 커뮤니티 게시글의 추천 수',0),(177,46,3,'최근 하루 동안의 주가 등락률 하나',0),(178,46,4,'지인의 매수 추천 여부',0),(179,47,1,'기업 실적 악화나 시장 상황에 따라 주가가 하락해 원금 손실이 발생할 수 있다',1),(180,47,2,'주식은 예금자보호 대상이라 원금 손실이 없다',0),(181,47,3,'주식은 만기가 있어 만기에는 항상 원금이 보장된다',0),(182,47,4,'주식 투자 손실은 국가가 보전해 준다',0),(183,48,1,'기업가치는 배당뿐 아니라 성장성, 수익성, 재무 안정성 등을 함께 봐야 하기 때문',1),(184,48,2,'배당을 주는 회사는 부도 위험이 전혀 없기 때문',0),(185,48,3,'배당을 주지 않는 회사는 상장폐지 대상이기 때문',0),(186,48,4,'배당 지급 여부는 주가와 아무 관련이 없기 때문',0),(187,49,1,'주식은 기업 소유권을 나타내는 증권으로, 가격 변동에 따른 이익과 손실을 주주가 함께 부담한다',1),(188,49,2,'주식은 원금과 수익이 보장되는 저축 상품이다',0),(189,49,3,'주식 보유자는 회사가 손실을 보더라도 이를 부담하지 않는다',0),(190,49,4,'주식은 만기일에 발행가 그대로 되돌려 받을 수 있는 상품이다',0),(191,50,1,'배당금',0),(192,50,2,'시장에서 거래되는 주식 한 주의 가격',1),(193,50,3,'시가총액',0),(194,50,4,'거래량',0),(195,51,1,'시가총액은 주가에 발행주식 수를 곱한 값이므로, 주가가 낮아도 발행주식 수가 많으면 시가총액은 클 수 있다',1),(196,51,2,'주가가 높은 회사가 항상 시가총액도 더 크다',0),(197,51,3,'주가와 시가총액은 항상 같은 값을 가리키는 동일한 개념이다',0),(198,51,4,'시가총액은 주가와 무관하게 결정된다',0),(199,52,1,'두 기업 중 어느 쪽 시가총액이 더 큰지는 알 수 없다',1),(200,52,2,'A기업이 B기업보다 저평가되어 있다',0),(201,52,3,'B기업 규모가 A기업보다 10배 크다',0),(202,52,4,'A기업 주식이 더 안전한 투자처다',0),(203,53,1,'주가는 실적과 시장 기대를 함께 반영한다',0