--
-- Table structure for table `quiz_questions`
--

DROP TABLE IF EXISTS `quiz_questions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quiz_questions` (
  `question_id` int NOT NULL AUTO_INCREMENT,
  `topic_id` int NOT NULL,
  `investment_level_id` int DEFAULT NULL,
  `category_id` int DEFAULT NULL,
  `owner_user_id` int DEFAULT NULL,
  `source_type` enum('DEFAULT','WRONG_ANSWER','PERSONAL_PROMPT','ADMIN') NOT NULL DEFAULT 'DEFAULT',
  `quiz_pool_type` enum('GENERAL','CONCEPT_CHECK','BOTH') NOT NULL DEFAULT 'GENERAL',
  `visibility` enum('PUBLIC','PRIVATE') NOT NULL DEFAULT 'PUBLIC',
  `source_question_id` int DEFAULT NULL,
  `source` enum('MANUAL','AI') NOT NULL DEFAULT 'MANUAL',
  `review_status` enum('PENDING','ACTIVE','INACTIVE','REJECTED','REVIEW_REQUIRED') NOT NULL DEFAULT 'ACTIVE',
  `ai_quality_score` int DEFAULT NULL,
  `final_quality_score` int DEFAULT NULL,
  `similarity_score` decimal(5,4) DEFAULT NULL,
  `similar_question_id` int DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `question_type` enum('MULTIPLE_CHOICE','OX') NOT NULL,
  `question_text` text NOT NULL,
  `explanation` text,
  `reward_cash` int DEFAULT '0',
  `status` enum('ACTIVE','INACTIVE') DEFAULT 'ACTIVE',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`question_id`),
  KEY `idx_quiz_topic` (`topic_id`),
  KEY `idx_quiz_level` (`investment_level_id`),
  KEY `idx_quiz_category` (`category_id`),
  KEY `idx_quiz_owner` (`owner_user_id`),
  KEY `idx_quiz_visibility_status` (`visibility`,`status`),
  KEY `idx_quiz_owner_visibility_status` (`owner_user_id`,`visibility`,`status`),
  KEY `idx_quiz_source_type` (`source_type`),
  KEY `idx_quiz_pool_type` (`quiz_pool_type`,`status`,`review_status`),
  KEY `idx_quiz_source_question` (`source_question_id`),
  KEY `idx_quiz_questions_review_status` (`review_status`),
  KEY `idx_quiz_questions_source` (`source`),
  KEY `idx_quiz_questions_quality` (`final_quality_score`,`similarity_score`),
  KEY `idx_quiz_status` (`status`),
  CONSTRAINT `fk_quiz_questions_category` FOREIGN KEY (`category_id`) REFERENCES `quiz_categories` (`category_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_quiz_questions_investment_level` FOREIGN KEY (`investment_level_id`) REFERENCES `investment_levels` (`investment_level_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_quiz_questions_owner` FOREIGN KEY (`owner_user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_quiz_questions_source_question` FOREIGN KEY (`source_question_id`) REFERENCES `quiz_questions` (`question_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_quiz_questions_topic` FOREIGN KEY (`topic_id`) REFERENCES `learning_topics` (`topic_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=977 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `quiz_questions`
--

LOCK TABLES `quiz_questions` WRITE;
/*!40000 ALTER TABLE `quiz_questions` DISABLE KEYS */;
INSERT INTO `quiz_questions` VALUES (40,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','주식의 의미로 가장 적절한 것은?','주식은 기업의 소유권 일부를 나타내는 증권이다. 주주는 회사 가치 변동에 따른 이익과 손실을 함께 부담한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(41,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','주식과 채권의 가장 큰 차이로 옳은 것은?','주식은 상환 의무가 없는 소유 지분이며, 채권은 발행자가 만기에 원금과 이자를 갚기로 약속한 채무 증권이다. 두 상품은 위험과 수익 구조가 근본적으로 다르다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(42,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','주주의 권리와 위험에 대한 설명 중 옳지 않은 것은?','기업 청산 시 채권자가 주주보다 우선 변제받고, 주주는 그 이후 남는 재산에 대해서만 권리를 갖는다. 이 때문에 주식은 채권보다 청산 시 회수 순위가 낮다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(43,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','주식은 기업의 소유권 일부를 나타내는 증권이다.','맞다. 주주는 지분율만큼 회사에 대한 소유권을 가지며 그에 따른 이익과 손실을 함께 부담한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(44,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','주식을 보유하면 회사 실적과 무관하게 매년 일정한 수익이 보장된다.','틀리다. 주식은 확정 수익 상품이 아니며 배당과 주가는 기업 실적과 시장 상황에 따라 달라진다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(45,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','A씨는 이익을 배당하지 않고 전액 재투자하는 회사의 주식을 보유하고 있다. 가장 적절한 해석은?','배당은 기업이 이익을 나누는 방법 중 하나일 뿐이다. 성장기 기업은 이익을 재투자해 기업가치를 높이는 전략을 택하기도 하므로 배당 여부만으로 투자 매력을 판단할 수 없다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(46,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','주식 투자를 결정하기 전 추가로 확인하면 좋은 정보로 가장 적절한 것은?','재무제표, 산업 동향, 경쟁사와의 비교는 기업의 실질 가치를 판단하는 데 도움이 된다. 단기 등락률이나 비공식적인 추천은 신뢰할 수 있는 판단 근거가 되기 어렵다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(47,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','주식 투자의 위험 요인으로 가장 적절한 것은?','주식은 예금자보호 대상이 아니며 원금이 보장되지 않는다. 기업 실적과 시장 상황에 따라 주가가 하락하면 투자자는 손실을 볼 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(48,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','배당을 지급하는 회사가 배당을 지급하지 않는 회사보다 항상 더 나은 투자 대상이라고 볼 수 없는 이유는?','배당은 기업가치를 판단하는 여러 요소 중 하나에 불과하다. 성장성이 높은 기업은 배당 대신 재투자를 선택하기도 하므로 배당 지급 여부만으로 우열을 가릴 수 없다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(49,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','주식에 대한 설명으로 가장 적절한 것은?','주식은 저축이나 채권과 달리 원금이나 수익을 보장하지 않는 소유권 증권이다. 회사 성과에 따라 주주가 이익과 손실을 함께 부담하는 구조임을 이해해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(50,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','주가의 의미로 가장 적절한 것은?','주가는 시장에서 거래되는 주식 한 주의 가격으로, 실적과 기대감, 수급, 시장 분위기의 영향을 함께 받는다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(51,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','주가와 시가총액의 관계를 옳게 설명한 것은?','시가총액은 주가에 발행주식 수를 곱해 산출한다. 주가가 낮은 종목이라도 발행주식 수가 많으면 시가총액은 더 클 수 있어, 주가만으로 기업 규모를 비교할 수 없다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(52,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','A기업 주가는 5,000원, B기업 주가는 50,000원이다. 이 정보만으로 알 수 있는 것은?','주가는 발행주식 수에 따라 액면분할이나 병합 등으로 달라질 수 있어 절대 수준만으로 기업 규모나 저평가 여부를 판단할 수 없다. 시가총액과 재무지표를 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(53,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','주가에 대한 설명 중 옳지 않은 것은?','주가는 발행주식 수에 따라 왜곡될 수 있으므로 절대 수치만으로 기업 규모를 비교하기 어렵다. 시가총액 등 관련 지표를 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(54,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','주가는 시장에서 거래되는 주식 한 주의 가격이다.','맞다. 주가는 실적, 기대감, 수급, 시장 분위기 등 다양한 요인의 영향을 받아 형성된다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(55,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','거래량이 증가하면 주가는 항상 상승한다.','틀리다. 거래량 증가는 매수와 매도가 모두 활발해졌다는 의미로, 상승과 하락 어느 쪽에서도 나타날 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(56,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','어떤 종목의 주가가 하루 만에 급등했다. 가장 적절한 다음 확인은?','단기 급등은 실적 개선 같은 근본적 요인일 수도, 일시적 수급 쏠림일 수도 있다. 원인을 확인하지 않고 추격 매수하면 변동성 위험에 노출될 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(57,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','주가만 보고 저평가 여부를 판단하기 어려운 이유로 가장 적절한 것은?','주가 수준 자체는 발행주식 수에 따라 달라질 수 있어 절대 가격만으로 저평가 여부를 알 수 없다. PER, PBR 같은 상대 지표와 실적, 성장성을 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(58,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','주가 변동에 영향을 주는 위험 요인으로 가장 적절한 것은?','주가는 기업 실적뿐 아니라 금리, 산업 업황, 시장 전반의 투자 심리 등 다양한 외부 요인에 영향을 받는다. 이러한 요인이 나빠지면 주가가 하락해 손실로 이어질 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(59,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','주가가 높은 회사와 시가총액이 큰 회사는 항상 같은 회사인가?','시가총액은 주가와 발행주식 수를 함께 곱해 계산하므로, 주가가 높아도 발행주식 수가 적으면 시가총액은 작을 수 있다. 두 지표는 함께 봐야 기업 규모를 제대로 파악할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(60,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','시가총액의 의미로 가장 적절한 것은?','시가총액은 주가에 발행주식 수를 곱해 산출한 시장가치 총액으로, 기업 규모를 비교하는 대표적인 지표다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(61,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','시가총액과 기업가치(EV)의 차이로 옳은 것은?','시가총액은 주식 가치만 반영하지만 기업가치(EV)는 순부채까지 더해 기업 전체 가치를 나타낸다. 부채가 많은 기업을 비교할 때는 시가총액만으로 규모를 판단하면 왜곡될 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(62,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','A기업과 B기업의 시가총액이 같다. 이 정보만으로 알 수 있는 것은?','시가총액이 같아도 발행주식 수, 수익성, 부채 수준 등은 크게 다를 수 있다. 시가총액은 규모를 비교하는 지표일 뿐 기업의 질적 차이를 설명하지 않는다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(63,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','시가총액에 대한 설명 중 옳지 않은 것은?','시가총액은 규모를 나타낼 뿐 저평가나 고평가 여부를 알려주지 않는다. 저평가 여부는 PER, PBR 등 이익·자산 대비 가격을 보여주는 지표로 판단해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(64,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','시가총액은 주가에 발행주식 수를 곱해 계산한 해당 기업 주식의 시장가치 총액이다.','맞다. 발행주식 수가 달라지면 주가가 낮아도 시가총액이 클 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(65,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','시가총액이 크면 그 기업은 항상 안전한 투자처다.','틀리다. 시가총액이 커도 산업 변화나 실적 악화에 따라 주가가 하락하고 손실이 발생할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(66,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','시가총액 상위 종목에만 투자하면 안전하다고 생각하는 투자자에게 해줄 조언으로 가장 적절한 것은?','시가총액이 크다는 것은 규모가 크다는 의미일 뿐, 손실 위험이 없다는 뜻은 아니다. 실적과 산업 환경 변화에 따라 대형주도 주가가 하락할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(67,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','시가총액이 비슷한 두 기업을 비교할 때 추가로 확인하면 좋은 정보는?','시가총액이 비슷해도 실적과 재무구조는 크게 다를 수 있다. 매출, 영업이익, 부채비율 등을 함께 비교해야 기업의 질적 차이를 파악할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(68,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','시가총액이 작은 기업(소형주) 투자에서 특히 유의해야 할 위험은?','시가총액이 작은 기업은 거래량이 적어 원하는 가격에 매매하지 못하는 유동성 위험이 있고, 실적 변동에 따른 주가 변동성도 상대적으로 크다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(69,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','시가총액과 주가 상승률의 관계로 옳은 것은?','시가총액은 현재 규모를, 주가 상승률은 일정 기간의 가격 변화율을 나타내는 서로 다른 지표다. 대형주도 정체될 수 있고 소형주도 급등락할 수 있어 둘은 비례 관계가 아니다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(70,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','배당의 의미로 가장 적절한 것은?','배당은 기업이 이익이나 보유 현금의 일부를 주주에게 나눠주는 것으로, 회사 정책과 실적, 현금흐름에 따라 규모가 달라질 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(71,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','배당과 채권 이자의 차이로 옳은 것은?','채권은 발행 시 약정한 이자를 지급할 의무가 있지만, 배당은 그런 계약상 의무가 없어 기업 실적이 나빠지면 축소되거나 지급되지 않을 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(72,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','배당수익률이 높은 종목을 발견했다. 가장 적절한 다음 확인은?','배당수익률은 주가가 하락하면 배당금이 그대로여도 높아 보일 수 있다. 배당의 재원이 되는 이익과 현금흐름이 안정적인지 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(73,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','배당에 대한 설명 중 옳지 않은 것은?','배당을 하지 않는 기업 중에는 이익을 재투자해 성장하는 우량 기업도 많다. 배당 지급 여부만으로 기업의 재무 상태를 단정할 수 없다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(74,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','배당은 기업이 이익이나 보유 현금의 일부를 주주에게 분배하는 것이다.','맞다. 배당의 규모와 지급 여부는 기업 실적과 이사회 정책에 따라 달라질 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(75,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','배당수익률이 높으면 항상 안전하고 우수한 투자 대상이다.','틀리다. 주가 급락으로 배당수익률이 일시적으로 높아 보일 수 있고, 향후 배당이 줄어들 위험도 함께 고려해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(76,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','매년 배당을 늘려온 기업이 올해 처음으로 배당을 줄였다. 가장 적절한 해석은?','배당 감소는 실적 부진, 투자 확대, 현금흐름 악화 등 다양한 배경에서 나타날 수 있다. 원인을 확인하지 않고 성급하게 결론을 내리면 판단을 그르칠 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(77,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','배당주에 투자할 때 배당수익률 외에 추가로 확인하면 좋은 정보는?','배당의 지속 가능성은 과거 배당 이력과 이익, 현금흐름의 안정성에서 확인할 수 있다. 배당수익률 한 지표만으로는 지속 가능성을 판단하기 어렵다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(78,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','배당주 투자에서 유의해야 할 위험으로 가장 적절한 것은?','배당은 확정된 것이 아니라 기업 실적에 따라 변동할 수 있는 이익 분배다. 배당주도 일반 주식과 마찬가지로 주가 하락에 따른 원금 손실 위험을 갖는다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(79,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','배당 여부와 기업가치의 관계를 가장 적절하게 설명한 것은?','배당은 기업이 이익을 나누는 여러 방법 중 하나일 뿐이다. 기업가치는 성장성, 수익성, 재무 안정성 등을 종합적으로 반영하므로 배당 여부만으로는 판단할 수 없다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(80,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','거래량의 의미로 가장 적절한 것은?','거래량은 일정 기간 실제로 거래된 주식 수량으로, 매매 관심도와 체결 강도를 보여주는 보조 지표다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(81,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','거래량과 주가의 관계로 옳은 것은?','거래량 증가는 시장 참여자들의 관심이 커졌다는 신호일 뿐, 방향을 알려주지는 않는다. 주가 흐름과 함께 봐야 매수세와 매도세 중 어느 쪽이 우세한지 가늠할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(82,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','어떤 종목의 주가는 크게 올랐지만 거래량은 평소보다 오히려 줄었다. 가장 적절한 해석은?','거래량을 동반하지 않은 상승은 소수의 매매만으로 가격이 움직였을 가능성이 있다. 이런 경우 상승세가 계속될지 신중하게 지켜볼 필요가 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(83,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','거래량에 대한 설명 중 옳지 않은 것은?','거래량은 관심도와 매매 강도를 보여줄 뿐 방향을 예측하는 지표가 아니다. 주가 움직임과 함께 봐야 해석에 도움이 된다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(84,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','거래량은 일정 기간 실제로 거래된 주식 수량이다.','맞다. 거래량은 매매 관심과 체결 강도를 보여주는 보조 정보다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(85,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','거래량 급증은 항상 주가 상승의 신호다.','틀리다. 거래량 급증은 매도세가 강하게 몰릴 때도 나타날 수 있어 방향을 단정할 수 없다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(86,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','평소보다 거래량이 10배 급증한 종목을 발견했다. 가장 적절한 다음 행동은?','거래량 급증은 특정 뉴스나 공시, 수급 변화 등 원인이 있는 경우가 많다. 원인과 주가 방향을 함께 확인해야 성급한 매매를 피할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(87,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','거래량 정보를 해석할 때 함께 확인하면 좋은 정보는?','거래량은 그 자체로는 방향성이 없는 정보다. 같은 기간 주가 움직임과 거래 증가의 배경이 되는 뉴스·공시를 함께 봐야 의미 있는 해석이 가능하다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(88,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','거래량이 매우 적은 종목(품절주 등) 투자 시 유의할 점은?','거래량이 매우 적으면 원하는 시점에 원하는 가격으로 매매하기 어려운 유동성 위험이 커진다. 이런 종목은 소량 매매에도 가격이 크게 흔들릴 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(89,1,1,1,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','거래량 증가가 항상 주가 상승을 의미하지 않는 이유로 가장 적절한 것은?','거래량은 방향을 가리지 않고 체결된 매매 수량을 모두 합산한 값이다. 매도세가 우세해 주가가 하락할 때도 거래량은 얼마든지 늘어날 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(90,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','PER의 의미로 가장 적절한 것은?','PER은 주가를 주당순이익(EPS)으로 나눈 주가수익비율로, 이익 대비 주가 수준을 나타낸다. 업종 평균, 성장성과 함께 비교해야 의미가 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(91,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','A기업의 주가는 20,000원, EPS는 2,000원이다. PER은 얼마인가?','PER은 주가를 EPS로 나눠 구한다. 20,000원을 2,000원으로 나누면 10배가 된다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(92,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','PER이 낮다고 해서 항상 저평가로 볼 수 없는 이유로 가장 적절한 것은?','PER은 주가 수준과 이익을 함께 반영하므로, 이익이 줄어 EPS가 낮아지면 PER도 낮게 계산될 수 있다. 업종 평균과 이익의 지속 가능성을 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(93,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','PER과 PBR의 차이로 옳은 것은?','PER은 주당순이익(EPS), PBR은 주당순자산(BPS)을 기준으로 각각 계산되는 별개의 지표다. 두 지표가 항상 같은 결론을 주는 것은 아니다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(94,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','PER은 주가를 주당순이익(EPS)으로 나눈 주가수익비율이다.','맞다. PER은 이익 대비 주가 수준을 나타내는 대표적인 밸류에이션 지표다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(95,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','PER이 낮으면 업종과 성장성을 비교하지 않아도 항상 저평가라고 볼 수 있다.','틀리다. 업종 평균, 성장성, 이익의 지속 가능성을 함께 비교해야 저평가 여부를 판단할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(96,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','A기업 PER은 8배, 같은 업종 평균 PER은 15배다. 가장 적절한 다음 확인은?','업종 평균보다 낮은 PER은 저평가 신호일 수도 있지만, 실적 악화나 리스크를 시장이 이미 반영한 결과일 수도 있다. 원인을 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(97,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','이익이 절반으로 줄었는데 주가는 그대로여서 PER이 이전보다 두 배로 높아졌다. 가장 적절한 해석은?','PER은 주가뿐 아니라 이익(EPS) 변화에도 영향을 받는다. 이익이 감소하면 주가가 그대로여도 PER이 높아질 수 있어 원인을 구분해 봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(98,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','PER만 보고 투자를 결정하기 전에 추가로 확인하면 좋은 정보는?','PER은 업종과 성장성에 따라 적정 수준이 달라진다. 업종 평균, 이익 성장률, 이익의 질을 함께 살펴야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(99,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','PER 해석의 한계로 가장 적절한 것은?','적자 기업은 EPS가 음수라 PER 해석이 어렵고, 일회성 이익이 섞이면 PER이 실제보다 낮아 보일 수 있다. PER 하나로 기업 전체를 판단하기는 어렵다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(100,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','B기업의 주가는 30,000원이고 EPS는 3,000원에서 1,500원으로 감소했다. PER 변화로 옳은 것은?','PER은 주가를 EPS로 나눠 계산한다. 주가가 그대로여도 EPS가 절반으로 줄면 PER은 두 배로 높아진다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(101,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','PER에 대한 설명 중 옳지 않은 것은?','PER이 같아도 성장성, 재무구조, 업종 특성에 따라 위험도는 크게 다를 수 있다. PER은 여러 판단 지표 중 하나로 활용해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(102,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','PER을 해석할 때 기준 기간이나 업종을 확인하는 것이 좋다.','맞다. PER의 적정 수준은 업종과 성장 단계에 따라 다르므로 기준을 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(103,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','ROE의 의미로 가장 적절한 것은?','ROE는 기업이 자기자본을 활용해 얼마나 이익을 냈는지 보여주는 수익성 지표다. 부채비율에 따라 값이 왜곡될 수 있어 재무구조와 함께 봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(104,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','자기자본이 10억 원인 기업이 당기순이익 1억 원을 냈다면 ROE는?','ROE는 당기순이익을 자기자본으로 나눠 구한다. 1억 원을 10억 원으로 나누면 10%다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(105,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','높은 ROE가 항상 우수한 수익성을 의미하지 않는 이유로 가장 적절한 것은?','ROE는 자기자본 대비 이익을 보여주므로, 부채를 늘려 자기자본 비중을 줄이면 이익 증가 없이도 ROE가 높아질 수 있다. 부채비율을 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(106,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','ROE와 PER을 구분한 설명으로 옳은 것은?','ROE는 수익성을, PER은 가격 수준을 나타내는 서로 다른 지표로, 두 지표가 항상 같은 방향으로 움직이는 것은 아니다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(107,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','ROE는 기업이 자기자본을 활용해 얼마나 이익을 냈는지를 보여주는 수익성 지표이다.','맞다. ROE가 높을수록 자기자본을 효율적으로 활용해 이익을 냈다고 볼 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(108,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','ROE가 높으면 부채 수준과 관계없이 항상 우량한 기업이다.','틀리다. 부채를 크게 늘려 ROE가 일시적으로 높아진 경우일 수 있어 재무구조를 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(109,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','C기업의 ROE는 20%로 매우 높지만 최근 부채비율이 크게 상승했다. 가장 적절한 확인은?','ROE는 부채 활용도가 커지면 함께 높아질 수 있는 지표다. 수익성 개선인지 레버리지 효과인지 재무구조를 통해 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(110,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','D기업은 올해 자산을 매각한 일회성 이익 덕분에 ROE가 크게 상승했다. 가장 적절한 해석은?','자산 매각 같은 일회성 이익은 그해 ROE를 높이지만 반복되지 않는다. 본업에서 나온 이익인지 구분해 지속 가능성을 판단해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(111,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','ROE만으로 기업의 수익성을 판단하기 어려울 때 추가로 확인하면 좋은 정보는?','ROE는 부채비율과 이익의 질에 따라 왜곡될 수 있으므로, 재무구조와 이익의 원천을 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(112,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','ROE에 대한 설명 중 옳지 않은 것은?','업종 평균보다 높은 ROE도 부채나 일회성 이익의 영향을 받을 수 있어 저위험을 보장하지 않는다. 원인을 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(113,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','ROE 해석의 한계로 가장 적절한 것은?','ROE는 유용한 수익성 지표지만 부채 구조와 이익의 질에 따라 왜곡될 수 있다. 원인을 함께 파악해야 올바르게 해석할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(114,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','E기업과 F기업의 ROE가 똑같이 15%다. E기업은 부채비율이 낮고 F기업은 부채비율이 매우 높다면?','ROE 수치가 같아도 그 이익이 어떻게 만들어졌는지는 다를 수 있다. 부채비율이 높은 기업은 레버리지에 의한 수익성 확대일 가능성을 함께 살펴야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(115,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','ROE를 해석할 때 부채비율과 이익의 지속 가능성을 함께 확인하는 것이 좋다.','맞다. ROE는 부채 구조와 이익의 질에 따라 달라질 수 있어 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(116,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','EPS의 의미로 가장 적절한 것은?','EPS는 기업의 순이익을 가중평균 유통보통주식 수로 나눈 주당 이익 지표로, PER 계산의 기준이 되는 값이다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(117,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','당기순이익이 50억 원이고 유통주식 수가 100만 주라면 EPS는?','EPS는 순이익을 유통주식 수로 나눠 구한다. 50억 원을 100만 주로 나누면 5,000원이다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(118,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','EPS가 증가했다고 해서 항상 기업의 본질적인 수익력이 좋아진 것은 아닌 이유는?','EPS는 일회성 이익이 포함되면 일시적으로 늘어날 수 있다. 본업에서 반복적으로 나오는 이익인지 확인해야 지속 가능성을 판단할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(119,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','EPS와 PER의 관계로 옳은 것은?','PER은 주가를 EPS로 나눈 값이므로 EPS가 변하면 PER도 함께 달라진다. EPS 감소는 PER을 높이는 방향으로 작용할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(120,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','EPS는 기업의 이익을 일정 기간의 가중평균 유통보통주식 수로 나누어 주당 이익 수준을 나타낸 지표이다.','맞다. 기본 EPS는 단순 발행주식 수가 아니라 가중평균 유통보통주식 수를 기준으로 계산한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(121,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','EPS가 늘어난 원인이 무엇인지 확인하지 않아도 항상 좋은 신호로 해석할 수 있다.','틀리다. 일회성 이익이나 자사주 매입에 따른 주식 수 감소 등으로도 EPS가 늘어날 수 있어 원인을 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(122,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','G기업은 이익 증가 없이 자사주를 매입해 소각했는데 EPS가 늘었다. 가장 적절한 해석은?','EPS는 이익뿐 아니라 유통주식 수에도 영향을 받는다. 자사주 매입·소각으로 주식 수가 줄면 이익이 그대로여도 EPS는 늘어날 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(123,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','H기업의 EPS가 전년보다 크게 늘었는데, 그중 대부분이 보유 부동산 매각 이익이었다. 적절한 판단은?','부동산 매각 같은 일회성 이익은 반복되지 않는다. EPS 증가가 본업에서 나온 것인지 구분해야 이익의 질을 제대로 평가할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(124,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','EPS 증가율만 보고 투자 판단을 내리기 전에 추가로 확인하면 좋은 정보는?','EPS는 이익뿐 아니라 유통주식 수 변화에도 영향을 받는다. 증가 원인이 본업 이익인지, 일회성 요인인지 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(125,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','EPS에 대한 설명 중 옳지 않은 것은?','EPS 증가의 원인이 본업 이익인지 일회성 요인인지에 따라 해석이 달라진다. 원인을 확인하지 않고 판단하면 이익의 질을 놓칠 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(126,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','EPS 해석의 한계로 가장 적절한 것은?','EPS는 유용한 지표지만 일회성 이익이나 주식 수 변화에 따라 실제 수익력과 다르게 나타날 수 있다. 이익의 원천을 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(127,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','EPS를 해석할 때 이익 증가의 원인과 유통주식 수 변화를 함께 확인하는 것이 좋다.','맞다. EPS는 이익과 유통주식 수 모두의 영향을 받으므로 원인을 함께 살펴야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(128,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','PBR의 의미로 가장 적절한 것은?','PBR은 주가를 주당순자산(BPS)으로 나눈 주가순자산비율로, 자산 대비 주가 수준을 나타낸다. 자산의 질과 수익성도 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(129,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','어떤 기업의 주가는 12,000원이고 BPS(주당순자산)는 6,000원이다. PBR은?','PBR은 주가를 BPS로 나눠 구한다. 12,000원을 6,000원으로 나누면 2배가 된다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(130,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','PBR을 해석할 때 업종 특성을 함께 고려해야 하는 이유로 가장 적절한 것은?','제조업처럼 유형자산이 많은 업종과 IT처럼 무형자산 비중이 큰 업종은 장부상 순자산의 의미가 다르다. 업종 특성을 고려하지 않고 PBR만 비교하면 판단을 그르칠 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(131,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','PBR과 PER의 차이로 옳은 것은?','PBR은 주당순자산(BPS), PER은 주당순이익(EPS)을 기준으로 각각 계산되는 별개의 지표이며 항상 같은 방향으로 움직이지 않는다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(132,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','PBR은 주가를 주당순자산(BPS)으로 나눈 주가순자산비율이다.','맞다. PBR은 기업의 장부상 자산 가치 대비 주가 수준을 보여준다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(133,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','PBR이 1배 미만이면 업종이나 자산의 질과 관계없이 항상 저평가된 것이다.','틀리다. 자산의 수익성이 낮거나 부실 자산이 포함된 경우 낮은 PBR이 정당화될 수 있어 자산의 질을 함께 봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(134,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','I기업의 PBR은 0.6배로 업종 평균보다 낮지만 최근 몇 년간 적자가 이어지고 있다. 가장 적절한 확인은?','낮은 PBR은 저평가 신호일 수도 있지만, 지속적인 적자로 자산의 수익 창출력이 낮게 평가된 결과일 수도 있다. 원인을 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(135,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','부동산 등 유형자산 비중이 큰 J기업과 지식재산 중심의 K기업의 PBR을 단순 비교하려 한다. 가장 적절한 태도는?','업종에 따라 자산의 구성과 장부가치의 의미가 크게 다르다. PBR은 가능한 한 같은 업종 내 기업끼리 비교하는 것이 더 합리적이다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(136,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','PBR만으로 투자 판단을 내리기 전에 추가로 확인하면 좋은 정보는?','PBR이 낮아도 자산의 수익성이 떨어지면 저평가로 보기 어렵다. ROE 같은 수익성 지표와 업종 평균을 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(137,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','PBR에 대한 설명 중 옳지 않은 것은?','낮은 PBR도 자산의 수익성이 낮으면 저평가로 보기 어렵다. 업종 특성과 수익성 지표를 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(138,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','PBR 해석의 한계로 가장 적절한 것은?','장부상 순자산은 실제 시장가치나 자산의 수익 창출력과 다를 수 있다. PBR은 다른 지표와 함께 활용하는 보조 지표로 봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(139,4,1,2,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','PBR을 해석할 때 업종 특성과 자산의 수익성을 함께 확인하는 것이 좋다.','맞다. PBR의 적정 수준은 업종과 자산의 질에 따라 달라질 수 있어 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(140,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','상승 추세의 의미로 가장 적절한 것은?','상승 추세는 가격의 고점과 저점이 전반적으로 높아지는 흐름이다. 상승 중에도 일시적인 조정이 나타날 수 있어 기간을 두고 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(141,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','최근 저점이 9,500원 → 10,100원 → 10,900원으로, 최근 고점이 10,000원 → 10,800원 → 11,500원으로 이어졌다. 가장 적절한 판단은?','고점과 저점이 함께 순차적으로 높아지는 흐름은 상승 추세의 대표적인 특징이다. 다만 추세 지속 여부는 이후 흐름과 거래량으로 추가 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(142,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','주가가 20일 이동평균선 위에서 움직이고 이동평균선 자체도 우상향하고 있다. 가장 적절한 해석은?','주가가 우상향하는 이동평균선 위에서 움직이면 단기 상승 추세가 유지되고 있다고 해석할 수 있다. 다만 이동평균선 하나만으로 매매를 결정하기보다 거래량 등을 함께 봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(143,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','상승 추세 중 거래량이 함께 늘고 있다면 가장 적절한 해석은?','상승 국면에서 거래량이 함께 증가하면 매수세가 뒷받침되고 있다는 신호로 해석할 수 있다. 거래량 없이 가격만 오르는 경우보다 상대적으로 신뢰도가 높다고 볼 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(144,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','상승 추세에 대한 설명 중 옳지 않은 것은?','상승 추세 중에도 조정이나 되돌림이 나타나는 것은 자연스러운 현상이다. 추세는 한 방향으로만 움직이는 것을 보장하지 않는다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(145,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','상승 추세는 가격의 고점과 저점이 전반적으로 높아지는 흐름이다.','맞다. 다만 상승 흐름 중에도 조정이 나타날 수 있어 기간과 거래량을 함께 본다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(146,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','상승 추세 하나만 확인하면 매수 시점을 확정할 수 있다.','틀리다. 상승 추세는 여러 판단 재료 중 하나이며, 지지·저항, 거래량 등과 함께 살펴야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(147,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','상승 추세이던 종목의 저점이 점점 낮아지기 시작했다. 가장 적절한 다음 행동은?','저점이 이전보다 낮아지기 시작하면 추세 전환의 초기 신호일 수 있다. 한두 번의 움직임만으로 단정하기보다 이후 흐름을 좀 더 지켜봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(148,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','상승 추세를 판단할 때 가격 흐름 외에 함께 확인하면 좋은 정보는?','가격의 고점·저점 흐름뿐 아니라 거래량, 이동평균선, 지지·저항선을 함께 보면 추세의 신뢰도를 더 잘 판단할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(149,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','상승 추세를 해석할 때의 한계로 가장 적절한 것은?','추세는 과거 가격 흐름을 바탕으로 한 해석일 뿐 미래를 보장하지 않는다. 상승 추세 중에도 조정이나 추세 전환이 언제든 나타날 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(150,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','상승 추세 중 주가가 이전 고점 부근(저항선)에 다가가고 있다. 가장 적절한 해석은?','이전 고점(저항선) 부근에서는 차익 실현 매물이 나와 상승세가 둔화되거나 일시 조정이 나타나는 경우가 많다. 저항선 돌파 여부를 함께 지켜보는 것이 좋다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(151,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','상승 추세와 일시적 반등의 차이로 가장 적절한 것은?','상승 추세는 일정 기간에 걸쳐 고점과 저점이 함께 높아지는 흐름을 말한다. 하락 중 짧게 나타나는 반등과 혼동하지 않으려면 기간을 두고 관찰해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(152,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','상승 추세를 판단할 때는 일정 기간의 가격 흐름과 거래량을 함께 확인하는 것이 좋다.','맞다. 짧은 기간의 움직임만으로는 추세와 일시적 반등을 구분하기 어렵다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(153,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','하락 추세의 의미로 가장 적절한 것은?','하락 추세는 가격의 고점과 저점이 전반적으로 낮아지는 흐름이다. 하락 중에도 일시적 반등이 나타날 수 있어 기간을 두고 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(154,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','최근 고점이 12,000원 → 11,200원 → 10,500원으로, 최근 저점이 11,000원 → 10,300원 → 9,700원으로 이어졌다. 가장 적절한 판단은?','고점과 저점이 함께 순차적으로 낮아지는 흐름은 하락 추세의 대표적인 특징이다. 추세 지속 여부는 이후 흐름과 거래량으로 추가 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(155,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','주가가 20일 이동평균선 아래에서 움직이고 이동평균선도 우하향하고 있다. 가장 적절한 해석은?','주가가 우하향하는 이동평균선 아래에서 움직이면 단기 하락 추세가 유지되고 있다고 해석할 수 있다. 이동평균선 하나만으로 매매를 결정하기보다 다른 정보와 함께 봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(156,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','하락 추세 중 반등이 나왔지만 거래량이 크게 늘지 않았다. 가장 적절한 해석은?','거래량을 동반하지 않은 반등은 일시적인 되돌림일 가능성이 있다. 추세 전환으로 단정하기보다 이후 거래량과 가격 흐름을 함께 지켜봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(157,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','하락 추세에 대한 설명 중 옳지 않은 것은?','하락 추세 중에도 일시적인 반등이 나타나는 것은 자연스러운 현상이다. 추세가 한 방향으로만 움직이는 것을 보장하지는 않는다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(158,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','하락 추세는 가격의 고점과 저점이 전반적으로 낮아지는 흐름이다.','맞다. 다만 하락 흐름 중에도 반등이 나타날 수 있어 기간과 거래량을 함께 본다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(159,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','하루 상승만으로 하락 추세가 끝났다고 단정할 수 있다.','틀리다. 하락 추세 중 일시적 반등은 흔히 나타나므로 이후 고점과 저점 흐름을 더 지켜봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(160,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','하락 추세이던 종목의 저점이 더 이상 낮아지지 않고 비슷한 수준에서 유지되고 있다. 가장 적절한 다음 행동은?','저점이 더 이상 낮아지지 않는 흐름은 하락세가 진정되고 있다는 신호일 수 있다. 다만 고점도 함께 높아지는지 확인해야 추세 전환 여부를 더 신뢰할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(161,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','하락 추세 중 주가가 이전 저점 부근(지지선)에 다가가고 있다. 가장 적절한 해석은?','이전 저점(지지선) 부근에서는 저가 매수세가 유입돼 하락세가 일시적으로 멈추거나 반등이 나타나는 경우가 많다. 지지선이 실제로 지켜지는지 함께 지켜보는 것이 좋다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(162,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','하락 추세를 판단할 때 가격 흐름 외에 함께 확인하면 좋은 정보는?','가격의 고점·저점 흐름뿐 아니라 거래량, 이동평균선, 지지·저항선을 함께 보면 추세 전환 가능성을 더 잘 판단할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(163,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','하락 추세를 해석할 때의 한계로 가장 적절한 것은?','추세는 과거 가격 흐름을 바탕으로 한 해석일 뿐 미래를 보장하지 않는다. 하락 추세 중에도 반등이나 추세 전환이 언제든 나타날 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(164,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','하락 추세와 일시적 조정의 차이로 가장 적절한 것은?','하락 추세는 일정 기간에 걸쳐 고점과 저점이 함께 낮아지는 흐름을 말한다. 상승 중 짧게 나타나는 조정과 혼동하지 않으려면 기간을 두고 관찰해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(165,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','하락 추세를 판단할 때는 일정 기간의 가격 흐름과 거래량을 함께 확인하는 것이 좋다.','맞다. 짧은 기간의 움직임만으로는 추세와 일시적 반등을 구분하기 어렵다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(166,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','횡보의 의미로 가장 적절한 것은?','횡보는 가격이 뚜렷한 방향 없이 일정 범위 안에서 오르내리는 흐름이다. 상단과 하단의 범위, 거래량 변화를 함께 살펴야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(167,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','최근 몇 주간 주가가 9,800원~10,200원 사이에서 반복해서 오르내리고 있다. 가장 적절한 판단은?','일정한 가격 범위 안에서 오르내림이 반복되면 방향성이 뚜렷하지 않은 횡보 국면으로 볼 수 있다. 범위를 벗어나는 시점(돌파)을 함께 지켜보는 것이 좋다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(168,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','횡보 구간의 상단과 하단은 각각 무엇으로 볼 수 있는가?','횡보 구간의 상단은 매도세가 유입되는 저항선, 하단은 매수세가 유입되는 지지선 역할을 하는 경우가 많다. 이 범위를 벗어나는 돌파가 나오면 새로운 추세로 이어질 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(169,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','횡보에 대한 설명 중 옳지 않은 것은?','횡보 구간에서는 다음 방향을 미리 확정할 수 없다. 범위 돌파와 거래량 변화를 함께 확인하며 대응하는 것이 좋다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(170,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','횡보는 가격이 뚜렷한 방향 없이 일정 범위 안에서 움직이는 흐름이다.','맞다. 횡보 구간에서는 상단과 하단의 범위, 거래량 변화를 함께 살펴야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(171,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','횡보 국면은 거래량과 관계없이 항상 상승 추세로 이어진다.','틀리다. 횡보 이후에는 상승 추세로 이어질 수도, 하락 추세로 이어질 수도 있어 방향을 미리 단정할 수 없다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(172,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','횡보 중이던 종목이 거래량을 동반하며 구간 상단(저항선)을 강하게 돌파했다. 가장 적절한 해석은?','거래량을 동반한 저항선 돌파는 매수세 유입을 시사하며 새로운 상승 추세로 이어질 가능성을 높이는 신호로 해석할 수 있다. 다만 이후 흐름으로 추가 확인이 필요하다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(173,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','횡보 국면을 판단할 때 가격 범위 외에 함께 확인하면 좋은 정보는?','횡보 국면에서는 가격 범위뿐 아니라 거래량 변화와 상단·하단 돌파 시도를 함께 보면 이후 방향을 판단하는 데 도움이 된다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(174,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','횡보 국면 해석의 한계로 가장 적절한 것은?','횡보는 방향성이 정해지지 않은 구간이므로 언제, 어느 방향으로 돌파될지 미리 확정할 수 없다. 돌파 이후의 거래량과 흐름을 함께 확인하는 것이 안전하다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(175,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','횡보와 상승 추세 중 일시적 조정의 차이로 가장 적절한 것은?','횡보는 방향성이 뚜렷하지 않은 채 일정 범위에서 지속되는 흐름이고, 조정은 상승 추세 안에서 짧게 나타나는 하락이다. 기간과 고점·저점의 흐름으로 구분할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(176,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','A종목은 여러 달째 좁은 범위에서 횡보 중이며 거래량도 계속 줄고 있다. 가장 적절한 해석은?','거래량이 계속 줄어드는 횡보는 시장의 관심이 낮아졌다는 신호일 수 있다. 이후 거래량이 다시 늘어나는 시점과 방향을 함께 지켜보는 것이 좋다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(177,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','횡보 구간을 해석할 때는 가격 범위뿐 아니라 거래량 변화를 함께 확인하는 것이 좋다.','맞다. 거래량 변화는 횡보 이후 방향을 가늠하는 데 도움이 되는 정보다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(178,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','거래량 변화의 의미로 가장 적절한 것은?','거래량 변화는 일정 기간의 거래량이 이전 기간보다 늘었는지 줄었는지를 보여주는 지표로, 가격 흐름과 함께 해석해야 의미가 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(179,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','어떤 종목의 하루 평균 거래량이 지난주 10만 주에서 이번 주 40만 주로 늘었다. 이 정보만으로 알 수 있는 것은?','거래량 증가는 매매 활동이 활발해졌다는 의미일 뿐 방향을 알려주지 않는다. 같은 기간의 주가 흐름과 함께 봐야 상승·하락 어느 쪽 힘이 강했는지 가늠할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(180,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','거래량 변화에 대한 설명 중 옳지 않은 것은?','거래량 급감이 다음 거래일의 주가 방향을 결정짓지는 않는다. 거래량 변화는 가격 흐름, 관련 뉴스와 함께 해석해야 의미가 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(181,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','거래량 변화는 일정 기간의 거래량이 이전 기간에 비해 증가했는지 감소했는지를 나타내는 변화이다.','맞다. 거래량 변화는 가격 흐름과 함께 봐야 매매 강도를 제대로 해석할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(182,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','거래량이 급증하면 그 방향과 관계없이 항상 좋은 매수 신호다.','틀리다. 거래량 급증은 매도세가 강할 때도 나타날 수 있어 방향과 원인을 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(183,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','상승하던 주가가 거래량이 눈에 띄게 줄어들면서 상승폭도 함께 둔화되고 있다. 가장 적절한 해석은?','상승 국면에서 거래량이 줄어드는 것은 매수 동력이 약해지고 있다는 신호로 해석되기도 한다. 이후 가격과 거래량 흐름을 함께 지켜보는 것이 좋다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(184,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','거래량 변화를 해석할 때 함께 확인하면 좋은 정보는?','거래량 변화 자체는 방향성이 없는 정보다. 같은 기간의 주가 움직임과 거래량 변화의 배경을 함께 봐야 의미 있는 해석이 가능하다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(185,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','거래량 변화 해석의 한계로 가장 적절한 것은?','거래량은 매수와 매도 양쪽 체결을 모두 합산한 값이라 그 자체로는 방향을 구분하지 못한다. 가격 흐름과 함께 봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(186,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','거래량 급증과 거래량 급감이 각각 시사할 수 있는 점으로 가장 적절한 것은?','거래량 급증은 특정 계기로 관심이 몰렸을 가능성을, 급감은 관심이 줄어 관망세가 짙어졌을 가능성을 시사할 수 있다. 다만 방향은 가격 흐름과 함께 판단해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(187,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','실적 발표를 앞두고 거래량이 평소보다 크게 늘고 있다. 가장 적절한 해석은?','이벤트를 앞두고 거래량이 느는 것은 시장의 관심이 커졌다는 의미일 수 있지만 결과의 방향까지 알려주지는 않는다. 발표 이후 실제 가격 반응을 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(188,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','거래량 변화를 해석하는 태도로 가장 적절하지 않은 것은?','거래량은 매매 강도를 보여줄 뿐 방향을 확정해 주지 않는다. 배경과 가격 흐름을 함께 확인하는 태도가 필요하다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(189,5,1,3,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','거래량 변화를 해석할 때는 같은 기간의 가격 흐름을 함께 확인하는 것이 좋다.','맞다. 거래량은 방향성이 없는 정보이므로 가격 흐름과 함께 봐야 의미 있는 해석이 가능하다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(190,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','정기예금의 의미로 가장 적절한 것은?','정기예금은 일정 기간 목돈을 금융기관에 맡기고 약정된 금리에 따라 이자를 받는 예금 상품이다. 만기, 중도해지 조건, 예금자보호 여부를 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(191,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','정기예금 가입 전 확인해야 할 조건으로 가장 거리가 먼 것은?','정기예금은 금리, 만기, 중도해지 조건, 예금자보호 여부가 실질 수익과 안전성을 좌우한다. 은행의 주가 흐름은 예금 상품 자체의 조건과는 관련이 없는 정보다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(192,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','정기예금 만기 전에 중도해지하면 일반적으로 어떤 일이 발생하는가?','정기예금은 약정 기간을 채우지 못하고 중도해지하면 대개 약정 금리보다 낮은 중도해지 이율이 적용된다. 자금이 필요한 시점을 고려해 만기를 선택하는 것이 좋다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(193,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','정기예금에 대한 설명 중 옳지 않은 것은?','정기예금은 안전자산 중 하나일 뿐이며 그 자체로 다른 투자자산의 매수·매도를 결정하는 근거가 되지 않는다. 예금은 예금대로 조건을 따져 활용해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(194,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','정기예금은 일정 기간 목돈을 금융기관에 맡기고 약정된 조건에 따라 이자를 받는 예금 상품이다.','맞다. 정기예금은 정해진 만기와 금리 조건에 따라 이자가 지급되는 대표적인 안전자산이다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(195,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','정기예금은 예금자보호 한도와 관계없이 예치 금액 전액이 항상 보호된다.','틀리다. 예금자보호는 금융기관별로 원금과 소정의 이자를 합쳐 5천만 원까지만 보호되며 초과 금액은 보호 대상이 아닐 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(196,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','A씨는 1년 뒤 목돈이 필요해 정기예금 가입을 고려하고 있다. 가장 적절한 확인 순서는?','정기예금은 자금이 필요한 시점에 맞춰 만기를 정하고, 금리와 중도해지 조건, 예금자보호 한도까지 함께 비교하는 것이 안전하다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(197,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','세전 금리가 동일한 두 정기예금 상품이 있다면 실제 받는 이자를 비교할 때 추가로 확인할 정보는?','표면 금리가 같아도 이자 지급 방식이나 세금 처리 방식에 따라 실제로 받는 세후 이자는 달라질 수 있다. 조건을 꼼꼼히 비교해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(198,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','정기예금 투자에서 유의해야 할 점으로 가장 적절한 것은?','예금자보호 제도는 금융기관별로 한도가 정해져 있어 한도를 초과하는 금액은 위험에 노출될 수 있다. 큰 금액을 예치할 때는 이 점을 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(199,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','정기예금과 적금의 차이를 옳게 설명한 것은?','정기예금은 목돈을 한 번에 예치하는 상품이고, 적금은 정해진 기간 동안 금액을 나누어 납입해 목돈을 만드는 상품이다. 두 상품은 납입 구조와 이자 계산 방식이 다르다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(200,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','적금의 의미로 가장 적절한 것은?','적금은 일정 기간 금액을 나누어 납입해 목돈을 만들어 가는 금융상품이다. 매월 납입한 금액마다 예치 기간이 달라 실제 이자 계산 방식을 이해해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(201,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','같은 표면 금리라도 정기예금과 적금의 실제 이자가 다를 수 있는 이유로 가장 적절한 것은?','적금은 매월 납입한 금액마다 만기까지 남은 예치 기간이 다르므로, 초기에 낸 돈과 마지막에 낸 돈이 실제로 이자가 붙는 기간이 다르다. 그래서 같은 표면 금리라도 정기예금보다 실제 이자가 적을 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(202,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','월 10만 원씩 12개월 납입하는 적금에서 마지막 회차(12회차) 납입금에 적용되는 이자 발생 기간으로 가장 적절한 것은?','적금은 납입 회차마다 만기까지 남은 기간이 다르다. 첫 회차 납입금은 12개월 내내 이자가 붙지만 마지막 회차는 약 1개월분의 이자만 붙는다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(203,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','적금에 대한 설명 중 옳지 않은 것은?','적금은 회차별로 예치 기간이 다르기 때문에 납입금마다 실제 적용되는 이자가 달라진다. 모든 납입금에 동일한 이자가 적용된다는 설명은 옳지 않다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(204,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','적금은 일정 기간 금액을 나누어 납입해 목돈을 만들어 가는 금융상품이다.','맞다. 적금은 매월 일정 금액을 납입해 만기에 원금과 이자를 함께 받는 상품이다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(205,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','적금의 표면 금리와 실제 수령하는 이자율은 항상 정확히 일치한다.','틀리다. 회차별 예치 기간 차이 때문에 실제 받는 이자는 표면 금리보다 낮게 느껴질 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(206,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','B씨는 정기예금과 적금 중 어느 것이 유리한지 고민하고 있다. 가장 적절한 조언은?','정기예금과 적금은 자금 상황과 목적에 따라 적합한 상품이 다르다. 이미 목돈이 있는지, 매월 모아가는 것인지에 따라 선택하고 조건을 비교해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(207,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','적금 가입 시 표면 금리 외에 추가로 확인하면 좋은 정보는?','적금은 우대금리 조건 충족 여부나 납입 한도에 따라 실제 받는 이자가 달라질 수 있다. 표면 금리만 보지 말고 실제 이자 계산 방식을 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(208,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','적금 투자에서 유의해야 할 점으로 가장 적절한 것은?','적금은 만기를 채우지 못하고 중도해지하면 대개 낮은 중도해지 이율이 적용된다. 꾸준히 납입할 수 있는 금액으로 계획하는 것이 좋다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(209,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','적금과 정기예금의 이자 계산 구조를 비교한 설명으로 가장 적절한 것은?','정기예금은 한 번에 예치한 금액 전체에 같은 기간만큼 이자가 붙지만, 적금은 납입 회차마다 예치 기간이 달라 이자 계산 구조가 다르다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(210,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','채권의 의미로 가장 적절한 것은?','채권은 정부, 공공기관, 기업 등이 자금을 조달하기 위해 발행하며 정해진 이자와 원금 지급을 약속하는 증권이다. 발행자의 신용도에 따라 위험 수준이 달라진다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(211,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','시중 금리가 상승할 때 기존에 발행된 채권의 가격은 일반적으로 어떻게 되는가?','시중 금리가 오르면 새로 발행되는 채권이 더 높은 이자를 지급하므로, 상대적으로 이자율이 낮은 기존 채권의 매력이 떨어져 가격이 하락하는 경향이 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(212,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','채권 투자에서 신용위험이란 무엇을 의미하는가?','신용위험은 채권을 발행한 국가나 기업이 약속한 이자·원금을 제때 지급하지 못할 가능성을 말한다. 신용등급이 낮을수록 신용위험이 크다고 볼 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(213,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','채권에 대한 설명 중 옳지 않은 것은?','채권도 발행자의 부도(신용위험)나 금리 변동에 따른 가격 하락으로 손실이 발생할 수 있다. 국채라도 만기 전 매도 시 가격 변동 위험이 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(214,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','채권은 정부, 공공기관, 기업 등이 자금을 조달하기 위해 발행하며 정해진 조건에 따라 이자와 원금 지급을 약속하는 증권이다.','맞다. 채권은 발행자가 만기에 원금과 약정 이자를 갚기로 약속한 채무 증권이다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(215,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','채권은 발행자와 관계없이 항상 주식보다 안전하며 손실 위험이 전혀 없다.','틀리다. 채권도 발행자의 신용위험, 금리위험, 유동성위험에 따라 가격이 하락하거나 원리금을 받지 못할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(216,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','C씨는 신용등급이 낮은 기업이 발행한 채권의 금리가 국채보다 훨씬 높은 것을 보았다. 가장 적절한 해석은?','신용등급이 낮은 채권은 부도 위험을 보상하기 위해 높은 금리를 제시하는 경우가 많다. 높은 금리만 보고 투자하기보다 발행자의 신용위험을 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(217,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','채권 투자 전 추가로 확인하면 좋은 정보는?','채권의 위험과 수익은 발행자의 신용등급, 만기, 금리 조건에 따라 달라진다. 이러한 정보를 함께 확인해야 합리적인 판단이 가능하다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(218,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','채권 투자에서 유의해야 할 위험으로 가장 거리가 먼 것은?','채권은 만기까지 보유하면 약정된 이자와 원금을 받는 것이 기본 구조다. 신용위험, 금리위험, 유동성위험이 채권 투자에서 실제로 유의해야 할 위험이다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(219,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','채권 가격과 시중 금리의 관계를 옳게 설명한 것은?','시중 금리가 오르면 상대적으로 낮은 이자를 주는 기존 채권의 매력이 떨어져 가격이 하락하는 경향이 있고, 금리가 내리면 반대 현상이 나타나는 경우가 많다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(220,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','펀드의 의미로 가장 적절한 것은?','펀드는 여러 투자자의 자금을 모아 정해진 투자 목적과 운용 전략에 따라 주식, 채권 등에 투자하는 금융상품이다. 운용 전략과 수수료, 투자 대상을 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(221,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','펀드가 항상 분산투자를 보장하는 상품은 아닌 이유로 가장 적절한 것은?','펀드는 분산형 상품도 있지만 특정 업종, 테마, 국가 등에 집중 투자하는 상품도 있다. 이름만으로 분산 정도를 판단하지 말고 투자설명서의 운용 전략을 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(222,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','펀드 투자 시 수수료·보수가 중요한 이유로 가장 적절한 것은?','펀드는 운용보수, 판매수수료 등 다양한 비용이 지속적으로 발생한다. 같은 성과라도 비용이 높으면 투자자가 실제로 받는 수익률은 낮아질 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(223,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','펀드에 대한 설명 중 옳지 않은 것은?','펀드는 투자 실적에 따라 원금 손실이 발생할 수 있는 실적배당형 상품이다. 예금과 달리 원금이 보장되지 않는다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(224,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','펀드는 여러 투자자의 자금을 모아 정해진 투자 목적과 운용 전략에 따라 주식, 채권 등 자산에 투자하는 금융상품이다.','맞다. 펀드는 전문 운용사가 투자자를 대신해 정해진 전략에 따라 자산을 운용하는 상품이다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(225,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','펀드에 가입하면 원금 손실 없이 항상 예금과 동일한 수준으로 안전하다.','틀리다. 펀드는 투자 실적에 따라 원금 손실이 발생할 수 있는 실적배당형 상품으로, 예금자보호 대상이 아니다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(226,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','D씨는 \'국내 주식형 펀드\'와 \'특정 산업 테마 펀드\' 중 하나를 고르려 한다. 가장 적절한 확인은?','펀드는 이름만으로 투자 대상과 분산 정도를 정확히 알기 어렵다. 투자설명서를 통해 실제 편입 자산과 업종 집중도를 비교하는 것이 좋다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(227,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','펀드 가입 전 추가로 확인하면 좋은 정보로 가장 적절한 것은?','펀드는 운용 전략과 투자 대상, 비용 구조에 따라 위험과 수익이 크게 달라진다. 이러한 정보를 투자설명서에서 확인하는 것이 중요하다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(228,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','펀드 투자에서 유의해야 할 위험으로 가장 적절한 것은?','펀드는 투자 대상의 가격 변동에 따라 손익이 결정되는 실적배당형 상품이다. 운용 전략이 특정 자산에 집중될수록 손실 폭이 커질 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(229,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','펀드의 분산투자 효과를 판단할 때 가장 적절한 방법은?','펀드의 이름이나 판매사 규모는 실제 분산 정도를 보장하지 않는다. 편입된 자산의 종류와 업종, 국가 구성을 직접 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(230,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','ETF의 의미로 가장 적절한 것은?','ETF는 거래소에 상장되어 주식처럼 실시간으로 매매할 수 있는 펀드다. 추종지수, 괴리율, 운용보수 등을 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(231,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','ETF의 시장가격과 순자산가치(NAV) 사이에 괴리율이 발생하는 이유로 가장 적절한 것은?','ETF는 거래소에서 실시간으로 거래되기 때문에 수급 상황에 따라 시장가격이 순자산가치(NAV)와 일시적으로 차이 나는 괴리율이 발생할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(232,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','특정 산업 하나에 집중 투자하는 테마 ETF에 투자할 때 유의할 점으로 가장 적절한 것은?','특정 산업에 집중 투자하는 테마 ETF는 그 산업에 부정적 이슈가 생기면 지수를 폭넓게 추종하는 ETF보다 더 크게 흔들릴 수 있다. 집중도를 확인하는 것이 중요하다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(233,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','ETF에 대한 설명 중 옳지 않은 것은?','ETF는 거래소에서 실시간 거래되는 특성상 시장가격과 순자산가치 사이에 괴리율이 발생할 수 있다. 이는 ETF 투자 시 확인해야 할 요소다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(234,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','ETF는 거래소에 상장되어 주식처럼 거래할 수 있는 펀드이다.','맞다. ETF는 일반 펀드와 달리 거래소에서 실시간으로 사고팔 수 있다는 특징이 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(235,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','모든 ETF는 시장 전체 지수만 추종하며 특정 산업에 집중 투자하는 상품은 존재하지 않는다.','틀리다. ETF에는 시장 지수를 추종하는 상품뿐 아니라 특정 산업이나 테마에 집중 투자하는 상품도 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(236,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','E씨는 코스피200 지수를 추종하는 ETF의 시장가격이 순자산가치보다 눈에 띄게 높게 거래되는 것을 보았다. 가장 적절한 해석은?','ETF의 시장가격이 순자산가치보다 크게 높거나 낮으면 일시적인 수급 불균형에 따른 괴리율일 수 있다. 매매 시점에 괴리율 수준을 확인하는 것이 좋다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(237,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','ETF 투자 전 추가로 확인하면 좋은 정보는?','ETF는 어떤 지수나 전략을 추종하는지, 운용보수는 얼마인지, 괴리율이 얼마나 발생하는지에 따라 투자 성과가 달라진다. 이러한 정보를 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(238,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','ETF 투자에서 유의해야 할 위험으로 가장 적절한 것은?','ETF도 추종 대상의 가격 변동에 따라 손실이 발생할 수 있는 실적배당형 상품이다. 특정 산업에 집중된 ETF는 그 산업 이슈에 따라 변동성이 더 커질 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(239,1,1,4,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','ETF와 일반 펀드의 가장 큰 차이로 옳은 것은?','ETF는 거래소 상장 상품으로 주식처럼 장중 실시간 가격에 매매할 수 있지만, 일반 펀드는 보통 하루 한 번 산정되는 기준가로 거래가 이뤄진다는 차이가 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(240,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','원금 손실 위험의 의미로 가장 적절한 것은?','원금 손실 위험은 투자 결과 투자한 원금보다 적은 금액을 회수하게 될 가능성을 말한다. 실적배당형 상품은 예금과 달리 이 위험을 피할 수 없다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(241,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','원금 손실과 원금 손실 위험의 차이로 옳은 것은?','원금 손실은 이미 발생한 결과이고, 원금 손실 위험은 앞으로 그런 결과가 나타날 가능성을 의미한다. 투자를 결정하기 전에는 위험 쪽을 살펴야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(242,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','A씨는 주식형 펀드에 1,000만 원을 투자했는데 6개월 뒤 평가금액이 850만 원이 되었다. 이 상황을 가장 적절하게 설명한 것은?','실적배당형 상품은 매도하기 전까지는 평가손익일 뿐이며, 이후 가격 변동에 따라 손실 폭이 줄거나 늘어날 수 있다. 손실을 확정하는 시점은 매도 시점이다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(243,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','원금 손실 위험에 대한 설명 중 옳지 않은 것은?','금융상품마다 원금 손실 위험의 크기는 다르다. 예금처럼 상대적으로 안전한 상품이 있는가 하면 주식처럼 위험이 큰 상품도 있어 동일하게 취급할 수 없다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(244,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','원금 손실 위험은 투자 결과 투자한 원금보다 적은 금액을 회수하게 될 가능성이다.','맞다. 이 위험은 상품의 종류와 투자 대상에 따라 크기가 달라진다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(245,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','주식이나 펀드에 투자하면 보유 기간과 관계없이 원금 손실 위험이 사라진다.','틀리다. 주식이나 펀드는 가격이 원금 이하로 유지되면 언제든 손실이 발생할 수 있는 실적배당형 상품이다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(246,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','B씨는 원금 손실 위험을 줄이기 위해 여러 종목에 나누어 투자했지만 그중 상당수가 같은 업종이었다. 가장 적절한 평가는?','여러 종목에 투자해도 업종이 겹치면 그 업종에 악재가 생겼을 때 함께 타격을 받을 수 있다. 종목 수뿐 아니라 업종과 자산군의 분산도 함께 봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(247,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','원금 손실 위험을 가늠하기 위해 투자 전 확인하면 좋은 정보는?','원금 손실 위험의 크기는 투자 대상의 변동성, 신용도, 유동성, 투자 기간 등 여러 요소에 따라 달라진다. 이러한 정보를 종합적으로 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(248,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','원금 손실 위험이 상대적으로 큰 투자로 가장 적절한 것은?','소수 종목이나 특정 산업에 집중하면 그 대상에 악재가 생겼을 때 손실이 크게 확대될 수 있다. 반대로 분산이 잘 되거나 신용도가 높은 자산은 상대적으로 손실 위험이 낮다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(249,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','원금 손실 위험과 변동성의 관계로 가장 적절한 것은?','변동성이 큰 자산은 가격이 크게 오르내릴 수 있어 원금 아래로 떨어질 가능성도 상대적으로 커진다. 다만 변동성과 손실 위험이 완전히 같은 개념은 아니다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(250,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','C씨는 손실을 만회하기 위해 하락한 종목에 자금을 추가로 투입하는 것을 고려하고 있다. 가장 적절한 조언은?','하락한 자산에 추가로 투자한다고 해서 손실 회복이 보장되는 것은 아니다. 하락 원인을 먼저 점검하고 신중하게 판단해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(251,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','원금 손실 위험은 상품 종류, 투자 대상, 분산 정도에 따라 다르게 나타난다.','맞다. 같은 금액을 투자해도 대상과 분산 방식에 따라 원금 손실 위험의 크기는 달라질 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(252,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','D씨의 포트폴리오는 국내 한 산업의 주식에 90%가 집중되어 있다. 가장 적절한 위험 판단은?','특정 산업에 자산 대부분이 집중되면 그 산업의 업황 악화가 포트폴리오 전체에 큰 손실로 이어질 수 있다. 자산군과 업종을 나누는 것이 위험을 줄이는 데 도움이 된다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(253,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','해외 자산에 투자할 때 원금 손실 위험을 키울 수 있는 추가 요인으로 가장 적절한 것은?','해외 자산은 현지 가격이 올라도 환율이 원화 강세로 움직이면 원화로 환산한 가치가 줄어들 수 있다. 환율위험은 해외 투자에서 추가로 고려해야 하는 요인이다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(254,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','원금 손실 위험을 줄이기 위한 방법으로 가장 적절한 것은?','자산군과 업종, 국가를 나누고 투자 기간과 감내 가능한 손실 수준을 미리 정해 두면 원금 손실 위험을 관리하는 데 도움이 된다. 위험을 완전히 없앨 수는 없다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(255,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','원금 손실 위험 관리의 한계로 가장 적절한 것은?','분산투자나 위험 관리는 손실 가능성을 줄이는 데 도움이 되지만 완전히 없애지는 못한다. 시장 전체가 흔들리는 상황에서는 분산된 자산도 함께 하락할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(256,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','원금 손실 위험을 판단할 때는 투자 대상의 변동성, 신용도, 분산 정도를 함께 고려하는 것이 좋다.','맞다. 원금 손실 위험은 여러 요인이 함께 작용하므로 종합적으로 판단해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(257,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','변동성의 의미로 가장 적절한 것은?','변동성은 가격이나 수익률이 일정 기간 얼마나 크게 오르내리는지를 나타내는 지표다. 변동성이 크다는 것은 손실 폭과 수익 폭이 함께 커질 수 있다는 의미다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(258,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','변동성이 크다는 것과 손실이 확정됐다는 것의 차이로 옳은 것은?','변동성은 가격의 등락 폭을 나타내는 지표일 뿐, 손실이나 이익이 확정됐다는 의미는 아니다. 변동성이 큰 자산도 매도 시점에 따라 이익이 날 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(259,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','E기업의 최근 3개월 주가는 8,000원~15,000원 사이를 오갔고, F기업은 같은 기간 9,500원~10,500원 사이에서 움직였다. 가장 적절한 판단은?','같은 기간 가격 변동 폭이 클수록 변동성이 높다고 볼 수 있다. E기업은 가격이 오간 범위가 더 넓어 상대적으로 변동성이 큰 종목으로 볼 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(260,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','변동성에 대한 설명 중 옳지 않은 것은?','변동성이 크다는 것은 위험이 크다는 의미이지 항상 나쁘다는 뜻은 아니다. 투자자의 성향과 목표에 따라 변동성을 받아들이는 정도가 다를 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(261,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','변동성은 가격이나 수익률이 오르내리는 정도이다.','맞다. 변동성이 클수록 가격의 등락 폭이 크다는 의미다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(262,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','변동성이 큰 자산은 항상 원금 손실이 확정된 자산이다.','틀리다. 변동성은 가격이 오르내리는 폭을 나타낼 뿐이며, 손실 여부는 매도 시점의 가격에 따라 달라진다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(263,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','G씨는 변동성이 큰 종목을 보고 불안해서 하락한 첫날 바로 매도했는데, 이후 며칠 만에 가격이 원래 수준을 회복했다. 가장 적절한 해석은?','변동성이 큰 자산은 단기간에 가격이 크게 하락했다가도 회복되는 경우가 있다. 특정 시점의 가격 변동에 즉흥적으로 반응하기보다 투자 목적과 기간, 손실 허용 범위 등 미리 정한 기준에 따라 판단하는 것이 바람직하다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(264,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','변동성이 큰 자산에 투자할 때 추가로 확인하면 좋은 정보는?','변동성이 큰 자산은 짧은 기간에 가격이 크게 움직일 수 있어, 투자자가 감내할 수 있는 손실 수준과 투자 기간을 먼저 점검하는 것이 중요하다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(265,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','변동성이 큰 자산에 투자할 때 유의할 점으로 가장 적절한 것은?','변동성이 큰 자산은 단기간에 가격이 크게 하락할 수 있어 원금 손실 위험도 함께 커진다. 투자자가 감내할 수 있는 수준인지 미리 점검해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(266,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','변동성과 분산투자의 관계로 가장 적절한 것은?','가격이 서로 다른 방향으로 움직이는 자산을 함께 보유하면 한쪽의 하락을 다른 쪽이 상쇄해 포트폴리오 전체의 변동성을 낮추는 데 도움이 될 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(267,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','변동성 지표의 한계로 가장 적절한 것은?','변동성은 과거 가격 흐름을 바탕으로 계산되며, 시장 상황이 바뀌면 앞으로의 변동성도 달라질 수 있다. 과거 수치만으로 미래를 단정할 수 없다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(268,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','H씨는 변동성이 낮은 자산만으로 포트폴리오를 구성했다. 가장 적절한 평가는?','변동성이 낮은 자산은 상대적으로 안정적이지만 그만큼 기대 수익률도 낮은 경우가 많다. 위험과 기대수익은 서로 맞물려 있는 경우가 많다는 점을 함께 고려해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(269,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','I씨는 변동성이 큰 종목의 하루 등락률만 보고 그 종목의 장기 위험 수준을 판단하려 한다. 가장 적절한 조언은?','하루의 등락률은 특정 이벤트로 인한 일시적 변동일 수 있다. 변동성을 제대로 판단하려면 일정 기간에 걸친 가격 흐름을 함께 봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(270,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','포트폴리오 전체의 변동성을 낮추는 데 도움이 되는 방법으로 가장 적절한 것은?','서로 다른 방향으로 움직이는 자산을 함께 담으면 특정 자산의 급락이 포트폴리오 전체에 미치는 영향을 줄일 수 있다. 이는 분산투자의 대표적인 효과다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(271,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','변동성은 손실 가능성을 자동으로 없애는 장치다.','틀리다. 변동성은 가격이 오르내리는 정도를 나타내는 지표일 뿐, 그 자체로 손실을 막아주지 않는다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(272,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','변동성을 다른 자료와 함께 봐야 하는 이유로 가장 적절한 것은?','변동성은 가격의 등락 폭만 보여줄 뿐 그 원인이 되는 실적이나 재무 상태, 산업 환경까지 설명하지 못한다. 다른 정보와 함께 살펴봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(273,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','변동성이 큰 자산에 투자할 때는 감내 가능한 손실 수준과 투자 기간을 미리 정해 두는 것이 좋다.','맞다. 변동성이 큰 자산은 단기간에 가격이 크게 움직일 수 있어 사전에 원칙을 정해 두는 것이 중요하다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(274,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','분산투자의 의미로 가장 적절한 것은?','분산투자는 여러 자산이나 종목에 나누어 투자해 특정 위험에 대한 집중을 줄이는 방법이다. 종목 수뿐 아니라 업종, 자산군, 국가의 분산도 함께 고려해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(275,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','종목 수를 많이 늘렸다고 해서 항상 충분히 분산된 것은 아닌 이유로 가장 적절한 것은?','분산 효과는 종목 수가 아니라 서로 다른 방향으로 움직이는 자산을 얼마나 담았는지에 달려 있다. 같은 업종에 몰리면 종목 수가 많아도 분산 효과는 제한적이다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(276,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','A씨의 포트폴리오는 국내 IT 업종 종목 10개로 구성되어 있다. 가장 적절한 평가는?','같은 업종에 종목이 몰려 있으면 그 업종에 악재가 생겼을 때 포트폴리오 전체가 함께 흔들릴 수 있다. 업종을 나누어 담는 것이 분산 효과를 높이는 데 중요하다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(277,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','분산투자에 대한 설명 중 옳지 않은 것은?','분산투자는 위험을 줄이는 데 도움을 줄 뿐 손실 가능성을 완전히 없애거나 결과를 확정해 주지는 않는다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(278,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','분산투자는 여러 자산이나 종목에 나누어 투자해 특정 위험에 대한 집중을 줄이는 방법이다.','맞다. 다만 어떤 기준으로 나누어 담느냐에 따라 실제 분산 효과는 달라질 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(279,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','자산 간 상관관계와 관계없이 종목 수만 늘리면 분산 효과는 항상 동일하게 커진다.','틀리다. 서로 비슷하게 움직이는 자산끼리는 종목 수를 늘려도 분산 효과가 크지 않을 수 있어 자산 간 상관관계를 함께 봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(280,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','B씨는 국내 주식과 국내 채권에 나누어 투자했는데, 금융위기 상황에서 두 자산이 함께 크게 하락했다. 가장 적절한 해석은?','평소 다르게 움직이던 자산이라도 시장 전체가 크게 흔들리는 위기 상황에서는 상관관계가 높아져 함께 하락할 수 있다. 분산투자가 모든 위험을 없애 주지는 않는다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(281,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','분산투자 효과를 판단할 때 종목 수 외에 함께 확인하면 좋은 정보는?','분산투자의 실제 효과는 종목 수보다 업종·국가 구성과 자산 간 상관관계에 더 크게 좌우된다. 이런 정보를 함께 살펴야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(282,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','분산투자로도 줄이기 어려운 위험으로 가장 적절한 것은?','개별 기업이나 업종, 국가에 따른 위험은 분산투자로 어느 정도 줄일 수 있지만, 시장 전체가 함께 흔들리는 체계적 위험은 분산투자만으로 완전히 없애기 어렵다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(283,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','업종 분산과 자산군 분산의 차이로 가장 적절한 것은?','업종 분산은 주식 내에서 산업을 나누는 것이고, 자산군 분산은 주식, 채권, 현금성 자산처럼 성격이 다른 자산을 함께 담는 것이다. 두 가지를 함께 고려하면 위험 분산에 더 도움이 된다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(284,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','C씨는 국내 자산에만 투자하다가 해외 자산을 일부 편입해 국가를 나누기로 했다. 가장 적절한 기대 효과는?','국가를 나누어 투자하면 특정 국가의 경제 상황에 대한 의존도를 낮출 수 있지만, 환율 변동 등 해외 투자 특유의 위험이 새로 생길 수 있다는 점도 함께 고려해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(285,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','분산투자의 한계로 가장 적절한 것은?','분산투자는 특정 위험에 대한 집중을 줄여주는 방법이지만 시장 전체 위험까지 없애거나 수익을 보장하지는 않는다. 위험 관리 수단 중 하나로 이해해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(286,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','분산투자를 실천하는 방법으로 가장 적절하지 않은 것은?','펀드 이름이 다르더라도 실제로 담고 있는 자산이 겹치면 분산 효과가 크지 않을 수 있다. 실제 편입 자산까지 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(287,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','집중투자와 분산투자를 비교할 때 고려할 점으로 가장 적절한 것은?','집중투자는 예측이 맞을 때 수익이 크지만 틀리면 손실도 커지는 구조다. 분산투자는 손실 폭을 완화하는 대신 한 자산이 크게 오를 때의 효과도 함께 줄어드는 경향이 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(288,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','분산투자 효과를 판단할 때는 종목 수뿐 아니라 업종, 자산군, 국가, 자산 간 상관관계를 함께 고려하는 것이 좋다.','맞다. 종목 수만으로는 실제 분산 효과를 제대로 판단하기 어렵다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(289,1,1,5,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','분산투자를 계획할 때 함께 고려하면 좋은 위험 요소로 가장 적절한 것은?','자산마다 신용위험, 금리위험, 유동성위험, 환율위험 등 서로 다른 위험 요인을 가진다. 분산투자를 계획할 때는 이런 위험 요인의 성격도 함께 고려하는 것이 좋다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(290,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','기업 A의 PER은 18배에서 12배로 낮아졌고 ROE는 8%에서 14%로 상승했다. 가장 적절한 해석은?','PER은 가격 수준, ROE는 자기자본 수익성을 보여준다. 두 지표가 모두 긍정적으로 보일 수 있어도 업종, 성장성, 이익 지속성, 재무상태를 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(291,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','기업 B의 PER은 7배로 낮지만 ROE가 3%이고 이익이 계속 감소하고 있다. 적절한 판단은?','PER이 낮아도 이익 감소와 낮은 수익성이 동반되면 위험 신호일 수 있다. PER과 ROE는 각각 따로 해석해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(292,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','기업 C의 ROE가 20%로 높지만 부채가 크게 늘어났다. 확인할 내용은?','ROE는 부채 활용이 커질 때 높아질 수 있다. 수익성뿐 아니라 재무구조와 이익의 질을 함께 봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(293,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','PER과 ROE를 함께 볼 때 옳은 설명은?','PER과 ROE는 서로 다른 정보를 제공한다. 둘을 하나의 점수처럼 합치기보다 각각의 의미를 비교해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(294,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','PER이 낮으면 어떤 업종과 상황에서도 반드시 좋은 투자 대상이다.','틀리다. 낮은 PER은 가격 부담이 낮아 보일 수 있지만 성장성 둔화나 이익 감소를 반영할 수도 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(295,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','기업 D의 PER은 25배이고 ROE는 22%다. 가장 균형 잡힌 해석은?','높은 ROE는 수익성 측면에서 긍정적일 수 있다. 다만 PER이 높으면 성장 기대와 이익 지속성을 함께 봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(296,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','기업 E의 PER은 9배, ROE는 4%이고 같은 업종 평균 ROE는 12%다. 적절한 판단은?','PER이 낮아 보여도 ROE가 업종보다 낮다면 시장이 낮은 수익성을 반영했을 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(297,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','ROE가 높아도 일회성 이익, 부채 증가, 업종 특성을 함께 확인해야 한다.','맞다. ROE는 수익성 지표지만 원인과 지속성을 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(298,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','기업 F의 PER은 14배로 업종 평균 13배와 비슷하지만 ROE는 6%로 업종 평균 15%보다 낮다. 해석은?','PER과 ROE는 서로 다른 지표다. 가격 수준이 평균과 비슷해도 수익성은 낮을 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(299,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','PER과 ROE 해석의 한계로 가장 적절한 것은?','PER과 ROE는 유용하지만 기업 전체를 모두 설명하지 않는다. 성장성, 현금흐름, 부채 구조도 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(300,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','기업 G는 PER 6배, ROE 18%지만 최근 이익 대부분이 자산 매각 이익이었다. 가장 적절한 확인은?','일회성 이익은 PER과 ROE를 좋아 보이게 만들 수 있다. 본업 이익의 지속성을 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(301,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','기업 H는 PER 30배, ROE 5%인데 매출 성장도 둔화되고 있다. 적절한 해석은?','높은 PER은 높은 기대를 반영할 수 있다. 낮은 ROE와 성장 둔화가 함께 보이면 기대가 과한지 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(302,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','기업 I의 PER은 전년 20배에서 10배로 낮아졌지만 EPS가 일회성 이익으로 급증했다. 적절한 판단은?','PER은 EPS의 영향을 받는다. 일회성 이익으로 EPS가 늘면 PER이 낮아 보여도 지속성이 약할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(303,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','PER과 ROE는 하나로 합산해 공식 점수처럼 해석하는 지표다.','틀리다. PER과 ROE는 각각 가격 수준과 수익성을 보여주는 별도 지표다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(304,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','기업 J의 PER은 11배, ROE는 16%이고 부채비율도 낮다. 그래도 추가로 볼 내용은?','PER과 ROE가 좋아 보여도 투자 판단에는 성장성, 현금흐름, 산업 환경이 필요하다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(305,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','기업 K와 L의 PER은 모두 12배다. K의 ROE는 20%, L의 ROE는 6%라면?','PER이 같아도 ROE가 다르면 수익성의 질이 다를 수 있다. 같은 업종과 재무구조를 함께 비교해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(306,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','PER과 ROE를 볼 때 업종과 기업의 이익 지속성을 함께 고려해야 한다.','맞다. 두 지표 모두 업종 특성과 이익의 질에 따라 해석이 달라질 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(307,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','매출 성장률의 의미로 가장 적절한 것은?','매출 성장률은 매출이 이전 기간보다 얼마나 증가하거나 감소했는지를 나타내는 비율이다. 영업이익, 이익률, 성장 원인, 일회성 요인, 업종 평균과 함께 봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(308,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','작년 매출이 100억 원, 올해 매출이 130억 원이라면 매출 성장률은?','매출 성장률은 (올해 매출-작년 매출)을 작년 매출로 나눠 구한다. (130억-100억)을 100억으로 나누면 30%다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(309,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','A기업 매출 성장률은 30%로 높지만 영업이익은 오히려 감소했다. 가장 적절한 확인 사항은?','매출 성장률은 외형 성장만 보여준다. 영업이익, 이익률, 성장 원인, 일회성 요인을 함께 봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(310,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','B기업 매출은 20% 늘었지만 매출채권이 그보다 더 빠르게 늘었다. 무엇을 점검해야 하는가?','매출 성장은 현금 회수와 함께 봐야 한다. 매출채권 급증은 회수 지연 가능성을 시사할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(311,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','C기업 매출 성장률은 25%, 업종 평균은 8%다. 가장 적절한 다음 확인은?','높은 매출 성장률도 원인과 지속성이 중요하다. 가격, 판매량, 일회성 계약을 구분해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(312,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','D기업과 E기업의 매출 성장률이 똑같이 15%다. D기업은 판매량 증가로, E기업은 가격 인상만으로 성장했다면?','같은 매출 성장률이라도 판매량 증가에 의한 성장과 가격 인상에 의한 성장은 지속 가능성이 다를 수 있다. 성장의 질을 함께 살펴야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(313,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','F기업 매출 성장률은 40%인데 EPS는 오히려 감소했다. 가장 적절한 해석은?','매출이 늘어도 원가나 비용, 일회성 손실로 인해 이익과 EPS는 오히려 줄어들 수 있다. 매출과 이익의 흐름을 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(314,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','매출 성장률 해석에 대한 설명 중 옳지 않은 것은?','매출 성장률이 높아도 영업이익과 현금흐름이 함께 개선되지 않으면 성장의 질을 의심해봐야 한다. 여러 지표를 함께 확인하는 것이 안전하다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(315,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','매출 성장률은 매출이 이전 기간보다 얼마나 증가하거나 감소했는지를 나타내는 비율이다.','맞다. 매출 성장률은 외형 성장을 보여주는 지표로, 이익 지표와 함께 해석해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(316,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','매출 성장률이 업종 평균보다 높으면 다른 지표를 확인하지 않아도 항상 좋은 투자 대상이다.','틀리다. 성장의 원인과 지속 가능성, 이익으로의 연결 여부를 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(317,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','G기업은 대규모 일회성 계약 하나로 이번 분기 매출이 급증해 성장률이 60%를 기록했다. 가장 적절한 판단은?','일회성 계약으로 인한 매출 급증은 다음 분기에 반복되지 않을 수 있다. 반복 가능한 매출을 기준으로 성장의 지속 가능성을 판단해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(318,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','매출 성장률 해석의 한계로 가장 적절한 것은?','매출 성장률은 외형의 성장을 보여줄 뿐 수익성이나 현금흐름까지 설명하지 않는다. 영업이익률, 현금흐름 등을 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(319,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','매출 성장률이 높은 기업을 평가할 때 추가로 확인하면 좋은 정보는?','매출 성장률이 높아도 영업이익률, 매출채권 변화, 성장의 지속 가능성을 함께 봐야 실제 기업가치 개선 여부를 판단할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(320,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','H기업 매출은 전년과 동일한데 영업이익률이 크게 개선됐다. 가장 적절한 해석은?','매출이 늘지 않아도 원가 절감이나 비용 효율화로 영업이익률이 개선될 수 있다. 개선의 원인이 일시적인지 구조적인지 확인하는 것이 좋다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(321,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','I기업의 매출 성장률은 5%로 낮지만 영업이익률은 업종 평균보다 크게 높다. 가장 적절한 해석은?','매출 성장률과 영업이익률은 서로 다른 정보를 준다. 성장은 더뎌도 수익성이 우수한 기업일 수 있어 두 지표를 함께 비교해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(322,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','J기업의 매출 성장률이 3분기 연속 둔화되고 있다. 가장 적절한 다음 확인은?','매출 성장률 둔화는 업황, 경쟁 강도, 일시적 요인 등 다양한 원인에서 비롯될 수 있다. 원인을 확인해야 향후 전망을 더 합리적으로 판단할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(323,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','매출 성장률을 해석할 때는 영업이익률, 현금흐름, 성장의 지속 가능성을 함께 확인하는 것이 좋다.','맞다. 매출 성장률은 외형 지표이므로 수익성과 현금흐름 지표를 함께 봐야 온전한 해석이 가능하다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(324,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','영업이익률의 의미로 가장 적절한 것은?','영업이익률은 매출에서 본업의 영업이익이 차지하는 비율이다. 매출 변화, 비용 구조, 원가, 일회성 비용, 업종 평균과 함께 해석해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(325,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','매출이 200억 원이고 영업이익이 24억 원이라면 영업이익률은?','영업이익률은 영업이익을 매출로 나눠 구한다. 24억 원을 200억 원으로 나누면 12%다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(326,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','K기업 영업이익률이 하락했지만 매출은 증가했다. 가장 적절한 해석은?','영업이익률은 본업의 수익성을 보여준다. 매출 변화, 비용 구조, 원가, 일회성 비용을 함께 봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(327,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','L기업과 M기업의 영업이익률이 똑같이 15%다. L기업은 원가 절감으로, M기업은 판매가 인상으로 이 수치를 냈다면?','같은 영업이익률이라도 원가 절감과 판매가 인상은 지속 가능성과 경쟁력 측면에서 다르게 평가될 수 있다. 개선의 배경을 함께 살펴야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(328,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','영업이익률에 대한 설명 중 옳지 않은 것은?','업종 평균보다 높은 영업이익률도 일회성 요인의 영향을 받을 수 있어 원인을 확인해야 한다. 지속 가능한 경쟁력에서 비롯된 것인지 살펴봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(329,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','영업이익률은 매출에서 본업의 영업이익이 차지하는 비율이다.','맞다. 영업이익률은 매출 대비 본업의 수익성을 보여주는 대표적인 지표다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(330,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','영업이익률이 업종 평균보다 높으면 원인과 관계없이 항상 지속 가능한 경쟁력을 의미한다.','틀리다. 일회성 비용 감소나 일시적 가격 상황으로 영업이익률이 높아졌을 수 있어 원인을 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(331,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','N기업은 일회성 자산 매각 이익 덕분에 이번 분기 영업이익률이 크게 개선됐다. 가장 적절한 판단은?','일회성 이익은 그 분기의 영업이익률을 높이지만 반복되지 않는다. 본업에서 나온 이익 기준으로 지속 가능성을 다시 판단해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(332,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','영업이익률 해석의 한계로 가장 적절한 것은?','영업이익률은 본업의 수익성을 보여줄 뿐 매출 규모나 현금흐름, 재무 안정성까지 설명하지 않는다. 다른 지표와 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(333,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','영업이익률이 개선된 기업을 평가할 때 추가로 확인하면 좋은 정보는?','영업이익률 개선의 원인이 무엇인지에 따라 그 효과가 지속될지, 일시적일지가 달라진다. 원인을 구체적으로 확인하는 것이 중요하다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(334,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','O기업은 매출은 줄었지만 판관비를 크게 줄여 영업이익률은 오히려 개선됐다. 가장 적절한 해석은?','비용 절감을 통한 이익률 개선은 단기적으로 긍정적일 수 있지만, 매출 감소가 계속되면 장기 성장에는 부담이 될 수 있다. 매출과 이익률을 함께 봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(335,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','영업이익률 개선의 원인이 본업 경쟁력 강화인지 일회성 요인인지 확인하는 것이 좋다.','맞다. 원인에 따라 개선 효과가 지속될지 일시적일지가 달라지므로 확인이 필요하다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(336,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','영업이익률이 하락했지만 매출은 증가했다. 가장 적절한 해석은?','영업이익률은 본업의 수익성을 보여준다. 매출 변화, 비용 구조, 원가, 일회성 비용을 함께 봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(337,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','영업이익률을 해석할 때 기준 기간이나 조건을 확인하는 것이 좋다.','맞다. 영업이익률은 기준과 조건에 따라 의미가 달라질 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(338,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','A기업 영업이익률은 18%, 업종 평균은 10%다. 가장 적절한 확인은?','영업이익률이 높아도 원인을 확인해야 한다. 반복 가능한 경쟁력인지 일시적 비용 감소인지 구분해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(339,4,2,6,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','원재료 가격이 급등했는데 영업이익률이 유지됐다. 확인할 내용은?','원가 상승에도 마진이 유지되면 가격 전가나 비용 절감이 있었을 수 있다. 지속 가능성을 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-27 07:14:52'),(340,5,2,7,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','용어 \'추세\'를 분석할 때 가장 적절한 출발점은?','\'추세\'의 핵심은 주가가 일정 기간 지속해서 진행하는 전반적인 방향이다. 이후 기간별 변화와 비교 대상을 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-14 00:45:19'),(341,5,2,7,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','기업 A의 \'추세\' 수치가 개선되었다. 가장 타당한 추가 확인은?','개념 \'추세\'는 주가가 일정 기간 지속해서 진행하는 전반적인 방향이다. 개선 여부는 비교 기준과 지속성, 일회성 요인을 함께 검토해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-14 00:45:19'),(342,5,2,7,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','용어 \'추세\'를 실제 투자 판단에 활용하는 방법으로 가장 적절한 것은?','중급 분석에서는 용어 \'추세\'를 단독 신호로 쓰지 않고 다른 자료와 교차 확인한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-14 00:45:19'),(343,5,2,7,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','개념 \'추세\'와 용어 \'지지선\'를 함께 해석한 설명으로 가장 적절한 것은?','두 정보는 서로 다른 측면을 보여준다. 함께 사용할 때 단일 지표의 한계를 줄일 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-14 00:45:19'),(344,5,2,7,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','\'추세\'의 한 번의 변화만으로 장기 추세를 확정할 수 있다.','틀리다. 개념 \'추세\'는 주가가 일정 기간 지속해서 진행하는 전반적인 방향이지만 여러 기간의 지속성과 다른 자료를 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-14 00:45:19'),(345,5,2,7,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','\'추세\' 관련 정보가 발표되었다. 가장 합리적인 분석 절차는?','개념 \'추세\'는 주가가 일정 기간 지속해서 진행하는 전반적인 방향이다. 내용의 구체성과 가격 반영 여부를 함께 봐야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-14 00:45:19'),(346,5,2,7,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','다음 중 \'추세\' 분석에서 발생하기 쉬운 오류를 피하는 방법은?','수치의 방향뿐 아니라 원인, 지속성, 비교 기준을 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-14 00:45:19'),(347,5,2,7,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'OX','개념 \'추세\'는 투자 판단의 보조 자료이며 결과를 확정하는 신호는 아니다.','맞다. 개념 \'추세\'는 주가가 일정 기간 지속해서 진행하는 전반적인 방향이며 다른 자료와 함께 해석해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-14 00:45:19'),(348,5,2,7,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','두 기업의 용어 \'추세\'를 비교할 때 우선 확인할 사항은?','비교 가능한 기준을 맞춰야 수치 차이가 기업 특성 때문인지 기간·단위 차이 때문인지 구분할 수 있다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-14 00:45:19'),(349,5,2,7,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','기본 개념을 확인한다. 용어 \'추세\'를 분석할 때 가장 적절한 출발점은?','\'추세\'의 핵심은 주가가 일정 기간 지속해서 진행하는 전반적인 방향이다. 이후 기간별 변화와 비교 대상을 함께 확인해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-14 00:45:19'),(350,5,2,7,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUAL','ACTIVE',NULL,NULL,NULL,NULL,NULL,'MULTIPLE_CHOICE','기본 개념을 확인한다. 기업 A의 \'추세\' 수치가 개선되었다. 가장 타당한 추가 확인은?','개념 \'추세\'는 주가가 일정 기간 지속해서 진행하는 전반적인 방향이다. 개선 여부는 비교 기준과 지속성, 일회성 요인을 함께 검토해야 한다.',1000,'ACTIVE','2026-08-14 00:45:19','2026-08-14 00:45:19'),(351,5,2,7,NULL,'DEFAULT','GENERAL','PUBLIC',NULL,'MANUA