CREATE TABLE `ranking_entries` (
  `entry_id` bigint NOT NULL AUTO_INCREMENT,
  `season_id` int NOT NULL,
  `user_id` int NOT NULL,
  `final_return_rate` decimal(10,4) DEFAULT NULL,
  `final_rank` int DEFAULT NULL,
  `joined_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`entry_id`),
  UNIQUE KEY `uk_ranking_entries_season_user` (`season_id`,`user_id`),
  KEY `fk_ranking_entries_user` (`user_id`),
  CONSTRAINT `fk_ranking_entries_season` FOREIGN KEY (`season_id`) REFERENCES `ranking_seasons` (`season_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ranking_entries_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
